  ui_story_5028_50280101_51_dialog_content = "(Isso é uma merda! Eu quase consegui.)",
  ui_story_5028_50280101_52_dialog_content = "(Mas não posso persegui-lo, preciso ver o que Kyllo está reclamando.)",
  ui_story_5028_50280101_X52_dialog_content = "(Espera aí... Por que está gritando assim?)",
  ui_story_5028_50280101_X53_dialog_content = "(Está gritando como um coro de corvos. Perderá a voz nesse ritmo.)",
