  ui_story_5028_50280101_54_dialog_content = "...",
  ui_story_5028_50280101_55_dialog_content = "Ei! Ei!",
  ui_story_5028_50280101_56_dialog_content = "Certo, Kyllo, estou indo. Você pode parar de chamar.",
  ui_story_5028_50280101_57_dialog_content = "Y-Você subiu em uma árvore?",
  ui_story_5028_50280101_58_dialog_content = "Ei...",
  ui_story_5028_50280101_59_dialog_content = "...",
  ui_story_5028_50280101_60_dialog_content = "Seriamente...",
  ui_story_5028_50280101_61_dialog_content = "Olha o tamanho de você! Você está com medo de um coelhinho?",
  ui_story_5028_50280101_62_dialog_content = "Ei...",
  ui_story_5028_50280101_63_dialog_content = "Não acredito que você assustou o Pangalo por isso.",
  ui_story_5028_50280101_64_dialog_content = "Você é um mau Kyllo. Acho que vou te deixar lá em cima!",
  ui_story_5028_50280101_65_dialog_content = "Ei...",
  ui_story_5028_50280101_66_dialog_content = "Lo, lo.",
  ui_story_5028_50280101_67_dialog_content = "Oh, não me dê esse olhar. Eu só estava brincando.",
  ui_story_5028_50280101_68_dialog_content = "Sr. Coelho, posso incomodá-lo para pular um pouco?",
  ui_story_5028_50280101_69_dialog_content = "Você parece estar assustando meu amigo.",
  ui_story_5028_50280101_70_dialog_content = "?!",
  ui_story_5028_50280101_71_dialog_content = "Oh não, eu não quis dizer que você era assustador!",
  ui_story_5028_50280101_72_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5028_50280101_73_dialog_content = "Ei, você aí! Saia daqui!",
  ui_story_5028_50280101_74_dialog_content = "Olha a bagunça que você fez! Por que você teve que me fazer levar Kyllo junto?",
  ui_story_5028_50280101_75_dialog_content = "É mais problema do que vale a pena, completamente inútil!",
  ui_story_5028_50280101_76_dialog_content = "Que raquete! Quem está fazendo tanto barulho?",
  ui_story_5028_50280101_77_dialog_content = "O carteiro? O reparador?",
  ui_story_5028_50280101_78_dialog_content = "Sou eu! Seu aprendiz.",
  ui_story_5028_50280101_79_dialog_content = "Meu aprendiz? Qual deles?",
  ui_story_5028_50280101_80_dialog_content = "Vic",
  ui_story_5028_50280101_X80_dialog_content = "18 anos de idade?",
  ui_story_5028_50280101_81_dialog_content = "Um vagabundo cansado e desempregado.",
  ui_story_5028_50280101_82_dialog_content = "É Fia! Fia!!!",
  ui_story_5028_50280101_83_dialog_content = "Você está bêbado? Você ainda se lembra do seu próprio nome?",
  ui_story_5028_50280101_83X_dialog_content = "Isso é facil. O nome é Vic.",
  ui_story_5028_50280101_83X1_dialog_content = "Não foi o que eu quis dizer...",
  ui_story_5028_50280101_84_dialog_content = "Oh! Fia, você está de volta.",
  ui_story_5028_50280101_85_dialog_content = "Eu me lembro agora, você foi para... Foi...",
  ui_story_5028_50280101_86_dialog_content = "Coletando esterco de Linmaphant? Era isso?",
  ui_story_5028_50280101_87_dialog_content = "Quem iria querer esterco de Linmaphant!?",
  ui_story_5028_50280101_88_dialog_content = "Fui pegar Pangalo.",
  ui_story_5028_50280101_89_dialog_content = "Claro, Pangalo pegando. E você conseguiu um?",
  ui_story_5028_50280101_90_dialog_content = "Ah, eu estava tão perto. Mas adivinhe!",
  ui_story_5028_50280101_91_dialog_content = "Kyllo continuou estragando tudo para mim. O Pangalo escapou no final.",
  ui_story_5028_50280101_S91_dialog_content = "Ah, escapou. Que pena. E, por que você queria um de novo? Lembre-me.",
  ui_story_5028_50280101_S92_dialog_content = "Para que eu pudesse observar seu comportamento, duh! Essa foi a lição de casa que você me deu!",
  ui_story_5028_50280101_S93_dialog_content = "Oh. Bem, então você pode anotar isso em seu diário: \"Os Pangalos são tímidos e têm medo das pessoas.\"",
  ui_story_5028_50280101_S94_dialog_content = "O que, e é isso?",
  ui_story_5028_50280101_S95_dialog_content = "O resto virá com o tempo. Lembra o que eu te disse? O estudo das bestas maravilhosas começa por respeitá-las.",
  ui_story_5028_50280101_S96_dialog_content = "Respeitando seus comportamentos e humores estranhos e seus habitats.",
  ui_story_5028_50280101_S97_dialog_content = "Estudar, mas não interferir. Essa é a chave para se tornar um extrozoólogo.",
  ui_story_5028_50280101_92_dialog_content = "Esse, Fia, é o caminho para o conhecimento. Ah, você tem muito o que aprender.",
  ui_story_5028_50280101_93_dialog_content = "Ah, isso de novo. Eu sei eu sei. Você sabe que as pessoas chamam isso de \"exibir sua antiguidade\", certo?",
  ui_story_5028_50280101_94_dialog_content = "Você está me chamando de velho?",
  ui_story_5028_50280101_X94_dialog_content = "Homens bonitos como eu não envelhecem. Nós amadurecemos.",
  ui_story_5028_50280101_X95_dialog_content = "(Nossa, que fanfarrão. Por que eu ainda o escuto?)",
  ui_story_5028_50280101_95_dialog_content = "O que eu não entendo é por que você queria que eu levasse Kyllo?",
  ui_story_5028_50280101_96_dialog_content = "Eu... Nós não trabalhamos bem juntos. Não é o parceiro certo para mim.",
  ui_story_5028_50280101_97_dialog_content = "Eu não posso fazer nada quando está lá, muito menos me tornar um <color=#FFB400>extrozoologista</color>!",
  ui_story_5028_50280101_98_dialog_content = "Porque você não pode se comunicar com ele, certo?",
  ui_story_5028_50280101_99_dialog_content = "...",
  ui_story_5028_50280101_100_dialog_content = "Sim.",
  ui_story_5028_50280101_102_dialog_content = "Sua capacidade de se comunicar com os animais é um presente. Mas não seria sábio confiar demais nele.",
  ui_story_5028_50280101_103_dialog_content = "Por exemplo, você pode entender os aurorianos. Mas apenas ser capaz de entender todo mundo significa que você pode ser amigo deles?",
  ui_story_5028_50280101_104_dialog_content = "Oh, desculpe. Esqueci, você não tem amigos.",
  ui_story_5028_50280101_105_dialog_content = "Você-",
  ui_story_5028_50280101_106_dialog_content = "Você também não tem! Não seja todo presunçoso!",
  ui_story_5028_50280101_107_dialog_content = "A amizade funciona de forma diferente para os adultos. Você não entenderia.",
  ui_story_5028_50280101_108_dialog_content = "Huh. Bem, se os adultos fazem amigos saindo em bares se gabando o tempo todo...",
  ui_story_5028_50280101_109_dialog_content = "E-Isso foi...",
  ui_story_5028_50280101_110_dialog_content = "E então fazer seu aprendiz pagar a conta para eles!",
  ui_story_5028_50280101_111_dialog_content = "É isso que todos os perdedores de meia-idade fazem?",
  ui_story_5028_50280101_112_dialog_content = "Falido, desempregado, espreguiçando em casa o dia todo!",
  ui_story_5028_50280101_113_dialog_content = "Ok, isso é o suficiente! E quem é um perdedor de meia-idade?",
  ui_story_5028_50280101_S113_dialog_content = "Como mais se chama alguém que depende de seu aprendiz para sobreviver?",
  ui_story_5028_50280101_S114_dialog_content = "Eu tenho que preparar as refeições de um dia inteiro para você antes de sair. Então, quando eu voltar, eu tenho que limpar a bagunça feita por todos os seus amiguinhos correndo.",
  ui_story_5028_50280101_S115_dialog_content = "Talvez você gostaria de tentar cuidar de si mesmo? Você sabe, adulto?",
  ui_story_5028_50280101_S116_dialog_content = "Você... Você...",
  ui_story_5028_50280101_114_dialog_content = "Eu ainda sou seu mentor, não sou? Você não deveria falar um pouco mais gentilmente?",
  ui_story_5028_50280101_X114_dialog_content = "Tudo bem, eu vou ser um pouco mais gentil...",
  ui_story_5028_50280101_X115_dialog_content = "(Não, espere! Fia, você está certo!)",
  ui_story_5028_50280101_X116_dialog_content = "(E se você mostrar fraqueza agora, isso acontecerá novamente.)",
  ui_story_5028_50280101_X117_dialog_content = "(Eu preciso ser corajoso. Sim, é isso. Corajoso!)",
  ui_story_5028_50280101_115_dialog_content = "Você nem leva minhas aulas a sério!",
  ui_story_5028_50280101_116_dialog_content = "Você apenas fica em casa e me manda fazer recados sozinho.",
  ui_story_5028_50280101_117_dialog_content = "E para adicionar insulto à injúria, agora eu tenho que fazer isso com Kyllo me segurando.",
  ui_story_5028_50280101_118_dialog_content = "Você poderia pelo menos explicar o porquê!",
  ui_story_5028_50280101_119_dialog_content = "Está bem, está bem. Eu entendo que as crianças lutam para controlar seu temperamento.",
  ui_story_5028_50280101_120_dialog_content = "Alguma vez você já se perguntou por que você pode se comunicar com todos os animais, exceto este?",
  ui_story_5028_50280101_121_dialog_content = "Não...",
  ui_story_5028_50280101_122_dialog_content = "Porque Kylo...",
  ui_story_5028_50280101_123_dialog_content = "Kylo é um <color=#FFB400>exótico</color>!",
  ui_story_5028_50280101_124_dialog_content = "Exótico!?",
  ui_story_5028_50280101_125_dialog_content = "Lo?",
  ui_story_5028_50280101_126_dialog_content = "As bestas maravilhosas que estudamos são as criaturas mais raras e únicas da natureza.",
  ui_story_5028_50280101_X126_dialog_content = "Sua natureza única decorre das diferentes maneiras pelas quais eles usam Lumina.",
  ui_story_5028_50280101_X127_dialog_content = "Mas os exóticos são os mais raros entre os animais maravilhosos e têm muito mais poderes.",
  ui_story_5028_50280101_127_dialog_content = "Então, por que parece um grande idiota?",
  ui_story_5028_50280101_128_dialog_content = "Porque, criança boba, ainda é jovem.",
  ui_story_5028_50280101_129_dialog_content = "Os exóticos devem passar por um processo de metamorfose durante seu crescimento. eu chamo isso <color=#FFB400>\"evolução.\"</color>",
  ui_story_5028_50280101_130_dialog_content = "E assim que Kyllo evoluir, ele será mais poderoso do que você pode imaginar.",
  ui_story_5028_50280101_131_dialog_content = "Você quer dinheiro? Ele vai transformar pedras em ouro.",
  ui_story_5028_50280101_132_dialog_content = "Você quer força? Ele vai destruir exércitos e devastar Lumopolis, sem sequer suar a camisa.",
  ui_story_5028_50280101_133_dialog_content = "Você quer poder? O medo que Kyllo inspira fará até a Rainha do Norte inclinar a cabeça.",
  ui_story_5028_50280101_134_dialog_content = "Ora, entregá-lo a você foi um grande sacrifício da minha parte!",
  ui_story_5028_50280101_135_dialog_content = "Mas o que posso dizer? Tal altruísmo está na minha natureza.",
  ui_story_5028_50280101_136_dialog_content = "...",
  ui_story_5028_50280101_137_dialog_content = "Você está se gabando de novo.",
  ui_story_5028_50280101_138_dialog_content = "O que? Como você pode dizer uma coisa dessas?",
  ui_story_5028_50280101_139_dialog_content = "Já ouvi tantas vezes.",
  ui_story_5028_50280101_140_dialog_content = "No ano passado você disse que ia comprar um dirigível e me levar de férias.",
  ui_story_5028_50280101_141_dialog_content = "Arrumei minhas malas e esperei e esperei. E o que eu ganhei? Balões!",
  ui_story_5028_50280101_142_dialog_content = "Bem... porque eu não sabia que os dirigíveis eram tão caros...",
  ui_story_5028_50280101_143_dialog_content = "Então, no inverno, você me disse que eu precisava aprender tudo sobre Thornpoises para um assunto importante.",
  ui_story_5028_50280101_144_dialog_content = "Levei três dias para encontrar um. Em seguida, uma noite inteira para pegá-lo.",
  ui_story_5028_50280101_145_dialog_content = "E o que aconteceu? Você usou para esfregar seus sapatos!",
  ui_story_5028_50280101_146_dialog_content = "Ah bem, isso...",
  ui_story_5028_50280101_147_dialog_content = "E de acordo com você, você não é apenas aparentemente um nobre, você também é um cantor famoso que só foi capaz de estudar bestas maravilhosas depois de deixar milhares de fãs fanáticos escaparem!",
  ui_story_5028_50280101_148_dialog_content = "Mas é tudo falso! Nada além de mentiras!",
  ui_story_5028_50280101_149_dialog_content = "Aposto que você está mentindo desta vez também!",
  ui_story_5028_50280101_X149_dialog_content = "(É enlouquecedor! Eu trabalho tanto e ele só... Ele só...)",
  ui_story_5028_50280101_X150_dialog_content = "Fia, espere um momento.",
  ui_story_5028_50280101_150_dialog_content = "<size=50>Eu quero tanto ser um extrozoólogo!</size>",
  ui_story_5028_50280101_151_dialog_content = "Mas não estou aprendendo nada e, em vez disso, sou sobrecarregado com um caloteiro...",
  ui_story_5028_50280101_152_dialog_content = "Eu estaria melhor sozinho!",
  ui_story_5028_50280101_153_dialog_content = "...",
  ui_story_5028_50280101_154_dialog_content = "Ah, agora entendi.",
  ui_story_5028_50280101_155_dialog_content = "Então você acha que eu não tenho mais nada para te ensinar?",
  ui_story_5028_50280101_156_dialog_content = "Ah, hã...",
  ui_story_5028_50280101_157_dialog_content = "Você é dotado. E talvez minha pedagogia esteja de fato um pouco desatualizada.",
  ui_story_5028_50280101_158_dialog_content = "Mas pensei que o estava treinando para ser um extrozoologista competente.",
  ui_story_5028_50280101_159_dialog_content = "Eu fiz você tentar as coisas por conta própria porque a experiência prática é vital.",
  ui_story_5028_50280101_160_dialog_content = "Eu esperava que você desenvolvesse habilidades independentes de resolução de problemas.",
  ui_story_5028_50280101_161_dialog_content = "Mas vejo agora que entendi tudo errado.",
  ui_story_5028_50280101_162_dialog_content = "Quer dizer, eu não estava...",
  ui_story_5028_50280101_163_dialog_content = "É verdade. Você é um gênio capaz de se comunicar com os animais. Você não precisa de educação estranha.",
  ui_story_5028_50280101_164_dialog_content = "Acho que é hora de terminar seu aprendizado.",
  ui_story_5028_50280101_165_dialog_content = "Quê?!",
  ui_story_5028_50280101_166_dialog_content = "Você não precisa mais dos meus ensinamentos.",
  ui_story_5028_50280101_167_dialog_content = "Mas... não foi isso que eu quis dizer...",
  ui_story_5028_50280101_168_dialog_content = "Kyllo aqui pode acompanhá-lo em sua graduação.",
  ui_story_5028_50280101_169_dialog_content = "Lo?",
  ui_story_5028_50280101_170_dialog_content = "Hã?",
  ui_story_5028_50280101_171_dialog_content = "Finalmente, eu realmente espero que você seja capaz de realizar seus sonhos.",
  ui_story_5028_50280101_172_dialog_content = "Eu lhe darei Kyllo, este exótico, como presente de despedida.",
  ui_story_5028_50280101_173_dialog_content = "Se você puder ajudá-lo a evoluir, significará que você é digno do nome de extrozoólogo.",
  ui_story_5028_50280101_174_dialog_content = "Que essa seja minha lição final para você.",
  ui_story_5028_50280101_175_dialog_content = "Mestre...",
  ui_story_5028_50280101_176_dialog_content = "Ah, não chore. Eu pensei que você sempre quis ser um extrozoologista.",
  ui_story_5028_50280101_177_dialog_content = "Simplesmente ajude Kyllo a evoluir e volte aqui para encerrar formalmente seu aprendizado. Feito. Sonho alcançado.",
  ui_story_5028_50280101_178_dialog_content = "E quanto a mim, o mentor que você acha tão carente... Apenas me deixe morrer de velhice sozinho.",
  ui_story_5028_50280101_179_dialog_content = "Mestre, você...",
  ui_story_5028_50280101_180_dialog_content = "Você ainda não me disse como ajudar Kyllo a evoluir.",
  ui_story_5028_50280101_181_dialog_content = "...",
  ui_story_5028_50280101_182_dialog_content = "Ah, é com isso que você está preocupado?",
  ui_story_5028_50280101_183_dialog_content = "Com o que você achou que eu estava preocupado?",
  ui_story_5028_50280101_184_dialog_content = "Porque você quer se tornar um extrozoólogo?",
  ui_story_5028_50280101_185_dialog_content = "Sim! É o meu sonho.",
  ui_story_5028_50280101_186_dialog_content = "T-Não há mais nada que você gostaria de me dizer?",
  ui_story_5028_50280101_187_dialog_content = "Oh, eu tenho algo a dizer!",
  ui_story_5028_50280101_188_dialog_content = "Você não está mentindo para mim de novo, está?",
  ui_story_5028_50280101_189_dialog_content = "Você-",
  ui_story_5028_50280101_190_dialog_content = "Tem certeza de que sabe alguma coisa sobre evolução exótica?",
  ui_story_5028_50280101_191_dialog_content = "É mesmo uma coisa real?",
  ui_story_5028_50280101_192_dialog_content = "Claro que existe tal coisa!",
  ui_story_5028_50280101_193_dialog_content = "Quando eu menti para você?",
  ui_story_5028_50280101_194_dialog_content = "...",
  ui_story_5028_50280101_195_dialog_content = "Ok, bem, desta vez estou sendo honesto.",
  ui_story_5028_50280101_196_dialog_content = "Mas evoluir exóticos é um desafio. Não tenho métodos infalíveis.",
  ui_story_5028_50280101_197_dialog_content = "Aqui, tome minhas notas.",
  ui_story_5028_50280101_198_dialog_content = "Nossa!",
  ui_story_5028_50280101_199_dialog_content = "Eu escrevi alguns testes cuidadosamente planejados.",
  ui_story_5028_50280101_200_dialog_content = "Tenha isso em mente: a experiência prática é mais importante.",
  ui_story_5028_50280101_201_dialog_content = "Se você completar esses testes, poderá evoluir o Kyllo.",
  ui_story_5028_50280101_202_dialog_content = "Acredite em si mesmo e um dia você se tornará...",
  ui_story_5028_50280101_203_dialog_content = "Agradável. Obrigado, mestre!",
  ui_story_5028_50280101_204_dialog_content = "Estou fora então! Tchau!",
  ui_story_5028_50280101_205_dialog_content = "Espere! eu não terminei...",
  ui_story_5028_50280101_206_dialog_content = "<color=#e8d9bb>Bater!</color>",
  ui_story_5028_50280101_207_dialog_content = "Extrozoologista...",
  ui_story_5028_50280101_208_dialog_content = "Você pode realmente evoluir, Kyllo?",
  ui_story_5028_50280101_209_dialog_content = "Ei!",
  ui_story_5028_50280101_210_dialog_content = "Ok, vamos ver que provações esse meu mestre inútil me deu.",
  ui_story_5028_50280101_211_dialog_content = "\"Sobre a evolução dos exóticos\"",
  ui_story_5028_50280101_212_dialog_content = "\"Isenção de responsabilidade: este estudo foi projetado com base nas próprias experiências do autor.\"",
  ui_story_5028_50280101_213_dialog_content = "\"Eles devem servir apenas como sugestões. Os resultados não são garantidos.\"",
  ui_story_5028_50280101_214_dialog_content = "Nossa. Estou apenas na página um e ele já está se esquivando da responsabilidade.",
  ui_story_5028_50280101_215_dialog_content = "Mas... 1, 2, 3, 4... há muitas provações a serem enfrentadas.",
  ui_story_5028_50280101_216_dialog_content = "\"Prova 1: Pegue e faça amizade com um <color=#FFB400>celestita</color>.\"",
  ui_story_5028_50280101_217_dialog_content = "Um celestita? Eu me pergunto que tipo de animal é esse.",
  ui_story_5028_50280201_1_dialog_content = "Prova: Pegue um celestita",
  ui_story_5028_50280201_2_dialog_content = "PlayerName, quando podemos começar a jogar?",
  ui_story_5028_50280201_3_dialog_content = "Espere. Muito em breve.",
  ui_story_5028_50280201_4_dialog_content = "Por que não agora? Eu não posso esperar!",
  ui_story_5028_50280201_5_dialog_content = "Porque precisamos de espaço. Em algum lugar com uma grande área de terreno plano.",
  ui_story_5028_50280201_6_dialog_content = "Mas este lugar está cheio de obstáculos, então não podemos jogar bola aqui.",
  ui_story_5028_50280201_7_dialog_content = "Entendi.",
  ui_story_5028_50280201_8_dialog_content = "Então podemos andar mais rápido?",
  ui_story_5028_50280201_9_dialog_content = "Você está com tanta pressa, haha. Ok, ok, vamos nos mexer.",
  ui_story_5028_50280201_10_dialog_content = "<color=#e8d9bb>Barulho... Barulho...</color>",
  ui_story_5028_50280201_11_dialog_content = "Ok, então a seguir vou jogar a bola na sua direção. Use o bastão que você está segurando para atingi-lo.",
  ui_story_5028_50280201_12_dialog_content = "Rubyestá estudando culturas antigas e ela já me contou tudo sobre esse jogo!",
  ui_story_5028_50280201_13_dialog_content = "Basicamente, quanto mais você acertar a bola, melhor.",
  ui_story_5028_50280201_14_dialog_content = "Entendeu?",
  ui_story_5028_50280201_15_dialog_content = "Entendi! Acerte a bola com o taco.",
  ui_story_5028_50280201_16_dialog_content = "Ok! Vamos tentar.",
  ui_story_5028_50280201_17_dialog_content = "3, 2, 1!",
  ui_story_5028_50280201_18_dialog_content = "Bata-o!",
  ui_story_5028_50280201_19_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_5028_50280201_20_dialog_content = "Ei, por que você se esquivou?",
  ui_story_5028_50280201_21_dialog_content = "PlayerName, por que você me atacou?",
  ui_story_5028_50280201_22_dialog_content = "Isso não foi um ataque. Chama-se arremesso.",
  ui_story_5028_50280201_23_dialog_content = "Lançando?",
  ui_story_5028_50280201_24_dialog_content = "Sim. Eu lanço a bola para você. Você o acerta no ar com o bastão. É assim que o jogo funciona.",
  ui_story_5028_50280201_25_dialog_content = "Ok, entendi agora. Vamos fazer de novo.",
  ui_story_5028_50280201_26_dialog_content = "Legal. E não se preocupe se você perder. Isso é normal no início.",
  ui_story_5028_50280201_27_dialog_content = "OK.",
  ui_story_5028_50280201_28_dialog_content = "Prepare-se! 3, 2, 1—",
  ui_story_5028_50280201_29_dialog_content = "Bata-o!",
  ui_story_5028_50280201_30_dialog_content = "<color=#e8d9bb>Vuuush!</color>",
  ui_story_5028_50280201_31_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_5028_50280201_32_dialog_content = "Uau! Você acertou!!!",
  ui_story_5028_50280201_33_dialog_content = "Yay! Eu fiz isso!",
  ui_story_5028_50280201_34_dialog_content = "A bola foi tão longe!",
  ui_story_5028_50280201_35_dialog_content = "Sim! Isso é o que eles chamavam de \"home run\" no passado!",
  ui_story_5028_50280201_36_dialog_content = "Ei, Revy, talvez você seja natural nisso!",
  ui_story_5028_50280201_37_dialog_content = "Eu? Um natural?",
  ui_story_5028_50280201_38_dialog_content = "Sim! Isso foi incrível para um primeiro swing.",
  ui_story_5028_50280201_39_dialog_content = "Bater na bola é divertido.",
  ui_story_5028_50280201_40_dialog_content = "Então, o que acontece a seguir?",
  ui_story_5028_50280201_41_dialog_content = "Próximo...",
  ui_story_5028_50280201_42_dialog_content = "Er, acho que precisamos pegar a bola de volta.",
  ui_story_5028_50280201_43_dialog_content = "Uau, isso pode demorar um pouco. Realmente foi longe.",
  ui_story_5028_50280201_44_dialog_content = "Desculpe. Da próxima vez, serei mais gentil.",
  ui_story_5028_50280201_45_dialog_content = "Ah, não faça isso. Não é sua culpa. As regras dizem que você tem que acertar o mais longe possível.",
  ui_story_5028_50280201_46_dialog_content = "Então... vou pegar a bola. Eu corro mais rápido.",
  ui_story_5028_50280201_47_dialog_content = "Ela se foi por mais de cinco minutos, por que ela ainda não voltou?",
  ui_story_5028_50280201_48_dialog_content = "<color=#e8d9bb>Farfalhar...</color>",
  ui_story_5028_50280201_49_dialog_content = "Talvez ela não consiga encontrar a bola? Ou aconteceu alguma coisa com ela?",
  ui_story_5028_50280201_50_dialog_content = "acho que me lembro Vice dizendo que Eclipsites tinha aparecido por aqui.",
  ui_story_5028_50280201_51_dialog_content = "<color=#e8d9bb>Barulho... Barulho...</color>",
  ui_story_5028_50280201_52_dialog_content = "Embora um Eclipse comum não seja um desafio para Revy.",
  ui_story_5028_50280201_53_dialog_content = "Afinal, ela é Rev—",
  ui_story_5028_50280201_54_dialog_content = "Agora!",
  ui_story_5028_50280201_55_dialog_content = "Uma rede?!",
  ui_story_5028_50280201_56_dialog_content = "Kyllo, seu idiota! Você errou novamente.",
  ui_story_5028_50280201_57_dialog_content = "Ok, estamos sem opções. Carregar!",
  ui_story_5028_50280201_58_dialog_content = "Quem no mundo é você?! Estou avisando, não sou alguém com quem você queira mexer.",
  ui_story_5028_50280201_59_dialog_content = "E aquela auroriana que estava aqui esmaga cabeças de Eclipse com as próprias mãos como se fossem melancias!",
  ui_story_5028_50280201_60_dialog_content = "Aproxime-se e usarei minhas habilidades psíquicas para pedir ajuda.",
  ui_story_5028_50280201_61_dialog_content = "Habilidades psíquicas? Você é mesmo um celestita!",
  ui_story_5028_50280201_62_dialog_content = "Temos que impedi-lo de pedir ajuda!",
  ui_story_5028_50280201_63_dialog_content = "Kyllo, Plano B! Agora!",
  ui_story_5028_50280201_64_dialog_content = "Ei!",
  ui_story_5028_50280201_65_dialog_content = "Espere! O que é o Plano B?",
  ui_story_5028_50280201_66_dialog_content = "Estou falando sério. Dê mais um passo e eu vou pedir ajuda.",
  ui_story_5028_50280201_67_dialog_content = "Vai-",
  ui_story_5028_50280201_68_option_content = "Força—Ai!",
  ui_story_5028_50280201_69_dialog_content = "Isso dói!",
  ui_story_5028_50280201_70_dialog_content = "Lo lo lo!",
  ui_story_5028_50280201_71_dialog_content = "Bom trabalho, Kylo. Certo, recue pela floresta como planejado.",
  ui_story_5028_50280201_72_dialog_content = "Olá!",
  ui_story_5028_50280201_73_dialog_content = "P-Coloque-me no chão! Para onde você está me levando?!",
  ui_story_5028_50280201_74_dialog_content = "<anim type=Shake><size=45>Revy—Rev—!</size></anim>",
  ui_story_5028_50280201_76_dialog_content = "Voltei. Eu confundi um coelho com a bola e passei séculos atrás dela.",
  ui_story_5028_50280201_77_dialog_content = "Eh? Onde está a PlayerName?",
  ui_story_5028_50280201_78_dialog_content = "O morcego ainda está aqui. Oh eu sei! PlayerName deve querer que eu pratique rebater home runs.",
  ui_story_5028_50280201_79_dialog_content = "Eu não vou te decepcionar! Primeiro, 1.000 balanços de prática. Pronto, vai!",
  ui_story_5028_50280201_80_dialog_content = "Ei!",
  ui_story_5028_50280201_81_dialog_content = "Espere, espere, onde essa coisinha estranha está me levando?",
  ui_story_5028_50280201_82_dialog_content = "Apenas me coloque para baixo. Estou em agonia aqui! Acho que você quebrou minhas costas.",
  ui_story_5028_50280201_83_dialog_content = "Lo?",
  ui_story_5028_50280201_84_dialog_content = "Kylo, espera!",
  ui_story_5028_50280201_85_dialog_content = "Ufa... Você finalmente decidiu parar? Oi oi.",
  ui_story_5028_50280201_86_dialog_content = "Kyllo, essa era a rota que planejamos para o Plano B?",
  ui_story_5028_50280201_87_dialog_content = "Lo lo?",
  ui_story_5028_50280201_88_dialog_content = "Não me diga que você acabou de correr para a floresta ao acaso...",
  ui_story_5028_50280201_89_dialog_content = "Ei...",
  ui_story_5028_50280201_90_dialog_content = "Não há sinal do caminho por onde viemos... são apenas... árvores.",
  ui_story_5028_50280201_91_dialog_content = "V-vocês são loucos! Você sabia que este lugar está cheio de eclipsitas?",
  ui_story_5028_50280201_92_dialog_content = "Eclipsitas?",
  ui_story_5028_50280201_93_dialog_content = "Aahhhhhh!",
  ui_story_5028_50280201_94_dialog_content = "Olha, um realmente apareceu!",
  ui_story_5028_50280201_95_dialog_content = "Por que haveria... É um Eclipse!!!",
  ui_story_5028_50280201_96_dialog_content = "Não fique aí parado! Corre!",
  ui_story_5028_50280201_97_dialog_content = "Aaargh!",
  ui_story_5028_50280201_98_dialog_content = "Kyllo!",
  ui_story_5028_50280201_99_dialog_content = "Ei!",
  ui_story_5028_50280201_100_dialog_content = "Um eclipse? Como pode haver Eclipses aqui?",
  ui_story_5028_50280201_101_dialog_content = "Pare de pensar e corra!",
  ui_story_5028_50280201_102_dialog_content = "Ugh não, eu realmente não posso correr muito mais longe...",
  ui_story_5028_50280201_103_dialog_content = "Eu sou bom em falar com bestas maravilhosas. Mas Eclipses e tudo isso? Que nojo!",
  ui_story_5028_50280201_104_dialog_content = "Eu ainda não posso ser comido por um Eclipsite. Eu tenho que me tornar um extrozoologista primeiro!",
  ui_story_5028_50280201_105_dialog_content = "Pense, pense, deve haver uma maneira...",
  ui_story_5028_50280201_106_dialog_content = "O que o Mestre costumava dizer? Quando confrontado com o perigo, não chore. Acho.",
  ui_story_5028_50280201_107_dialog_content = "Talvez eu devesse ganhar algum tempo para Kyllo e a Caelestita fugirem.",
  ui_story_5028_50280201_108_dialog_content = "Mas não sei se sou forte o suficiente... Seja como for, terei que ser! Eu não posso segurá-los.",
  ui_story_5028_50280201_109_dialog_content = "Relaxe, sim? Você sabe mesmo lutar?",
  ui_story_5028_50280201_110_dialog_content = "*Soluço* Um pouco. Mas apenas para autodefesa, principalmente.",
  ui_story_5028_50280201_111_dialog_content = "Isso é bom! Os inimigos no início de uma aventura são sempre mais fracos.",
  ui_story_5028_50280201_112_dialog_content = "Destino. Isso é tudo que o destino é.",
  ui_story_5028_50280201_113_dialog_content = "Vou usar meus poderes para ajudá-lo!",
  ui_story_5028_50280201_114_dialog_content = "Se continuarmos correndo pela floresta, vamos atrair mais Eclipsitas.",
  ui_story_5028_50280201_114X_dialog_content = "Devemos lidar com eles nos seguindo e então decidir o que fazer.",
  ui_story_5028_50280201_115_dialog_content = "Mas são tantos...",
  ui_story_5028_50280201_116_dialog_content = "Confie em mim!",
  ui_story_5028_50280201_117_dialog_content = "E não estamos sozinhos! Tem seu amigo também. Se trabalharmos juntos, podemos vencê-los!",
  ui_story_5028_50280201_118_dialog_content = "Ei!",
  ui_story_5028_50280201_119_dialog_content = "*Sniff* Ok então.",
  ui_story_5028_50280201_120_dialog_content = "A propósito, você deve mostrar algum respeito! Eu sou o melhor extrozoologista do mundo, você sabe.",
  ui_story_5028_50280201_121_dialog_content = "Como você se atreve a tentar me assustar?",
  ui_story_5028_50280201_122_dialog_content = "Alinhe-se e prepare-se para uma surra!",
  ui_story_5028_50280202_1_dialog_content = "Uau. Na verdade, ganhamos!",
  ui_story_5028_50280202_2_dialog_content = "Incrível! Kyllo, você viu isso?",
  ui_story_5028_50280202_3_dialog_content = "Ei! Ei!",
  ui_story_5028_50280202_4_dialog_content = "Heehee. Eu não esperava que você fosse um lutador tão bom, Kyllo. Estou impressionado!",
  ui_story_5028_50280202_5_dialog_content = "Ei!",
  ui_story_5028_50280202_6_dialog_content = "(Eu deveria escapar enquanto eles estão ocupados parabenizando um ao outro.)",
  ui_story_5028_50280202_7_dialog_content = "Óh, e...",
  ui_story_5028_50280202_8_dialog_content = "(Mas ainda existem Eclipses por aí. Não estou mais seguro se for embora.)",
  ui_story_5028_50280202_9_dialog_content = "(*Suspirar*)",
  ui_story_5028_50280202_10_dialog_content = "Er, Sr. Caelestite?",
  ui_story_5028_50280202_11_dialog_content = "Tô aqui.",
  ui_story_5028_50280202_12_dialog_content = "Obrigado... por ajudar Kyllo e eu.",
  ui_story_5028_50280202_13_dialog_content = "Ah, não mencione isso. Não foi nada.",
  ui_story_5028_50280202_14_dialog_content = "Não há absolutamente nenhuma necessidade de me agradecer. Quer saber, por que não deixo vocês dois aqui? Eu só vou te segurar.",
  ui_story_5028_50280202_15_dialog_content = "Você não pode simplesmente ir embora, Sr. Caelestite.",
  ui_story_5028_50280202_16_dialog_content = "Não depois de me testemunhar em tal desordem.",
  ui_story_5028_50280202_17_dialog_content = "O-o que aconteceu agora? Onde é isso? Ah, eu perdi minha memória.",
  ui_story_5028_50280202_18_dialog_content = "E fingir amnésia não vai funcionar.",
  ui_story_5028_50280202_19_dialog_content = "Seja um bom menino e torne-se meu parceiro e animal de estimação, como Kyllo aqui. Fique por perto, ajude.",
  ui_story_5028_50280202_20_dialog_content = "(Heehee. E dando meu sorriso mais doce, eu prendo a Caelestita.)",
  ui_story_5028_50280202_21_dialog_content = "De jeito nenhum! Eu recuso.",
  ui_story_5028_50280202_22_dialog_content = "Hã?!",
  ui_story_5028_50280202_23_dialog_content = "Eu te ajudei agora porque era a coisa certa a fazer. Isso não faz de mim seu servo.",
  ui_story_5028_50280202_24_dialog_content = "E ainda precisamos discutir como essa besta Kyllo me derrubou e me sequestrou.",
  ui_story_5028_50280202_25_dialog_content = "Por que não nos ajudamos a sair dessa floresta primeiro? Então vamos chamá-lo de par e seguir nossos caminhos separados.",
  ui_story_5028_50280202_26_dialog_content = "*funga*",
  ui_story_5028_50280202_27_dialog_content = "(Foi muito duro?)",
  ui_story_5028_50280202_28_dialog_content = "(Não, não foi. A garota provavelmente está tentando me enganar. E eu também não confio nesse Kyllo.)",
  ui_story_5028_50280202_29_dialog_content = "*Soluço*",
  ui_story_5028_50280202_30_dialog_content = "Mas eu só... eu só queria um amigo...",
  ui_story_5028_50280202_31_dialog_content = "Ei...",
  ui_story_5028_50280202_32_dialog_content = "Todo mundo diz que eu só posso fazer amizade com bestas maravilhosas. Eu queria provar que isso não era verdade e que eu posso fazer amizade com Aurorains e Caelestites também.",
  ui_story_5028_50280202_33_dialog_content = "Eu só quero cumprir o último desejo do meu Mestre...",
  ui_story_5028_50280202_34_dialog_content = "(Seu Mestre? Aquele que ela acabou de mencionar? E último desejo? Ele está morto?)",
  ui_story_5028_50280202_35_dialog_content = "Atchim!",
  ui_story_5028_50280202_36_dialog_content = "Estou bem, pequena bola de pêlos. Talvez eu esteja ficando resfriado.",
  ui_story_5028_50280202_37_dialog_content = "Você está preocupado comigo? Então deixe-me usar você para limpar meu nariz, sim?",
  ui_story_5028_50280202_38_dialog_content = "Haha. Claro que eu estava brincando. Eu tenho que mantê-lo limpo para vender sua pele derramada aos clientes.",
  ui_story_5028_50280202_39_dialog_content = "(Ela não vai chorar de verdade, vai? Seus olhos estão todos vermelhos.)",
  ui_story_5028_50280202_40_dialog_content = "(Ela parece ainda mais jovem do que Revy e ela não é boa em lutar.)",
  ui_story_5028_50280202_40X_dialog_content = "(A vida na estrada deve ser difícil para ela.)",
  ui_story_5028_50280202_41_dialog_content = "É por isso que eu sequestrei você. Para que pudéssemos ser amigos.",
  ui_story_5028_50280202_42_dialog_content = "(Não chore. Não chore. Faça o que fizer, não chore.)",
  ui_story_5028_50280202_43_dialog_content = "Eu r-realmente sinto muito por fazer todas essas coisas terríveis com você. Eu realmente me arrependo.",
  ui_story_5028_50280202_44_dialog_content = "Se você realmente me odeia Sr. Caelestite, deixe-me aqui sozinho...",
  ui_story_5028_50280202_45_dialog_content = "Deixe-me aqui para morrer...",
  ui_story_5028_50280202_46_dialog_content = "Aaaaaaaaaaaaaaaa!",
  ui_story_5028_50280202_47_dialog_content = "Me desculpe, me desculpe!",
  ui_story_5028_50280202_48_dialog_content = "Me desculpe, eu não deveria ter sido tão má com você.",
  ui_story_5028_50280202_49_dialog_content = "Vocês queriam ser amigos, certo? Coisa certa! Eu estou PlayerName.",
  ui_story_5028_50280202_50_dialog_content = "S-realmente? Eu sou Fia!",
  ui_story_5028_50280202_51_dialog_content = "Certo, Fia, então somos amigos.",
  ui_story_5028_50280202_52_dialog_content = "Sério?",
  ui_story_5028_50280202_53_dialog_content = "Sério! Juro.",
  ui_story_5028_50280202_54_dialog_content = "Ei!",
  ui_story_5028_50280202_55_dialog_content = "Hehehe... Ei, PlayerName, isso faz de você meu primeiro amigo.",
  ui_story_5028_50280202_56_dialog_content = "Estou tão feliz que você é meu amigo!",
  ui_story_5028_50280202_57_dialog_content = "Veja, mestre! Eu fiz um amigo!",
  ui_story_5028_50280202_58_dialog_content = "Olá!",
  ui_story_5028_50280202_59_dialog_content = "(Nossa! Primeiro eu sou vítima das lágrimas, agora é o sorriso!)",
  ui_story_5028_50280202_60_dialog_content = "(Ela era tão solitária quanto eu costumava ser quando estava sozinha? Não, eu tinha Soroz, pelo menos.)",
  ui_story_5028_50280202_61_dialog_content = "(Embora ela tenha esse animal Kyllo.)",
  ui_story_5028_50280202_62_dialog_content = "(De qualquer forma, mesmo que ela esteja fingindo, não posso deixar uma garota soluçando sozinha aqui.)",
  ui_story_5028_50280202_63_dialog_content = "PlayerName, PlayerName, O que você pensa sobre?",
  ui_story_5028_50280202_64_dialog_content = "Ah, nada demais. Só que devemos voltar para que eu possa te levar para casa no Colossus.",
  ui_story_5028_50280202_65_dialog_content = "Oh sim! Esqueci que os celestitas têm colossos.",
  ui_story_5028_50280202_66_dialog_content = "Poderemos viajar de Colossus em vez de caminhar. Eu serei capaz de completar as provas do meu Mestre em pouco tempo!",
  ui_story_5028_50280202_67_dialog_content = "Vamos, PlayerName, vamos já!",
  ui_story_5028_50280202_68_dialog_content = "Huh? Que provações? E solte minha mão.",
  ui_story_5028_50280202_69_dialog_content = "Ai! Pare de me puxar, minhas costas ainda doem!",
  ui_story_5028_50280202_70_dialog_content = "E eu preciso deixar Revy saiba o que está acontecendo! Oi!",
  ui_story_5028_50280202_71_dialog_content = "998... Ah! 999... Ah!",
  ui_story_5028_50280202_72_dialog_content = "1.000... Ah!",
  ui_story_5028_50280202_73_dialog_content = "Como é que o Navigator ainda não voltou? Eu terminei a prática.",
  ui_story_5028_50280202_74_dialog_content = "Talvez ele tenha voltado para o Colosso? Deixe-me ir verificar.",
  ui_story_5028_50280202_75_dialog_content = "Hã?",
  ui_story_5028_50280202_76_dialog_content = "Onde está o Colosso?",
  ui_story_5028_50280202_77_dialog_content = "E onde está PlayerName?",
  ui_story_5028_50280202_78_dialog_content = "Hã?",
  ui_story_5028_50280202_79_dialog_content = "E o que diabos é isso?",
  ui_story_5028_50280301_1_dialog_content = "Prova: Chocando um ovo de Drakolion",
  ui_story_5028_50280301_2_dialog_content = "o <color=#FFB400>Drakolion</color> tem a cabeça de um dragão feroz.",
  ui_story_5028_50280301_3_dialog_content = "Também tem o corpo de um leão poderoso e as asas de uma águia majestosa.",
  ui_story_5028_50280301_4_dialog_content = "Uma única chicotada de sua cauda poderosa é capaz de derrubar um rinoceronte.",
  ui_story_5028_50280301_5_dialog_content = "Mas o mais aterrorizante de tudo são suas pernas musculosas.",
  ui_story_5028_50280301_5X_dialog_content = "Um Drakolion pode capturar e subjugar qualquer presa, mesmo em terra.",
  ui_story_5028_50280301_6_dialog_content = "Mas, felizmente, eles preferem permanecer no ar do que atacar no chão.",
  ui_story_5028_50280301_6X_dialog_content = "Eles são muito raramente vistos.",
  ui_story_5028_50280301_7_dialog_content = "o <color=#FFB400>exótico</color> Drakolion é o alvo deste julgamento.",
  ui_story_5028_50280301_8_dialog_content = "Ei, Fia, sobre o que você está resmungando?",
  ui_story_5028_50280301_9_dialog_content = "Parece um livro legal. Posso dar uma olhada?",
  ui_story_5028_50280301_10_dialog_content = "Xiu!",
  ui_story_5028_50280301_11_dialog_content = "Honestamente! Estou tentando fazer uma narração aqui. Não interrompa.",
  ui_story_5028_50280301_12_dialog_content = "Ei!",
  ui_story_5028_50280301_13_dialog_content = "O que quer dizer, uma narração? Somos os únicos aqui.",
  ui_story_5028_50280301_14_dialog_content = "Para que precisamos de uma narração?",
  ui_story_5028_50280301_15_dialog_content = "Ha, porque há certos procedimentos a seguir neste campo de trabalho, isso é tudo.",
  ui_story_5028_50280301_16_dialog_content = "Antes de se envolver com uma fera maravilhosa, é importante recitar tudo o que você sabe sobre ela.",
  ui_story_5028_50280301_17_dialog_content = "Particularmente quando se trata de uma fera maravilhosa como o Drakolion, você tem que fazer toda a pesquisa que puder em seus habitats.",
  ui_story_5028_50280301_18_dialog_content = "Além disso, dá a tudo uma sensação ritualística, o que ajuda a manter a calma em caso de emergência.",
  ui_story_5028_50280301_19_dialog_content = "Olá!",
  ui_story_5028_50280301_20_dialog_content = "... Sinceramente, estou mais preocupado que a verdadeira razão pela qual você está recitando para si mesmo é que você não tem ideia do que está fazendo.",
  ui_story_5028_50280301_21_dialog_content = "Ah. Relaxe, eu fiz minha pesquisa. Estou absolutamente certo de que vamos encontrar um Drakolion.",
  ui_story_5028_50280301_22_dialog_content = "As asas de uma águia majestosa...",
  ui_story_5028_50280301_23_dialog_content = "Você já disse essa parte, acho que não precisa repetir...",
  ui_story_5028_50280301_24_dialog_content = "Ah, fique quieto! Por favor, pare de me interromper.",
  ui_story_5028_50280301_25_dialog_content = "Já é difícil ter que decifrar a caligrafia atroz do Mestre. É como se ele mergulhasse um verme na tinta e o soltasse na página.",
  ui_story_5028_50280301_26_dialog_content = "Oh. Então você herdou aquele caderno do seu mestre?",
  ui_story_5028_50280301_27_dialog_content = "Herdado? Ouça, você poderia ficar quieto? Estou chegando à parte importante.",
  ui_story_5028_50280301_28_dialog_content = "Drakolions são bestas estranhas, com um profundo amor pelo céu.",
  ui_story_5028_50280301_29_dialog_content = "Eles estão relutantes em pousar mesmo quando põem ovos, a menos que haja uma ameaça para seus filhotes.",
  ui_story_5028_50280301_30_dialog_content = "E quando ameaçados, eles invocam relâmpagos e usam suas garras para estripar qualquer inimigo tolo o suficiente para se aproximar.",
  ui_story_5028_50280301_31_dialog_content = "Mas uma vez que eles colocam seu ovo, eles não mostram interesse em saber se ele cai ou não com segurança no chão ou choca.",
  ui_story_5028_50280301_32_dialog_content = "Talvez forçar seus jovens a enfrentar o mundo hostil sozinhos é como esse rei dos céus garante que apenas os mais fortes de sua espécie sobrevivam.",
  ui_story_5028_50280301_33_dialog_content = "Esta é também a razão pela qual os Drakolions são tão raros.",
  ui_story_5028_50280301_34_dialog_content = "Ok, agora eu entendo porque temos que ter certeza de que um dos ovos deles eclodirá.",
  ui_story_5028_50280301_35_dialog_content = "Às vezes é melhor respeitar os hábitos de uma fera maravilhosa. Mas, às vezes, precisamos dar uma mãozinha para que eles cresçam e se tornem grandes e fortes.",
  ui_story_5028_50280301_36_dialog_content = "Excelente! Este é o tipo de ensaio que me faz sentir como um verdadeiro extrozoólogo!",
  ui_story_5028_50280301_37_dialog_content = "Ei!",
  ui_story_5028_50280301_38_dialog_content = "Isso soa ridiculamente perigoso! Acho que vou me despedir agora!",
  ui_story_5028_50280301_39_dialog_content = "Espera espera! Não basta ir embora!",
  ui_story_5028_50280301_40_dialog_content = "Lo lo lo!",
  ui_story_5028_50280301_41_dialog_content = "Ah-há-há! De acordo com as anotações do meu mestre, o ovo eclodirá imediatamente após o pouso. Supondo que aterrisse em segurança, quero dizer.",
  ui_story_5028_50280301_42_dialog_content = "Então, tudo o que temos a fazer é garantir que não quebre ao cair.",
  ui_story_5028_50280301_43_dialog_content = "Ah, isso é tudo, hein? E aquela coisa aterrorizante do dragão?",
  ui_story_5028_50280301_44_dialog_content = "Quão perigoso é um Drakolion, você diria? Na sua opinião profissional.",
  ui_story_5028_50280301_45_dialog_content = "Sobre... digamos 50 pontos perigosos?",
  ui_story_5028_50280301_46_dialog_content = "Ok, então 50 de 100. Um perigo de médio alcance. Isso não soa muito mal.",
  ui_story_5028_50280301_47_dialog_content = "(Eh? Eu não pensei PlayerName confiaria em mim tão facilmente. Agora me sinto culpado!)",
  ui_story_5028_50280301_48_dialog_content = "50... de 10.",
  ui_story_5028_50280301_49_dialog_content = "...",
  ui_story_5028_50280301_50_dialog_content = "Ei...",
  ui_story_5028_50280301_51_dialog_content = "Oh, eu vejo! Ok, estou indo embora.",
  ui_story_5028_50280301_52_dialog_content = "Não vá, não vá! Por favor!",
  ui_story_5028_50280301_53_dialog_content = "Tenho coisas que podemos usar. Tipo, algo para encobrir nosso cheiro.",
  ui_story_5028_50280301_54_dialog_content = "Se usarmos isso, ficaremos bem. As notas dizem que os Drakolions têm uma visão muito ruim. Se não puder nos cheirar, não saberá que estamos lá.",
  ui_story_5028_50280301_55_dialog_content = "Hum...",
  ui_story_5028_50280301_56_dialog_content = "Você não tem idéias mais seguras?",
  ui_story_5028_50280301_57_dialog_content = "Talvez pudéssemos usar Soroz para pegar o ovo?",
  ui_story_5028_50280301_58_dialog_content = "Teoricamente possível, embora eu tenha uma pergunta.",
  ui_story_5028_50280301_59_dialog_content = "Soroz é homem ou mulher? Porque preciso saber se devemos evitar um ataque de Drakolion.",
  ui_story_5028_50280301_60_dialog_content = "...",
  ui_story_5028_50280301_61_dialog_content = "...",
  ui_story_5028_50280301_62_dialog_content = "... Lo?",
  ui_story_5028_50280301_63_dialog_content = "Essa é uma pergunta difícil de responder...",
  ui_story_5028_50280301_64_dialog_content = "Quer saber, finja que eu não disse nada.",
  ui_story_5028_50280301_65_dialog_content = "Você é o especialista, então faremos as coisas do seu jeito. Por mais assustador que isso possa ser.",
  ui_story_5028_50280301_66_dialog_content = "Relaxar. Eu vou te mostrar do que um extrozoologista talentoso é capaz!",
  ui_story_5028_50280301_67_dialog_content = "Ei...",
  ui_story_5028_50280301_68_dialog_content = "Ah—Ah—Achoo!",
  ui_story_5028_50280301_69_dialog_content = "Este creme de máscara de perfume tem um cheiro meio familiar.",
  ui_story_5028_50280301_70_dialog_content = "Pelo menos mantém os insetos longe. Eles estão todos nos evitando, mesmo enquanto estamos agachados aqui na grama.",
  ui_story_5028_50280301_71_dialog_content = "Ei...",
  ui_story_5028_50280301_72_dialog_content = "Heehee. Isso é um extrato feito de esterco de Kyllo. Funciona bem, não é?",
  ui_story_5028_50280301_73_dialog_content = "Quê?!",
  ui_story_5028_50280301_74_dialog_content = "Você deveria ter dito isso antes!",
  ui_story_5028_50280301_75_dialog_content = "Agora eu sinto toda coceira. É venenoso?",
  ui_story_5028_50280301_76_dialog_content = "Claro que não! Eu manchei também, lembra?",
  ui_story_5028_50280301_77_dialog_content = "E veja, sua espessura ajuda a reter a umidade, então é bom para sua pele.",
  ui_story_5028_50280301_78_dialog_content = "Eu uso a secreção de Kyllo para fazer toda uma gama de produtos para a pele, como acontece.",
  ui_story_5028_50280301_78X_dialog_content = "Mantém minha tez fresca e clara, mesmo depois de um dia inteiro no campo.",
  ui_story_5028_50280301_79_dialog_content = "Olá!",
  ui_story_5028_50280301_80_dialog_content = "Shhh! Eu ouvi algo.",
  ui_story_5028_50280301_81_dialog_content = "É um Drakolion?",
  ui_story_5028_50280301_82_dialog_content = "Sim. Quando estão prestes a botar um ovo, voam para algum lugar que acham seguro e fazem o mínimo de barulho possível.",
  ui_story_5028_50280301_83_dialog_content = "Mas ainda posso ouvir o som das asas, e tenho certeza de que é um Drakolion.",
  ui_story_5028_50280301_84_dialog_content = "<color=#e8d9bb>Barulho... Barulho...</color>",
  ui_story_5028_50280301_85_dialog_content = "Ok, então eu nunca ouvi o que um Drakolion em vôo soa. Mas é possível que o som esteja vindo da vegetação rasteira ali?",
  ui_story_5028_50280301_86_dialog_content = "Argh! Deve ser algum animalzinho irritante.",
  ui_story_5028_50280301_87_dialog_content = "Kyllo, vá e afaste-o!",
  ui_story_5028_50280301_88_dialog_content = "Ei!",
  ui_story_5028_50280301_89_dialog_content = "PlayerName, você realmente não pode ouvi-lo? É como as cordas de um instrumento sendo dedilhadas.",
  ui_story_5028_50280301_90_dialog_content = "<color=#e8d9bb>Barulho... Barulho... Barulho...</color>",
  ui_story_5028_50280301_91_dialog_content = "... Ei!",
  ui_story_5028_50280301_92_dialog_content = "Cordas de instrumentos? Tudo o que posso ouvir é a grama e Kyllo, só isso.",
  ui_story_5028_50280301_93_dialog_content = "Ei! Olá!",
  ui_story_5028_50280301_94_dialog_content = "Você é tão estúpido! Você quer que eu arranque um fio de cabelo e dedule para você, para que você saiba do que estou falando?",
  ui_story_5028_50280301_95_dialog_content = "<size=45>Lo—!</size>",
  ui_story_5028_50280301_96_dialog_content = "Kyllo, você é muito barulhento!",
  ui_story_5028_50280301_97_dialog_content = "Aahhhhhh!",
  ui_story_5028_50280301_98_dialog_content = "Eclipsitas!",
  ui_story_5028_50280301_99_dialog_content = "Por que tem que fazer isso agora? Se o Drakolion nos vir quando estiver tentando botar um ovo, estamos acabados!",
  ui_story_5028_50280301_100_dialog_content = "Vamos fazer isso rápido, PlayerName!",
  ui_story_5028_50280301_101_dialog_content = "Pode deixar! Vamos!",
  ui_story_5028_50280301_102_dialog_content = "Ei!",
  ui_story_5028_50280302_1_dialog_content = "Ok, bem, pelo menos isso está resolvido.",
  ui_story_5028_50280302_2_dialog_content = "Com todo esse creme mascarador de cheiro, os Eclipsites não deveriam ter nos encontrado.",
  ui_story_5028_50280302_3_dialog_content = "Ei, PlayerName, você tem certeza de que não há nada em você que os atraia?",
  ui_story_5028_50280302_4_dialog_content = "Você gosta de algum tipo de farol ou algo que naturalmente chama a atenção deles?",
  ui_story_5028_50280302_5_dialog_content = "Como mariposas para uma chama.",
  ui_story_5028_50280302_6_dialog_content = "Agora que penso nisso, você pode estar certo.",
  ui_story_5028_50280302_7_dialog_content = "Não importa onde eu vá – a praia, as montanhas, o deserto, as ruínas antigas – os eclipses sempre aparecem.",
  ui_story_5028_50280302_8_dialog_content = "É como assassinatos bizarros ocorrem sempre que um detetive famoso está por perto.",
  ui_story_5028_50280302_9_dialog_content = "<size=30>Mais uma vez, o Mestre me sobrecarrega com um fardo...</size>",
  ui_story_5028_50280302_10_dialog_content = "O quê?",
  ui_story_5028_50280302_11_dialog_content = "Deixa para lá. Pelo menos o Drakolion não nos notou, e parece que está prestes a botar seu ovo.",
  ui_story_5028_50280302_12_dialog_content = "Está descendo. Vamos nos esconder.",
  ui_story_5028_50280302_13_dialog_content = "Eu vejo isso! Mas certamente o ovo vai quebrar se cair dessa altura?",
  ui_story_5028_50280302_14_dialog_content = "Que tipo de prática bizarra é essa? É um milagre que a espécie não tenha sido extinta.",
  ui_story_5028_50280302_15_dialog_content = "Todo zoólogo em Astra se pergunta a mesma coisa.",
  ui_story_5028_50280302_16_dialog_content = "Mas isso são feras maravilhosas para você. Seu comportamento nem sempre faz sentido.",
  ui_story_5028_50280302_17_dialog_content = "O que significa... que precisamos pensar em algo, ou o ovo vai quebrar.",
  ui_story_5028_50280302_18_dialog_content = "Ei!",
  ui_story_5028_50280302_19_dialog_content = "Fia? O que você está fazendo?",
  ui_story_5028_50280302_20_dialog_content = "Vou subir nesta árvore para pegar o ovo!",
  ui_story_5028_50280302_21_dialog_content = "Não seja estúpido! É uma árvore alta, mas não é nem de longe alta o suficiente.",
  ui_story_5028_50280302_22_dialog_content = "E como você vai usar a rede aí em cima?",
  ui_story_5028_50280302_23_dialog_content = "Argh! Então o que devemos fazer então? Não podemos evitar assim.",
  ui_story_5028_50280302_24_dialog_content = "Eles só põem ovos cerca de uma vez por década e já estão quase extintos.",
  ui_story_5028_50280302_25_dialog_content = "Consegui todas as informações que precisava de você, mas ainda não consegui protegê-las, Mestre...",
  ui_story_5028_50280302_26_dialog_content = "Ei...",
  ui_story_5028_50280302_27_dialog_content = "Eu sei!",
  ui_story_5028_50280302_28_dialog_content = "Eh? Você quer dizer...",
  ui_story_5028_50280302_29_dialog_content = "Mesmo?",
  ui_story_5028_50280302_30_dialog_content = "Não temos outra escolha, só podemos tentar isso!",
  ui_story_5028_50280302_31_dialog_content = "PlayerName, obrigado por deixar Soroz nos ajudar!",
  ui_story_5028_50280302_32_dialog_content = "Bem, eu não posso deixar o bebê Drakolion morrer antes mesmo de ver o mundo.",
  ui_story_5028_50280302_33_dialog_content = "Não tenho certeza do que o Drakolion vai pensar de Soroz, mas vamos tentar!",
  ui_story_5028_50280302_34_dialog_content = "Rugido-",
  ui_story_5028_50280302_35_dialog_content = "PlayerName! O Drakolion parece ter se interessado por Soroz!",
  ui_story_5028_50280302_36_dialog_content = "Na verdade, parece querer fazer amizade com Soroz. Continua cada vez mais perto.",
  ui_story_5028_50280302_37_dialog_content = "Ok, quase lá. Só um pouco mais perto... e aí eu posso usar a rede...",
  ui_story_5028_50280302_38_dialog_content = "(Espere aí, o que é isso no tornozelo? Não importa, vou me preocupar com isso mais tarde.)",
  ui_story_5028_50280302_39_dialog_content = "Ei! Ei!",
  ui_story_5028_50280302_40_dialog_content = "Rooarrrrr—",
  ui_story_5028_50280302_41_dialog_content = "Fia! Está chegando!",
  ui_story_5028_50280302_42_dialog_content = "Eu sei! Aproxime-nos um pouco e deixe o resto para mim e Kyllo!",
  ui_story_5028_50280302_43_dialog_content = "3.",
  ui_story_5028_50280302_44_dialog_content = "2.",
  ui_story_5028_50280302_45_dialog_content = "1.",
  ui_story_5028_50280302_46_dialog_content = "Fia!",
  ui_story_5028_50280302_47_dialog_content = "Ei!",
  ui_story_5028_50280302_48_dialog_content = "!",
  ui_story_5028_50280302_49_dialog_content = "Funcionou!",
  ui_story_5028_50280302_50_dialog_content = "É tão brilhante. Será que vai chocar agora?",
  ui_story_5028_50280302_51_dialog_content = "P...",
  ui_story_5028_50280302_52_dialog_content = "Espreitar?",
  ui_story_5028_50280302_53_dialog_content = "Olá!",
  ui_story_5028_50280302_54_dialog_content = "É... É tão fofo!",
  ui_story_5028_50280302_55_dialog_content = "Como algo tão pequeno se transforma em uma daquelas criaturas enormes?",
  ui_story_5028_50280302_56_dialog_content = "É inacreditável. Não é à toa que os Drakolions são <color=#FFB400>exóticos</color>.",
  ui_story_5028_50280302_57_dialog_content = "Fia! Funcionou?",
  ui_story_5028_50280302_58_dialog_content = "Ele fez! Tudo graças a você e ao Soroz! O Drakolion já eclodiu.",
  ui_story_5028_50280302_59_dialog_content = "Ei!",
  ui_story_5028_50280302_60_dialog_content = "Sim, graças a você também, Kyllo.",
  ui_story_5028_50280302_61_dialog_content = "Olá!",
  ui_story_5028_50280302_62_dialog_content = "Espreite!",
  ui_story_5028_50280302_63_dialog_content = "Pessoal, vamos deixar os parabéns para depois!",
  ui_story_5028_50280302_64_dialog_content = "O Drakolion agarrou Soroz e não está soltando, o que significa que não podemos pousar.",
  ui_story_5028_50280302_65_dialog_content = "Ah, esqueci de mencionar.",
  ui_story_5028_50280302_65X_dialog_content = "Eles são muito protetores de sua espécie. Provavelmente pensa que estamos sequestrando o filhote!",
  ui_story_5028_50280302_66_dialog_content = "O que!? Estamos quase mortos então!",
  ui_story_5028_50280302_67_dialog_content = "Não, espere. Isso não é um grito beligerante.",
  ui_story_5028_50280302_68_dialog_content = "Parece... Acho que está apaixonado pelo Soroz.",
  ui_story_5028_50280302_69_dialog_content = "Diga o quê!?",
  ui_story_5028_50280302_70_dialog_content = "E nenhum sinal de PlayerName aqui também.",
  ui_story_5028_50280302_71_dialog_content = "Huh? Você é Revy, não é? O que você está fazendo vagando por aqui?",
  ui_story_5028_50280302_72_dialog_content = "Oh, Smokey.",
  ui_story_5028_50280302_73_dialog_content = "Estou procurando o celestita.",
  ui_story_5028_50280302_74_dialog_content = "PlayerName e eu estava jogando bola nas proximidades.",
  ui_story_5028_50280302_75_dialog_content = "Mas nos separamos. Ele deixou um bilhete, mas acho que pode ter sido sequestrado.",
  ui_story_5028_50280302_76_dialog_content = "O quê?",
  ui_story_5028_50280302_77_dialog_content = "O que você acabou de dizer? PlayerName foi sequestrado?",
  ui_story_5028_50280302_78_dialog_content = "Onde está a nota?",
  ui_story_5028_50280302_79_dialog_content = "Oh, eu perdi enquanto lidava com alguns Eclipsites.",
  ui_story_5028_50280302_80_dialog_content = "Que divertido.",
  ui_story_5028_50280302_81_dialog_content = "Ele realmente é muito infeliz. Eu me pergunto quem o levou desta vez.",
  ui_story_5028_50280302_82_dialog_content = "Você vai me ajudar a encontrá-lo?",
  ui_story_5028_50280302_83_dialog_content = "Vice e Gram vão ficar bravos comigo se descobrirem que o perdi.",
  ui_story_5028_50280302_84_dialog_content = "Bem, não tenho mais nada para fazer. Vamos ver se encontramos o tolo.",
  ui_story_5028_50280401_1_dialog_content = "Teste: Crise da vinha",
  ui_story_5028_50280401_2_dialog_content = "Huff... Huff! Ah!",
  ui_story_5028_50280401_3_dialog_content = "Oi, Fia! Fia, vá devagar.",
  ui_story_5028_50280401_4_dialog_content = "Para onde vamos mesmo?",
  ui_story_5028_50280401_5_dialog_content = "Estamos cercados por videiras. O que estamos fazendo desta vez, chocando um dragão de uva?",
  ui_story_5028_50280401_6_dialog_content = "Lo.",
  ui_story_5028_50280401_7_dialog_content = "Shhh. Estou organizando minhas anotações sobre a eclosão do Drakolion.",
  ui_story_5028_50280401_8_dialog_content = "Eu não podia acreditar o quão rápido ele cresceu. Ele cresceu tão grande quanto Kyllo instantaneamente e foi imediatamente auto-suficiente.",
  ui_story_5028_50280401_9_dialog_content = "*Suspiro* ... Eu não esperava que ele voasse em busca de seu próprio território tão rapidamente.",
  ui_story_5028_50280401_9X_dialog_content = "Eu nem tive a chance de apreciar adequadamente sua fofura!",
  ui_story_5028_50280401_10_dialog_content = "Huh. Acho que devemos ser gratos por termos escapado do Drakolion com nossas vidas.",
  ui_story_5028_50280401_11_dialog_content = "Sério, eu não posso mais andar. Vamos fazer uma pausa.",
  ui_story_5028_50280401_12_dialog_content = "Uma pausa? Já? Mas estamos quase lá...",
  ui_story_5028_50280401_13_dialog_content = "Eu não sei o que fazer com você, PlayerName. Aqui, abra bem e beba isso.",
  ui_story_5028_50280401_14_dialog_content = "O-o que você está fazendo? Eu não estou bebendo nada!",
  ui_story_5028_50280401_15_dialog_content = "Vamos. Seja bom!",
  ui_story_5028_50280401_16_dialog_content = "Fique atrás!",
  ui_story_5028_50280401_17_dialog_content = "Kyllo, me ajude a segurar PlayerName baixa!",
  ui_story_5028_50280401_18_dialog_content = "Olá!",
  ui_story_5028_50280401_19_dialog_content = "*Gritando abafado* Glug glug glug!",
  ui_story_5028_50280401_20_dialog_content = "É picante! Não, espere. Isso é leite? Está mudando de novo... Agora está tão gelado!",
  ui_story_5028_50280401_21_dialog_content = "O que diabos você me fez beber?",
  ui_story_5028_50280401_22_dialog_content = "Energético patenteado pela Fia, feito com leite de boi-de-fogo e caules de castanheira.",
  ui_story_5028_50280401_23_dialog_content = "Também um pouco de frostmint, que adicionei especialmente. Essa foi a parte final. Ela só cresce em Northland, você sabe. Revigorante, não é?",
  ui_story_5028_50280401_24_dialog_content = "Eu dou todos os ingredientes para Kyllo e ele agita tudo em seu estômago. Isso contribui para uma mistura mais suave do que fazê-lo à mão.",
  ui_story_5028_50280401_25_dialog_content = "Com apenas um gole, você estará tão animado quanto possível!",
  ui_story_5028_50280401_25X_dialog_content = "Seus ingredientes são muito preciosos, só para você saber.",
  ui_story_5028_50280401_26_dialog_content = "Ei!",
  ui_story_5028_50280401_27_dialog_content = "Que nojo. Kyllo, por que você a ajuda com esse tipo de coisa?!",
  ui_story_5028_50280401_28_dialog_content = "Lo?",
  ui_story_5028_50280401_29_dialog_content = "E quanto a você, Fia!",
  ui_story_5028_50280401_30_dialog_content = "Hã?",
  ui_story_5028_50280401_31_dialog_content = "Você não pode simplesmente fazer suas próprias misturas e me usar como cobaia! Isso é ilegal. Muito ilegal!",
  ui_story_5028_50280401_32_dialog_content = "O-o quê? Como poderia ser?",
  ui_story_5028_50280401_33_dialog_content = "N-não conte a ninguém sobre este incidente, ok? Sou muito jovem e ambicioso para ir para a prisão.",
  ui_story_5028_50280401_34_dialog_content = "Contanto que você prometa não derramar uma gosma estranha na minha garganta de repente...",
  ui_story_5028_50280401_35_dialog_content = "Está bem, está bem. Mas foi para o seu próprio bem...",
  ui_story_5028_50280401_36_dialog_content = "Hum. Parece estar funcionando, no entanto.",
  ui_story_5028_50280401_37_dialog_content = "Sinto-me muito melhor, revigorado e cheio de energia.",
  ui_story_5028_50280401_38_dialog_content = "Veja, funciona! Espera aí, preciso anotar a receita que usei dessa vez.",
  ui_story_5028_50280401_39_dialog_content = "Espere, esta foi sua primeira vez dando a alguém para beber? Eu sou o único celestita remanescente do continente!",
  ui_story_5028_50280401_40_dialog_content = "Se eu morresse em algum lugar assim só por ser forçado a beber uma mistura estranha...",
  ui_story_5028_50280401_41_dialog_content = "Esse é o tipo louco de final trágico que você só lê na ficção!",
  ui_story_5028_50280401_42_dialog_content = "Ahhaha. Claro que não foi a primeira vez. De qualquer forma, como você está se sentindo?",
  ui_story_5028_50280401_42X_dialog_content = "Você gostaria de apertar Kyllo para um pouco mais?",
  ui_story_5028_50280401_43_dialog_content = "Ei!?",
  ui_story_5028_50280401_44_dialog_content = "Absolutamente não! Você pode tê-lo.",
  ui_story_5028_50280401_45_dialog_content = "E nem pense em me alimentar com algo tão questionável de novo!",
  ui_story_5028_50280401_46_dialog_content = "Honestamente, um grande e forte Caelestita, com medo de um pouco de bebida energética. Isso é meio embaraçoso.",
  ui_story_5028_50280401_47_dialog_content = "Honestamente, eu te ensinaria uma lição se não precisasse de você para salvar Soroz.",
  ui_story_5028_50280401_48_dialog_content = "Heehee. Relaxar. Conseguimos fugir do Drakolion com segurança, não foi?",
  ui_story_5028_50280401_49_dialog_content = "Se estiver apaixonado por Soroz, não fará mal a Soroz.",
  ui_story_5028_50280401_50_dialog_content = "Você diz isso, mas acha que Soroz ser forçado a voar com um Drakolion para sempre é melhor?",
  ui_story_5028_50280401_51_dialog_content = "Aham.",
  ui_story_5028_50280401_52_dialog_content = "Uau!",
  ui_story_5028_50280401_53_dialog_content = "Q-Quem era aquele? Um eclipse? Uma fera? Um monstro?",
  ui_story_5028_50280401_54_dialog_content = "Desculpe desapontá-lo, mas nenhuma das opções acima. Eu sou apenas um auroriano.",
  ui_story_5028_50280401_55_dialog_content = "Você seria o melhor aluno do Sr. Vic, suponho?",
  ui_story_5028_50280401_56_dialog_content = "Victor?",
  ui_story_5028_50280401_57_dialog_content = "(Vamos lá, Fia, você tem que fazer melhor que isso. Imagine ficar assustado com um velho gentil.)",
  ui_story_5028_50280401_58_dialog_content = "Aham. Olá senhor. Eu sou discípulo de Vic. Fia, a extrozoóloga.",
  ui_story_5028_50280401_59_dialog_content = "Fia, você ainda não está treinando?",
  ui_story_5028_50280401_60_dialog_content = "Um especialista em treinamento ainda é um especialista.",
  ui_story_5028_50280401_61_dialog_content = "Ah, me perdoe! Eu deveria saber.",
  ui_story_5028_50280401_62_dialog_content = "Então, meu mestre—",
  ui_story_5028_50280401_63_dialog_content = "Na minha juventude, eu era um Guarda Lumo. Lutei em algumas guerras, se assim posso dizer.",
  ui_story_5028_50280401_64_dialog_content = "Este joelho sofre de uma velha ferida de guerra, na verdade. Entendi o dia Senhor Schwartz e lutei lado a lado contra os Eclipsitas.",
  ui_story_5028_50280401_65_dialog_content = "Senhor, você—",
  ui_story_5028_50280401_66_dialog_content = "Ah, mas o que eu realmente queria ser, claro, era um autor. Eu costumava fugir de meus deveres de escrever.",
  ui_story_5028_50280401_67_dialog_content = "Acabei sendo pego e dispensado cedo. Mandaram-me aqui, para cultivar uvas.",
  ui_story_5028_50280401_68_dialog_content = "Por favor escute-",
  ui_story_5028_50280401_69_dialog_content = "Eu escrevi um monte de romances de sucesso!",
  ui_story_5028_50280401_69X_dialog_content = "Como O Cavaleiro Já Está Morto, Juiz x Família, Karma Rider Vice, e assim por diante.",
  ui_story_5028_50280401_70_dialog_content = "Senhor! Por favor, diga-nos o que precisamos fazer primeiro!",
  ui_story_5028_50280401_71_dialog_content = "Oh oh oh! Isso. Sinto muito. Eu vou te dizer imediatamente.",
  ui_story_5028_50280401_72_dialog_content = "Estúpido, irritante, idiota, Mestre! Amaldiçoe-o!",
  ui_story_5028_50280401_73_dialog_content = "Como ele ousa me fazer passar a noite toda guardando a vinha de um velho tolo!",
  ui_story_5028_50280401_74_dialog_content = "Estou tentando ser um extrozoólogo! Não um segurança perseguidor de ladrões!",
  ui_story_5028_50280401_75_dialog_content = "Ei acorde. Seu relógio.",
  ui_story_5028_50280401_76_dialog_content = "Blech, você está babando...",
  ui_story_5028_50280401_77_dialog_content = "Pegue! Acima!",
  ui_story_5028_50280401_78_dialog_content = "Ah? E-há um ladrão?",
  ui_story_5028_50280401_79_dialog_content = "Sim, um ladrão roubou sua Soroz das nuvens.",
  ui_story_5028_50280401_80_dialog_content = "O que? Sério?",
  ui_story_5028_50280401_81_dialog_content = "Não, na verdade não! É a sua vez de vigiar. Estou exausto.",
  ui_story_5028_50280401_82_dialog_content = "<color=#e8d9bb>Muito tarde</color>",
  ui_story_5028_50280401_83_dialog_content = "Ronco...",
  ui_story_5028_50280401_84_dialog_content = "Ha ha ha!",
  ui_story_5028_50280401_85_dialog_content = "O que foi isso?",
  ui_story_5028_50280401_86_dialog_content = "Ei. Mastigue.",
  ui_story_5028_50280401_87_dialog_content = "Fia!",
  ui_story_5028_50280401_88_dialog_content = "O-O quê?",
  ui_story_5028_50280401_89_dialog_content = "Loo...?",
  ui_story_5028_50280401_90_dialog_content = "Acorda!",
  ui_story_5028_50280401_91_dialog_content = "As uvas acabaram!",
  ui_story_5028_50280401_92_dialog_content = "Wha?!?!",
  ui_story_5028_50280401_93_dialog_content = "O culpado foi assim! Se apresse!",
  ui_story_5028_50280401_94_dialog_content = "Que diabo sorrateiro!",
  ui_story_5028_50280401_95_dialog_content = "Desapareceu na floresta, assim mesmo!",
  ui_story_5028_50280401_96_dialog_content = "Não há nada que possamos fazer. Nós nunca vamos alcançar.",
  ui_story_5028_50280401_97_dialog_content = "Talvez haja mais de um deles. Devemos voltar para a vinha.",
  ui_story_5028_50280401_98_dialog_content = "Pfft. Hahaha—",
  ui_story_5028_50280401_99_dialog_content = "Você está bem, Fia? Eu sei que o ladrão escapou, mas o riso histérico parece um pouco...",
  ui_story_5028_50280401_100_dialog_content = "Não é isso não. Acabei de pensar em uma piada muito engraçada.",
  ui_story_5028_50280401_101_dialog_content = "Hã?",
  ui_story_5028_50280401_102_dialog_content = "Você sabe como eles dizem: \"Ande pelo deserto de Rediesel e você certamente encontrará um verme da areia\".",
  ui_story_5028_50280401_103_dialog_content = "Eu tenho um novo: \"Vá para uma floresta escura com um celestita e você certamente encontrará um...\"",
  ui_story_5028_50280401_104_dialog_content = "Aahhhhhh!",
  ui_story_5028_50280401_105_dialog_content = "Isso não é engraçado! É totalmente sem graça e atrai Eclipsites. Corre!",
  ui_story_5028_50280401_106_dialog_content = "Uau! Ele se tornou realidade! E espere, seu estúpido celestita!",
  ui_story_5028_50280401_107_dialog_content = "Espere!",
  ui_story_5028_50280402_1_dialog_content = "Ufa, bufa!",
  ui_story_5028_50280402_2_dialog_content = "Por que esses malditos Eclipsites simplesmente não desistem?",
  ui_story_5028_50280402_3_dialog_content = "Graagh!",
  ui_story_5028_50280402_4_dialog_content = "Cuidado!",
  ui_story_5028_50280402_5_dialog_content = "Ei!",
  ui_story_5028_50280402_6_dialog_content = "Estou bem. Obrigado, PlayerName.",
  ui_story_5028_50280402_7_dialog_content = "Oh não! Caderno do meu mestre!",
  ui_story_5028_50280402_8_dialog_content = "Vá e pegue-o, rápido, antes que mais Eclipsites apareçam. Eu ficarei aqui.",
  ui_story_5028_50280402_9_dialog_content = "Mas...",
  ui_story_5028_50280402_10_dialog_content = "Vai!",
  ui_story_5028_50280402_11_dialog_content = "Graaah!",
  ui_story_5028_50280402_12_dialog_content = "Este Eclipse está me ignorando completamente, está indo direto para Fia.",
  ui_story_5028_50280402_13_dialog_content = "(Eu preciso encontrar uma chance de acertar seu ponto fraco.)",
  ui_story_5028_50280402_14_dialog_content = "Graaah!",
  ui_story_5028_50280402_15_dialog_content = "(Mal posso esperar mais ou Fia será cercada!)",
  ui_story_5028_50280402_16_dialog_content = "Ha!",
  ui_story_5028_50280402_17_dialog_content = "Não esperava isso, não é, seus Eclipsitas imundos!",
  ui_story_5028_50280402_18_dialog_content = "Ai ai! Eles são duros como rochas.",
  ui_story_5028_50280402_19_dialog_content = "Graagh!",
  ui_story_5028_50280402_20_dialog_content = "Uau! Eu fui muito apressado. Hora de pegar Fia e sair!",
  ui_story_5028_50280402_21_dialog_content = "Eu entendi, PlayerName. Vamos lá!",
  ui_story_5028_50280402_22_dialog_content = "Ah! Nós finalmente nos livramos deles.",
  ui_story_5028_50280402_23_dialog_content = "PlayerName, você está bem? Seu braço está inchado.",
  ui_story_5028_50280402_24_dialog_content = "Não é nada. Eu abordei um Eclipsite e era meio resistente.",
  ui_story_5028_50280402_25_dialog_content = "É tudo minha culpa por ser descuidado. Oh, sinto muito! Eu vou colocar um pouco de pomada nele imediatamente!",
  ui_story_5028_50280402_26_dialog_content = "Está bem. Desde que tenhamos de volta o caderno do seu falecido mestre.",
  ui_story_5028_50280402_27_dialog_content = "Huh? Mestre \"atrasado\"?",
  ui_story_5028_50280402_28_dialog_content = "Oh, certo. Sim, eu fingi que ele estava morto.",
  ui_story_5028_50280402_29_dialog_content = "Desculpe! Ele está realmente vivo.",
  ui_story_5028_50280402_30_dialog_content = "Hã?",
  ui_story_5028_50280402_31_dialog_content = "Ok, eu coloquei pomada e enfaixei. O inchaço deve diminuir em breve.",
  ui_story_5028_50280402_32_dialog_content = "<size=30>E... me desculpe.</size>",
  ui_story_5028_50280402_33_dialog_content = "O quê?",
  ui_story_5028_50280402_34_dialog_content = "<size=30>Eu disse, desculpe.</size>",
  ui_story_5028_50280402_35_dialog_content = "Fia, você está sussurrando. Eu não posso te ouvir.",
  ui_story_5028_50280402_36_dialog_content = "*respira*",
  ui_story_5028_50280402_37_dialog_content = "<size=45>Eu sinto Muito! Eu sinto Muito! Eu sinto Muito! Estou me desculpando, ok!!!</size>",
  ui_story_5028_50280402_38_dialog_content = "Uau. De onde veio isso?",
  ui_story_5028_50280402_39_dialog_content = "Desculpe, eu menti. Eu vou fazer as pazes com você e isso nunca vai acontecer novamente.",
  ui_story_5028_50280402_40_dialog_content = "Mas honestamente, ele era um mestre inútil. Ele apenas me mandava e tornava minha vida difícil.",
  ui_story_5028_50280402_41_dialog_content = "Não como você, PlayerName. Você foi honesto e gentil e me ajudou.",
  ui_story_5028_50280402_42_dialog_content = "E eu entrei em pânico e menti, mas eu realmente queria desesperadamente um amigo. Sério!",
  ui_story_5028_50280402_43_dialog_content = "Eu espero que você possa me perdoar.",
  ui_story_5028_50280402_44_dialog_content = "E quanto ao meu estúpido mestre, ele pode simplesmente explodir onde está! Hmph!",
  ui_story_5028_50280402_45_dialog_content = "Atchim!",
  ui_story_5028_50280402_46_dialog_content = "Alguém deve estar falando de mim. Quem, eu me pergunto?",
  ui_story_5028_50280402_47_dialog_content = "Estou sentindo algo bastante sinistro...",
  ui_story_5028_50280402_48_dialog_content = "Ah, eu entendi. Na verdade, percebi na hora que você estava fingindo as lágrimas. Mas eu não estava prestes a abandoná-lo lá.",
  ui_story_5028_50280402_49_dialog_content = "Mas honestamente, Fia, desejar que alguém exploda é um pouco demais, não é?",
  ui_story_5028_50280402_50_dialog_content = "Você não pode dizer coisas assim, mesmo se estiver brincando.",
  ui_story_5028_50280402_51_dialog_content = "E embora sua caligrafia possa parecer um rabisco de galinha, seu mestre dedicou muito tempo e esforço a esse caderno. É muito detalhado.",
  ui_story_5028_50280402_52_dialog_content = "Ele não a teria dado a você se não a tivesse em alta conta.",
  ui_story_5028_50280402_53_dialog_content = "Oh... bem, sim, acho que você está certo.",
  ui_story_5028_50280402_54_dialog_content = "Eu não deveria desejar a morte de ninguém, nem mesmo ele. Peço desculpas a ele também, mesmo que ele esteja muito longe para ouvir.",
  ui_story_5028_50280402_55_dialog_content = "E nunca mais direi algo assim. Então...",
  ui_story_5028_50280402_56_dialog_content = "Então, você poderia parar de acariciar minha cabeça? Eu sei que somos amigos, mas eu sou tímido, e Kyllo está assistindo!",
  ui_story_5028_50280402_57_dialog_content = "Oh, desculpe. É só, você sabe... É meio natural, com a diferença de altura.",
  ui_story_5028_50280402_58_dialog_content = "Você está me chamando de curto?",
  ui_story_5028_50280402_59_dialog_content = "Aham. Bem, de qualquer maneira... Você tem alguma idéia sobre aquele ladrão de uvas?",
  ui_story_5028_50280402_60_dialog_content = "Bem, parecia-me um <color=#FFB400>Bica</color>. Esse é um tipo de besta maravilhosa.",
  ui_story_5028_50280402_61_dialog_content = "De acordo com o caderno, eles gostam de alimentos redondos e podem engoli-los inteiros, independentemente do tamanho.",
  ui_story_5028_50280402_62_dialog_content = "Eles têm corpos muito flexíveis, você vê, que se expandem para acomodar o tamanho de sua comida.",
  ui_story_5028_50280402_63_dialog_content = "Eles têm pernas poderosas e são corredores rápidos.",
  ui_story_5028_50280402_64_dialog_content = "Mas eles não são criaturas inteligentes. Definitivamente uma das bestas maravilhosas mais estúpidas.",
  ui_story_5028_50280402_65_dialog_content = "Alimentos redondos? Deixe-me pensar.",
  ui_story_5028_50280402_66_dialog_content = "<size=30>Isso realmente vai funcionar?</size>",
  ui_story_5028_50280402_67_dialog_content = "<size=30>Apenas colocando uma melancia em uma gaiola como esta? Quero dizer, claro, parece gostoso</size>.",
  ui_story_5028_50280402_68_dialog_content = "<size=30>Mas será que a Bica cairá na armadilha tão facilmente?</size>",
  ui_story_5028_50280402_69_dialog_content = "<size=30>Relaxar. Se o que o notebook diz for verdade, ele não será capaz de resistir a nada tão grande e redondo.</size>",
  ui_story_5028_50280402_70_dialog_content = "<size=30>Então confie em mim, e tenha fé nas anotações do seu mestre.</size>",
  ui_story_5028_50280402_71_dialog_content = "<size=30>Está bem então. Ei, algo está vindo.</size>",
  ui_story_5028_50280402_72_dialog_content = "Hai—Hai—",
  ui_story_5028_50280402_73_dialog_content = "Ei?",
  ui_story_5028_50280402_74_dialog_content = "Ei...",
  ui_story_5028_50280402_75_dialog_content = "Ele comeu!",
  ui_story_5028_50280402_76_dialog_content = "Ei!",
  ui_story_5028_50280402_77_dialog_content = "Acho que o rapaz é mesmo burro.",
  ui_story_5028_50280402_78_dialog_content = "Oi!? Oi!?",
  ui_story_5028_50280402_79_dialog_content = "Não tenha medo. Não vamos te machucar.",
  ui_story_5028_50280402_80_dialog_content = "Ei?",
  ui_story_5028_50280402_81_dialog_content = "Bem, nós só queríamos perguntar. Você poderia parar de roubar as uvas do Sr. Peng?",
  ui_story_5028_50280402_82_dialog_content = "Oi oi?",
  ui_story_5028_50280402_83_dialog_content = "Deixe-me tentar.",
  ui_story_5028_50280402_84_dialog_content = "Não tenha medo. Nós não vamos te machucar.",
  ui_story_5028_50280402_85_dialog_content = "Ei...?",
  ui_story_5028_50280402_86_dialog_content = "PlayerName, abra a gaiola. Não vai fugir.",
  ui_story_5028_50280402_87_dialog_content = "Ok, se você tem certeza.",
  ui_story_5028_50280402_88_dialog_content = "Ei...",
  ui_story_5028_50280402_89_dialog_content = "O que? Você diz que a melancia é saborosa? Você está realmente preocupado com isso em um momento como este?",
  ui_story_5028_50280402_90_dialog_content = "Ha ha ha!",
  ui_story_5028_50280402_91_dialog_content = "Diz que escapou das garras de um monstro assustador.",
  ui_story_5028_50280402_92_dialog_content = "Você deve estar apavorado, coitado. Mas isso não significa que você pode vir aqui e roubar uvas.",
  ui_story_5028_50280402_93_dialog_content = "Fia, você pode...",
  ui_story_5028_50280402_94_dialog_content = "Ei.",
  ui_story_5028_50280402_95_dialog_content = "Oh? Você estará seguro comigo, e haverá melancia para comer?",
  ui_story_5028_50280402_96_dialog_content = "Bem, isso é doce de sua parte.",
  ui_story_5028_50280402_97_dialog_content = "PlayerName, vamos adotá-lo. Isso vai impedi-lo de roubar uvas. E não será intimidado por outros animais.",
  ui_story_5028_50280402_98_dialog_content = "Bem, se vocês dois estão de acordo, não tenho objeções.",
  ui_story_5028_50280402_99_dialog_content = "Kyllo, você não se importaria se a Bica se juntasse a nós, não é?",
  ui_story_5028_50280402_100_dialog_content = "Ei!",
  ui_story_5028_50280402_101_dialog_content = "Excelente. Temos um novo companheiro!",
  ui_story_5028_50280402_102_dialog_content = "Acabei com os cartazes aqui.",
  ui_story_5028_50280402_103_dialog_content = "E eu estou acabado deste lado.",
  ui_story_5028_50280402_104_dialog_content = "Cartazes de pessoas desaparecidas não são muito úteis, mas nunca se sabe. Podemos ter uma pista.",
  ui_story_5028_50280402_105_dialog_content = "Quem está aí?",
  ui_story_5028_50280402_106_dialog_content = "Heheh! Eu vi tudo, Smokey.",
  ui_story_5028_50280402_107_dialog_content = "Difícil acreditar que você sucumbiu a colar anúncios para ganhar a vida agora.",
  ui_story_5028_50280402_108_dialog_content = "Com esse garoto Illumina, nada menos.",
  ui_story_5028_50280402_109_dialog_content = "Ouça, se você está com pouco dinheiro, por que não te empresto um pouco?",
  ui_story_5028_50280402_110_dialog_content = "Prometo que não vou cobrar muito juros. Vamos chamá-lo de... uma taxa amigável.",
  ui_story_5028_50280402_111_dialog_content = "Tchau, você fala demais.",
  ui_story_5028_50280402_112_dialog_content = "Ei Revy, você acha que suas armas Illuminan atiram mais rápido, ou a boca dessa mulher?",
  ui_story_5028_50280402_113_dialog_content = "Não tenho certeza. Eu não uso armas.",
  ui_story_5028_50280402_114_dialog_content = "PlayerName está desaparecido. Smokey está me ajudando a pesquisar.",
  ui_story_5028_50280402_115_dialog_content = "Oh? Eu diria que é estranho, mas não é realmente. E é surpreendente, mas não realmente.",
  ui_story_5028_50280402_116_dialog_content = "Mas se você está procurando o Navigator, Smokey, então eu também. Não vou deixar você encontrá-lo primeiro.",
  ui_story_5028_50280402_117_dialog_content = "Por favor, não.",
  ui_story_5028_50280402_118_dialog_content = "Eu recomendo que você primeiro procure um médico para o seu transtorno de competitividade crônica. Volte e nos encontre depois de alguns meses de terapia.",
  ui_story_5028_50280402_119_dialog_content = "Você só vai causar problemas. E você mal conhece o celestita.",
  ui_story_5028_50280402_120_dialog_content = "A menos que você esteja de olho nele por algum motivo? Precisa de outro membro para sua comitiva ruim?",
  ui_story_5028_50280402_121_dialog_content = "Ah, relaxe, Smokey. Não é na Caelestita que estou de olho.",
  ui_story_5028_50280402_122_dialog_content = "Gostaria de saber quem tem a infelicidade de ser tão abençoado.",
  ui_story_5028_50280402_123_dialog_content = "Huh. vou ver se PlayerName está por trás dessas lixeiras.",
  ui_story_5028_50280501_1_dialog_content = "Teste: Seaside Secret",
  ui_story_5028_50280501_2_dialog_content = "Que sol deslumbrante e tórrido...",
  ui_story_5028_50280501_3_dialog_content = "E a brisa do mar é enevoada, mas revigorante.",
  ui_story_5028_50280501_4_dialog_content = "E olhe para as multidões!",
  ui_story_5028_50280501_5_dialog_content = "Eu não posso acreditar que estou de volta aqui novamente.",
  ui_story_5028_50280501_6_dialog_content = "estou fervendo! E aqui está muito cheio.",
  ui_story_5028_50280501_7_dialog_content = "Ei!",
  ui_story_5028_50280501_8_dialog_content = "É realmente o momento perfeito para uma viagem à beira-mar.",
  ui_story_5028_50280501_9_dialog_content = "Ai!",
  ui_story_5028_50280501_10_dialog_content = "Ah, você está bem?",
  ui_story_5028_50280501_11_dialog_content = "Eu estou bem, obrigado.",
  ui_story_5028_50280501_12_dialog_content = "Aposto que você está pensando: \"Se ao menos tivesse sido uma garota bonita.\"",
  ui_story_5028_50280501_13_dialog_content = "Eu não sou!",
  ui_story_5028_50280501_14_dialog_content = "Ou talvez você goste mais de garotos em forma como ele?",
  ui_story_5028_50280501_15_dialog_content = "Não! Pare com isso.",
  ui_story_5028_50280501_16_dialog_content = "Sabe, acho que seu mestre deve se preocupar muito com você.",
  ui_story_5028_50280501_17_dialog_content = "Isso parece mais um feriado à beira-mar, não algum tipo de teste.",
  ui_story_5028_50280501_18_dialog_content = "Sim, certo, como se aquele homem estúpido fosse tão generoso.",
  ui_story_5028_50280501_19_dialog_content = "É tão lotado aqui, eu odeio isso. E ele nunca me disse por que me mandaria para um lugar como este.",
  ui_story_5028_50280501_20_dialog_content = "Tudo o que ele fez foi me dizer para escovar aquelas bolinhas de pelo, raspar aquelas bolinhas de pelo. Então ele venderia a pele.",
  ui_story_5028_50280501_21_dialog_content = "E saía bebendo e se divertindo com o dinheiro...",
  ui_story_5028_50280501_22_dialog_content = "E eu ficaria em casa. Fazendo forragem para os Fatwrens. Limpando após o Cocodeer. Sendo liderado pelo Speedhound para uma corrida.",
  ui_story_5028_50280501_23_dialog_content = "Você pode imaginar? Uma jovem adorável como eu, usada por ele como serva.",
  ui_story_5028_50280501_24_dialog_content = "E agora aqui estou eu, enviado para fazer trabalho de campo com as mais mesquinhas instruções.",
  ui_story_5028_50280501_25_dialog_content = "Lo, lo.",
  ui_story_5028_50280501_26_dialog_content = "Por que você decidiu ser seu aprendiz então?",
  ui_story_5028_50280501_27_dialog_content = "Além disso, você continua fazendo as tarefas que ele lhe dá, mesmo que reclame constantemente.",
  ui_story_5028_50280501_28_dialog_content = "Sim. Foi uma espécie de culpa do destino que eu o conheci.",
  ui_story_5028_50280501_29_dialog_content = "Eu era obcecado por este livro quando era criança chamado \"<color=#FFB400>1.001 Criaturas Fantásticas</color>.\"",
  ui_story_5028_50280501_30_dialog_content = "Pode-se dizer que esse livro definiu minha infância.",
  ui_story_5028_50280501_30X_dialog_content = "Foi o que me deu essa afinidade com os animais e me permitiu me comunicar com eles.",
  ui_story_5028_50280501_31_dialog_content = "Mas em Umbraton, há muitos Aurorianos e basicamente nenhuma besta maravilhosa. Eu não gostei disso, então decidi.",
  ui_story_5028_50280501_32_dialog_content = "Decidi que encontraria o autor daquele livro e faria com que ele me dissesse onde encontrar todos aqueles animais maravilhosos com os quais sonhava todas as noites.",
  ui_story_5028_50280501_33_dialog_content = "Arrumei minhas malas, me despedi de meus pais e fui para a floresta onde diziam que o autor morava.",
  ui_story_5028_50280501_34_dialog_content = "Passei dias procurando por ele e não encontrei nada. Então, um dia, eu estava sentado ao lado da minha barraca assando castanhas quando esse homem apareceu.",
  ui_story_5028_50280501_35_dialog_content = "Ele apenas rastejou para fora da vegetação rasteira e veio em minha direção, parecendo meio faminto.",
  ui_story_5028_50280501_36_dialog_content = "Não me diga que foi...",
  ui_story_5028_50280501_37_dialog_content = "Sim. Mas na época eu não tinha ideia de que era ele.",
  ui_story_5028_50280501_38_dialog_content = "Depois de comer, ele me disse aleatoriamente: \"Sou o maior extrozoólogo do continente. Estou fazendo uma pesquisa ecológica aqui perto\".",
  ui_story_5028_50280501_39_dialog_content = "Ele parecia tanto com uma espécie de golpista que quase corri de volta para a cidade para chamar os guardas.",
  ui_story_5028_50280501_40_dialog_content = "Mas então ele me mostrou as notas quase legíveis, mas definitivamente genuínas, que ele tinha sobre ele, bem como todo o seu equipamento estranho.",
  ui_story_5028_50280501_41_dialog_content = "Com apenas um assobio, ele foi capaz de atrair uma variedade de bestas maravilhosas que habitavam a floresta ao redor.",
  ui_story_5028_50280501_42_dialog_content = "PlayerName, você se lembra de quando conhecemos a Bica?",
  ui_story_5028_50280501_43_dialog_content = "Você notou que eu podia me comunicar com as bestas maravilhosas, não é? Como a ligação psíquica que você tem com os aurorianos.",
  ui_story_5028_50280501_44_dialog_content = "Foi assim que consegui entender a Bica e o filhote de Drakolion. E... bem, eu gosto mais de interagir com bestas maravilhosas do que com Aurorianos.",
  ui_story_5028_50280501_45_dialog_content = "Honestamente, eu devo ter me empolgado por estar cercado por bestas maravilhosas na época.",
  ui_story_5028_50280501_46_dialog_content = "Não ajudou que ele continuasse me dizendo que minha capacidade de me comunicar com eles me tornaria um ótimo extrozoólogo.",
  ui_story_5028_50280501_47_dialog_content = "A ideia de ser um extrozoólogo era como um sonho tornado realidade. Não resisti à tentação.",
  ui_story_5028_50280501_48_dialog_content = "Mesmo agora, se eu pudesse escolher novamente, acho que ainda escolheria ser seu aprendiz.",
  ui_story_5028_50280501_49_dialog_content = "Desde aquele momento, acreditei piamente que ele era o grande extrozoologista Vic, autor do livro que eu tanto amava.",
  ui_story_5028_50280501_50_dialog_content = "Escolhi esta vida para mim, mas ainda assim, devo dizer que ele é um péssimo mentor!",
  ui_story_5028_50280501_51_dialog_content = "Haha. Mas você tem feito o que você ama todo esse tempo.",
  ui_story_5028_50280501_52_dialog_content = "Ai!",
  ui_story_5028_50280501_53_dialog_content = "Cuidado!",
  ui_story_5028_50280501_54_dialog_content = "Oh, desculpe. Eu escorreguei.",
  ui_story_5028_50280501_55_dialog_content = "Sem problemas. Desde que você esteja bem.",
  ui_story_5028_50280501_56_dialog_content = "(Novamente?)",
  ui_story_5028_50280501_57_dialog_content = "Desculpe. Então, er... Na verdade, eu acho...",
  ui_story_5028_50280501_58_dialog_content = "É assim que a vida é. As coisas nem sempre correm bem. Você já tem mais sorte do que muita gente.",
  ui_story_5028_50280501_59_dialog_content = "Uau, ver você tentando soar madura como um adulto é bastante constrangedor.",
  ui_story_5028_50280501_60_dialog_content = "A menina bonita caindo em seus braços lhe deu uma concussão?",
  ui_story_5028_50280501_61_dialog_content = "Oh, pelo amor de Deus, ela não caiu em meus braços! Eu só a impedi de cair.",
  ui_story_5028_50280501_62_dialog_content = "A propósito, seu tom... isso é ciúme?",
  ui_story_5028_50280501_63_dialog_content = "Ah. Como se eu tivesse tempo para essas bobagens tediosas. Estou muito feliz com minhas bestas maravilhosas como companhia, obrigado.",
  ui_story_5028_50280501_64_dialog_content = "Há mais sal em suas palavras do que o oceano.",
  ui_story_5028_50280501_65_dialog_content = "Você-!",
  ui_story_5028_50280501_66_dialog_content = "Ok, de volta aos negócios. Se você pode conversar com animais maravilhosos, isso significa que você será um excelente extrozoólogo.",
  ui_story_5028_50280501_67_dialog_content = "Assim como minha habilidade de formar ligações psíquicas com o auroriano me torna um bom comandante de campo de batalha.",
  ui_story_5028_50280501_68_dialog_content = "Embora isso seja verdade, há exceções. Minhas habilidades não funcionam em Kyllo, por exemplo.",
  ui_story_5028_50280501_69_dialog_content = "Ei!",
  ui_story_5028_50280501_70_dialog_content = "Por quê?",
  ui_story_5028_50280501_71_dialog_content = "Eu não sei... O Mestre diz que é um tipo especial de besta maravilhosa. Um exótico.",
  ui_story_5028_50280501_72_dialog_content = "Ei!",
  ui_story_5028_50280501_73_dialog_content = "Exótico? Certamente apenas algo como um Drakolion seria considerado exótico?",
  ui_story_5028_50280501_74_dialog_content = "Veja, nem você acredita no que ele diz.",
  ui_story_5028_50280501_75_dialog_content = "Lo... Lo...",
  ui_story_5028_50280501_76_dialog_content = "Não fique triste, Kyllo.",
  ui_story_5028_50280501_77_dialog_content = "Posso não ser capaz de te entender, mas sei que você é um bom Kyllo.",
  ui_story_5028_50280501_78_dialog_content = "Ei!",
  ui_story_5028_50280501_79_dialog_content = "Inútil, talvez. E praticamente inútil.",
  ui_story_5028_50280501_80_dialog_content = "Ei!",
  ui_story_5028_50280501_81_dialog_content = "Ahhhh!",
  ui_story_5028_50280501_82_dialog_content = "Por que todo mundo está caindo?",
  ui_story_5028_50280501_83_dialog_content = "Eu sabia que havia algo errado com este lugar. Vamos ver!",
  ui_story_5028_50280501_84_dialog_content = "Ei! Fia, não corra—",
  ui_story_5028_50280501_85_dialog_content = "Uau!",
  ui_story_5028_50280501_86_dialog_content = "Ei!",
  ui_story_5028_50280501_87_dialog_content = "O-obrigado, PlayerName.",
  ui_story_5028_50280501_88_dialog_content = "Honestamente, por que você correu tão rápido sabendo como é fácil escorregar aqui?",
  ui_story_5028_50280501_89_dialog_content = "Desculpe... fiquei animado. Você poderia me colocar para baixo?",
  ui_story_5028_50280501_90_dialog_content = "Ah, certo.",
  ui_story_5028_50280501_91_dialog_content = "Ah, eu sabia!",
  ui_story_5028_50280501_92_dialog_content = "O quê?",
  ui_story_5028_50280501_93_dialog_content = "Você não pode vê-lo? A coisa grudou no meu pé.",
  ui_story_5028_50280501_94_dialog_content = "Essa coisa translúcida é um <color=#FFB400>Glooey</color>.",
  ui_story_5028_50280501_95_dialog_content = "Gloo.",
  ui_story_5028_50280501_96_dialog_content = "Eles geralmente vivem na água, mas sobem para a terra para respirar.",
  ui_story_5028_50280501_97_dialog_content = "Mas ser transparente significa que eles são fáceis de pisar por acidente.",
  ui_story_5028_50280501_98_dialog_content = "Mas há muitos Aurorianos por aqui. Acho que este lugar não é mais seguro para eles.",
  ui_story_5028_50280501_99_dialog_content = "Devem ter vindo todos à terra para migrar para um novo lar.",
  ui_story_5028_50280501_100_dialog_content = "Mas eles se movem muito devagar e todo mundo continua escorregando neles. Se isso continuar, Glooeys e turistas vão acabar se machucando.",
  ui_story_5028_50280501_101_dialog_content = "(Ela sempre fica séria assim que começa a falar sobre bestas maravilhosas.)",
  ui_story_5028_50280501_102_dialog_content = "Deve ser disso que se trata o nosso teste: ajudar os Glooeys a se mudarem para um novo lar!",
  ui_story_5028_50280501_103_dialog_content = "Sim. Vamos juntar os que foram espalhados pela multidão. Então podemos escoltá-los em segurança.",
  ui_story_5028_50280501_104_dialog_content = "Kyllo, pare de brincar com o Glooey. Venha ajudar!",
  ui_story_5028_50280501_105_dialog_content = "Ei!",
  ui_story_5028_50280501_106_dialog_content = "Ufa. Esse é o último?",
  ui_story_5028_50280501_107_dialog_content = "Gloo...",
  ui_story_5028_50280501_108_dialog_content = "Sim. Parece que estão todos rastejando na mesma direção.",
  ui_story_5028_50280501_109_dialog_content = "Eles estarão procurando uma parte mais tranquila do litoral para habitar. Só precisamos garantir que eles cheguem lá.",
  ui_story_5028_50280501_110_dialog_content = "Espere. Acho que vejo Eclipses à frente. Você poderia pedir aos Glooeys para desviar deles?",
  ui_story_5028_50280501_111_dialog_content = "Eu não posso, eles são muito teimosos. É por isso que eles não saem do caminho e são pisados o tempo todo.",
  ui_story_5028_50280501_112_dialog_content = "E são apenas alguns Eclipsites fedorentos. Por que devemos nos esconder?",
  ui_story_5028_50280501_113_dialog_content = "Deixe-os para mim desta vez. Eu vou combatê-los!",
  ui_story_5028_50280502_1_dialog_content = "<color=#e8d9bb>*Ondas quebrando*</color>",
  ui_story_5028_50280502_2_dialog_content = "Aqui é muito mais tranquilo. Não consigo nem ouvir gaivotas.",
  ui_story_5028_50280502_3_dialog_content = "Acho que esta será uma boa casa para os Glooeys.",
  ui_story_5028_50280502_4_dialog_content = "Glória... Glória...",
  ui_story_5028_50280502_5_dialog_content = "Da próxima vez, tome mais cuidado! Certifique-se de migrar antes que os turistas cheguem, não depois.",
  ui_story_5028_50280502_6_dialog_content = "Ei! Os turistas que escorregam e caem são inocentes, você sabe.",
  ui_story_5028_50280502_7_dialog_content = "Mas entre as massas de Eclipsites e mudanças ambientais drásticas, habitats de animais maravilhosos estão ficando cada vez mais difíceis de encontrar.",
  ui_story_5028_50280502_8_dialog_content = "Muitos deles realmente protegem Aurorianos o tempo todo, você sabia disso?",
  ui_story_5028_50280502_9_dialog_content = "Muitas feras maravilhosas vivem perto das cidades, onde servem como a primeira linha de defesa dos Aurorianos, avistando e lutando contra invasores do Eclipsite.",
  ui_story_5028_50280502_10_dialog_content = "Nossa, eu não sabia disso.",
  ui_story_5028_50280502_11_dialog_content = "De qualquer forma, esse é mais um julgamento concluído. Mais um dia produtivo de ajuda a bestas maravilhosas!",
  ui_story_5028_50280502_12_dialog_content = "(Eh? Tem algo pegajoso na minha perna.)",
  ui_story_5028_50280502_13_dialog_content = "Gloo...",
  ui_story_5028_50280502_14_dialog_content = "Você diz que viu um monstro aterrorizante por aqui, mas ninguém mais acredita em você? Então você gostaria de ficar comigo?",
  ui_story_5028_50280502_15_dialog_content = "Heehee. Suas linhas de captação são um pouco clichê.",
  ui_story_5028_50280502_16_dialog_content = "Mas claro, por que não. Você pode se juntar aos outros!",
  ui_story_5028_50280502_17_dialog_content = "PlayerName, olhar. Temos mais um novo companheiro!",
  ui_story_5028_50280502_18_dialog_content = "Ei!",
  ui_story_5028_50280502_19_dialog_content = "Outro? Você é sempre tão popular com eles?",
  ui_story_5028_50280502_20_dialog_content = "Oi!",
  ui_story_5028_50280502_21_dialog_content = "É claro. Eu vou ser um extrozoólogo, eu preciso fazer amizade com todas as feras maravilhosas.",
  ui_story_5028_50280502_22_dialog_content = "Mas vou dar alguns ao meu mestre para cuidar se acabar com muitos. Estar comigo pode nem sempre ser seguro para eles, afinal.",
  ui_story_5028_50280502_23_dialog_content = "Eu vejo. Bem, eu poderia incomodar nossa especialista residente para me dizer quantos testes ela tem que completar?",
  ui_story_5028_50280502_24_dialog_content = "Hum. Deixe-me ver.",
  ui_story_5028_50280502_25_dialog_content = "Incrível! Oh. Droga!",
  ui_story_5028_50280502_26_dialog_content = "Lo?",
  ui_story_5028_50280502_27_dialog_content = "O quê?",
  ui_story_5028_50280502_28_dialog_content = "Bem, você poderia dizer que eu terminei, mas também é possível que eu nunca termine.",
  ui_story_5028_50280502_29_dialog_content = "Do que você está falando?",
  ui_story_5028_50280502_30_dialog_content = "Hum, eu terminei todos os testes perigosos!",
  ui_story_5028_50280502_31_dialog_content = "Mas como vou terminar esta: memorizar a Enciclopédia Exótica do Mestre Vic?",
  ui_story_5028_50280502_32_dialog_content = "Eca. Estou trabalhando nisso há uma semana e só memorizei duas páginas e meia.",
  ui_story_5028_50280502_33_dialog_content = "Ei...",
  ui_story_5028_50280502_34_dialog_content = "Hmm, luta e força bruta não serão suficientes para este.",
  ui_story_5028_50280502_35_dialog_content = "Posso ser um celestita, mas ainda não tenho como enraizar toda essa informação na sua cabeça.",
  ui_story_5028_50280502_36_dialog_content = "... Ei!",
  ui_story_5028_50280502_37_dialog_content = "Suspirar...",
  ui_story_5028_50280502_38_dialog_content = "Ei! Ei!",
  ui_story_5028_50280502_39_dialog_content = "Eh? Kyllo, pare, o que você está fazendo?",
  ui_story_5028_50280502_40_dialog_content = "Pare de puxar o caderno, você vai rasgá-lo!",
  ui_story_5028_50280502_41_dialog_content = "Ei!",
  ui_story_5028_50280502_42_dialog_content = "Eu disse, não... Ah!",
  ui_story_5028_50280502_43_dialog_content = "Fia, tudo bem?",
  ui_story_5028_50280502_44_dialog_content = "Você está procurando uma briga, Kyllo?!",
  ui_story_5028_50280502_45_dialog_content = "Espere, está folheando o notebook.",
  ui_story_5028_50280502_46_dialog_content = "O quê?",
  ui_story_5028_50280502_47_dialog_content = "Ei! Ei!",
  ui_story_5028_50280502_48_dialog_content = "Esta página... é sobre um coelho?",
  ui_story_5028_50280502_49_dialog_content = "Um coelho?",
  ui_story_5028_50280502_50_dialog_content = "Estamos aqui.",
  ui_story_5028_50280502_51_dialog_content = "Huh? É aqui que termina o lead pelo qual você pagou todo esse dinheiro?",
  ui_story_5028_50280502_52_dialog_content = "Imagine cair nesse golpe depois de tantos anos em Umbraton.",
  ui_story_5028_50280502_53_dialog_content = "Ou você só queria me levar para um encontro à beira-mar? Desculpe desapontá-lo, mas não trouxe meu maiô.",
  ui_story_5028_50280502_54_dialog_content = "Haha. Acontece que eu tenho o meu.",
  ui_story_5028_50280502_55_dialog_content = "Aposto que você está se arrependendo de não usar esse seu maiô minúsculo agora, não é?",
  ui_story_5028_50280502_56_dialog_content = "Agora você está preso parecendo vestido demais para a beira-mar sozinho como um tolo.",
  ui_story_5028_50280502_57_dialog_content = "Você não tem ideia de quanto tempo esperei para ver esse olhar de inveja em seu rosto.",
  ui_story_5028_50280502_58_dialog_content = "Você! Vou jogá-lo no mar, depois vá procurar o celestita.",
  ui_story_5028_50280502_59_dialog_content = "Haha. Sejamos honestos, quem se importa com o celestita? Eu só vim desde que eu tive tempo para matar.",
  ui_story_5028_50280502_60_dialog_content = "Não é esse também o motivo de sua vinda?",
  ui_story_5028_50280502_61_dialog_content = "Oh, por favor, minhas motivações não são tão superficiais. Faça-me um favor e não projete.",
  ui_story_5028_50280502_62_dialog_content = "Vejo isso como uma oportunidade de provar de uma vez por todas que sou melhor que você!",
  ui_story_5028_50280502_63_dialog_content = "Não confiando em um maiô minúsculo, mas usando minhas habilidades como caçadora de recompensas profissional!",
  ui_story_5028_50280502_64_dialog_content = "Oh? Isso é uma grande conversa para alguém que esqueceu de trazer um maiô para a praia.",
  ui_story_5028_50280502_65_dialog_content = "Ooh legal! Eu quero um maiô também.",
  ui_story_5028_50280502_66_dialog_content = "Sorria para a câmera!",
  ui_story_5028_50280502_67_dialog_content = "<color=#e8d9bb>Clique!</color>",
  ui_story_5028_50280502_68_dialog_content = "Lester?",
  ui_story_5028_50280502_69_dialog_content = "Ei, não é isso Smokey!?",
  ui_story_5028_50280502_70_dialog_content = "O que você está fazendo aqui? Ainda na sua viagem?",
  ui_story_5028_50280502_71_dialog_content = "É claro. Vocês dois parecem familiares também, estão todos aqui para umas férias na praia?",
  ui_story_5028_50280502_72_dialog_content = "Aqui, olhe para a foto que eu tirei de você.",
  ui_story_5028_50280502_73_dialog_content = "Ah, obrigado.",
  ui_story_5028_50280502_74_dialog_content = "... Deixe-me ver.",
  ui_story_5028_50280502_75_dialog_content = "Eu acho que você poderia chamar isso de uma mini-pausa. Além disso, também estamos procurando por um amigo que foi sequestrado ou perdido ou algo assim.",
  ui_story_5028_50280502_76_dialog_content = "Oh hey, você realmente o conhece, o celestita.",
  ui_story_5028_50280502_77_dialog_content = "O celestita está desaparecido? O único celestita que resta no continente está desaparecido?",
  ui_story_5028_50280502_78_dialog_content = "Sim, o único ou o que quer que seja, de qualquer maneira ele se foi.",
  ui_story_5028_50280502_79_dialog_content = "Eu vejo. Bem, vou manter meus olhos abertos para ele.",
  ui_story_5028_50280502_80_dialog_content = "E se acontecer de eu encontrá-lo, eu o trarei de volta para vocês.",
  ui_story_5028_50280601_1_dialog_content = "Trial: Memorize a Enciclopédia Exótica",
  ui_story_5028_50280601_2_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5028_50280601_3_dialog_content = "<color=#e8d9bb>Bate, bate!</color>",
  ui_story_5028_50280601_4_dialog_content = "O suficiente! Segure seu fogo.",
  ui_story_5028_50280601_5_dialog_content = "Você vai assustar a presa.",
  ui_story_5028_50280601_6_dialog_content = "Tch, e aqueles dois? Vamos deixá-los ir?",
  ui_story_5028_50280601_7_dialog_content = "Não há tempo. Precisamos pegar isso <color=#FFB400>coelho peko</color> em breve para <color=#FFB400>Gary</color>.",
  ui_story_5028_50280601_8_dialog_content = "Se deixarmos o chefe bravo, estaremos em apuros.",
  ui_story_5028_50280601_9_dialog_content = "Hmm...",
  ui_story_5028_50280601_10_dialog_content = "Ahhh—Ahhh—",
  ui_story_5028_50280601_11_dialog_content = "Atchim!",
  ui_story_5028_50280601_12_dialog_content = "Shiu.",
  ui_story_5028_50280601_13_dialog_content = "Eles foram embora.",
  ui_story_5028_50280601_14_dialog_content = "Lo.",
  ui_story_5028_50280601_15_dialog_content = "Ainda bem que Kyllo teve a previsão de encontrar esse arbusto coberto de neve para nos escondermos.",
  ui_story_5028_50280601_16_dialog_content = "Ei!",
  ui_story_5028_50280601_17_dialog_content = "Achoooo!",
  ui_story_5028_50280601_18_dialog_content = "Achoo! Achoo! Achoo!",
  ui_story_5028_50280601_19_dialog_content = "Você está bem? Aqui, limpe o nariz.",
  ui_story_5028_50280601_20_dialog_content = "*Sniff* Obrigado.",
  ui_story_5028_50280601_21_dialog_content = "Eu odeio este lugar. Minhas mãos e pés estão congelados.",
  ui_story_5028_50280601_22_dialog_content = "Eu nunca teria chegado a um lugar tão frio se não fosse por querer pegar um daqueles coelhos Peko mencionados no caderno.",
  ui_story_5028_50280601_23_dialog_content = "Aqui, pegue meu casaco. Ah, e eu tenho um cachecol reserva.",
  ui_story_5028_50280601_24_dialog_content = "Não, duvido que você duraria muito sem eles também.",
  ui_story_5028_50280601_25_dialog_content = "Coma isso.",
  ui_story_5028_50280601_26_dialog_content = "Milímetros?!",
  ui_story_5028_50280601_27_dialog_content = "É uma pílula feita de verme da areia em pó, óleo combustível e capim-sol.",
  ui_story_5028_50280601_28_dialog_content = "Ajuda a mantê-lo aquecido em ambientes frios.",
  ui_story_5028_50280601_29_dialog_content = "Mas este é o único que me resta desde que fiquei sem pó de verme da areia recentemente.",
  ui_story_5028_50280601_30_dialog_content = "Eu me sinto muito mais quente. Mas e voce?",
  ui_story_5028_50280601_31_dialog_content = "Vou usar Glooey como isolamento extra no meu corpo.",
  ui_story_5028_50280601_32_dialog_content = "Gloo...",
  ui_story_5028_50280601_33_dialog_content = "Se eu desmaiar de frio, você pode me carregar da montanha e pedir ajuda.",
  ui_story_5028_50280601_34_dialog_content = "Mas se você desmaiar, não posso fazer nada além de deixá-lo aqui.",
  ui_story_5028_50280601_35_dialog_content = "Oh, certo. Certo, se acontecer alguma coisa, eu vou tirar você deste lugar com certeza.",
  ui_story_5028_50280601_36_dialog_content = "Embora agora que penso nisso, não tenho certeza se você é forte o suficiente para me carregar. Talvez você devesse cuspir a pílula para que Kyllo pudesse tomá-la.",
  ui_story_5028_50280601_37_dialog_content = "Tarde demais, já está no meu estômago.",
  ui_story_5028_50280601_38_dialog_content = "Haha. Eu estava apenas brincando.",
  ui_story_5028_50280601_39_dialog_content = "Lo?",
  ui_story_5028_50280601_40_dialog_content = "Ok, agora que estamos todos nos sentindo melhor, devemos nos mexer.",
  ui_story_5028_50280601_41_dialog_content = "Precisamos encontrar o coelho Peko antes dos caçadores.",
  ui_story_5028_50280601_42_dialog_content = "Este coelho é realmente tão raro? Com certeza conseguiu atrair muitos caçadores para este lugar esquecido por Deus.",
  ui_story_5028_50280601_43_dialog_content = "E eles parecem organizados e profissionais. O chefe deles deve ter gasto uma fortuna.",
  ui_story_5028_50280601_44_dialog_content = "Hmph. Não importa quantos idiotas eles enviem.",
  ui_story_5028_50280601_45_dialog_content = "Mão-de-obra, armas, cães... Nada disso lhes servirá de nada. Nem aquelas armadilhas que colocaram nas colinas.",
  ui_story_5028_50280601_46_dialog_content = "Um coelho Peko nunca seria pego dessa maneira.",
  ui_story_5028_50280601_47_dialog_content = "Bem, se caçadores profissionais não conseguem, como vamos conseguir?",
  ui_story_5028_50280601_48_dialog_content = "Relaxar. Não se esqueça, eu sou um extrozoologista experiente!",
  ui_story_5028_50280601_49_dialog_content = "Posso pegar um coelho Peko tão facilmente quanto estalar os dedos.",
  ui_story_5028_50280601_50_dialog_content = "Argh... Meus dedos estão congelados novamente.",
  ui_story_5028_50280601_51_dialog_content = "Encontrou o caderno? Devo ajudá-lo a olhar?",
  ui_story_5028_50280601_52_dialog_content = "Não, obrigado! Eu tenho.",
  ui_story_5028_50280601_53_dialog_content = "Eles são alertas e inteligentes, o que os torna difíceis de capturar. Eles gostam de comer livros.",
  ui_story_5028_50280601_54_dialog_content = "Perfeito! Podemos usar um livro como isca—",
  ui_story_5028_50280601_55_dialog_content = "Se você acha que é tão fácil quanto jogar um livro como isca e capturar um, devemos desistir agora mesmo.",
  ui_story_5028_50280601_56_dialog_content = "Finja que não disse nada.",
  ui_story_5028_50280601_57_dialog_content = "Eles são muito espertos. Um livro deitado na neve os deixará cautelosos.",
  ui_story_5028_50280601_58_dialog_content = "Mas talvez possamos usar a curiosidade deles contra eles. A grama é mais verde do outro lado e tudo mais.",
  ui_story_5028_50280601_59_dialog_content = "Como podemos fazer isso? Ei, PlayerName, me dê aquele livro que você tem lido ultimamente.",
  ui_story_5028_50280601_60_dialog_content = "O que é isto? \"A garota ao meu lado às vezes esconde seus sentimentos em eclipsiano\"?",
  ui_story_5028_50280601_61_dialog_content = "Por que seu título é tão obscenamente longo?",
  ui_story_5028_50280601_62_dialog_content = "Sim. Foi um presente do Sr. Peng, o cara do vinhedo. Ele escreveu.",
  ui_story_5028_50280601_63_dialog_content = "Ele até assinou. Ele disse que valeria muito em alguns anos.",
  ui_story_5028_50280601_64_dialog_content = "Oh, eu vejo. Bem, prefiro arriscar isso do que o caderno do Mestre.",
  ui_story_5028_50280601_65_dialog_content = "Suspirar...",
  ui_story_5028_50280601_66_dialog_content = "De alguma forma, parece que você acabou de insultar a mim e ao Sr. Peng, embora você claramente não tenha dito nada...",
  ui_story_5028_50280601_67_dialog_content = "Menos chat, mais trabalho. Precisamos pegar aquele coelho antes dos caçadores.",
  ui_story_5028_50280601_68_dialog_content = "Esconda-se, vou começar a ler.",
  ui_story_5028_50280601_69_dialog_content = "Quando o Peko aparecer, pressione o botão.",
  ui_story_5028_50280601_70_dialog_content = "Isso não vai te prender na rede também?",
  ui_story_5028_50280601_71_dialog_content = "E daí? Não vai me morder.",
  ui_story_5028_50280601_72_dialog_content = "E se isso acontecer, eu vou morder de volta. Mais difíceis.",
  ui_story_5028_50280601_73_dialog_content = "<color=#e8d9bb>Algum tempo depois</color>",
  ui_story_5028_50280601_74_dialog_content = "Peko?",
  ui_story_5028_50280601_75_option_content = "Mindlink com Fia",
  ui_story_5028_50280601_76_dialog_content = "Alguma coisa está vindo. Fique parado.",
  ui_story_5028_50280601_77_dialog_content = "Entendi. E não perca sua chance.",
  ui_story_5028_50280601_78_dialog_content = "Ei...",
  ui_story_5028_50280601_79_dialog_content = "Peko Peko...",
  ui_story_5028_50280601_80_dialog_content = "(Hehehe, é isso. Siga sua curiosidade e venha até mim.)",
  ui_story_5028_50280601_81_dialog_content = "Peko...",
  ui_story_5028_50280601_82_dialog_content = "Não é bom. Este pequeno animal suspeito continua pulando na borda da rede, sem vontade de ir mais longe.",
  ui_story_5028_50280601_83_dialog_content = "Se o acionarmos agora, provavelmente escapará, e nunca teremos outra chance como essa.",
  ui_story_5028_50280601_84_dialog_content = "Só há uma opção. Eu vou dar um jeito nele. Modo de espera, PlayerName.",
  ui_story_5028_50280601_85_dialog_content = "Agora...",
  ui_story_5028_50280601_86_dialog_content = "Peko?",
  ui_story_5028_50280601_87_dialog_content = "Pare!",
  ui_story_5028_50280601_88_dialog_content = "Peko!!",
  ui_story_5028_50280601_89_dialog_content = "Entendi!",
  ui_story_5028_50280601_90_dialog_content = "Eu entendi! Eu entendi!",
  ui_story_5028_50280601_91_dialog_content = "Peko peko peko peko!!",
  ui_story_5028_50280601_92_dialog_content = "Uau, você acabou de gritar com o coelho Peko e o aterrorizou até a submissão.",
  ui_story_5028_50280601_93_dialog_content = "Não sei se ter essa ideia em uma fração de segundo o torna inteligente ou louco.",
  ui_story_5028_50280601_94_dialog_content = "Heehee, vou levar isso como um elogio. E não fique aí parado, tire nós dois daqui.",
  ui_story_5028_50280601_95_dialog_content = "Heheheh. Agora poderei completar o julgamento final.",
  ui_story_5028_50280601_96_dialog_content = "Pe... Peko...",
  ui_story_5028_50280601_97_dialog_content = "Ei!",
  ui_story_5028_50280601_98_dialog_content = "Como o coelho Peko vai ajudá-lo no julgamento?",
  ui_story_5028_50280601_99_dialog_content = "De acordo com o caderno, os coelhos Peko podem absorver o conhecimento dos livros e depois transferi-lo para outras pessoas.",
  ui_story_5028_50280601_100_dialog_content = "Cheguei a um ponto em que algo assim nem me surpreende. Então, como isso realmente funciona?",
  ui_story_5028_50280601_101_dialog_content = "Vamos ver. Primeiro, prepare o livro que contém as informações que você precisa para transferir e alimente o Peko.",
  ui_story_5028_50280601_102_dialog_content = "Bem, suponho que posso aceitar que isso é normal. Para um animal maravilhoso.",
  ui_story_5028_50280601_103_dialog_content = "E depois?",
  ui_story_5028_50280601_104_dialog_content = "Então... aqueça um pouco de óleo em uma panela... adicione a cebola, o gengibre e o alho... frite até perfumar...",
  ui_story_5028_50280601_105_dialog_content = "?",
  ui_story_5028_50280601_106_dialog_content = "Peko!!",
  ui_story_5028_50280601_107_dialog_content = "Ei!!",
  ui_story_5028_50280601_108_dialog_content = "Adicione um pouco de açúcar e cozinhe até caramelizar. Em seguida, esfolie a...",
  ui_story_5028_50280601_109_dialog_content = "Você está me dizendo que devemos assá-lo?",
  ui_story_5028_50280601_110_dialog_content = "Parece... mas... como é que isso... Aquele homem estúpido!",
  ui_story_5028_50280601_111_dialog_content = "Talvez comer apenas uma perna funcione?",
  ui_story_5028_50280601_112_dialog_content = "Peko peko peko!",
  ui_story_5028_50280601_113_dialog_content = "Não faça piadas assim, o Peko já está apavorado.",
  ui_story_5028_50280601_114_dialog_content = "Espere, acho que está tentando nos avisar de algo.",
  ui_story_5028_50280601_115_dialog_content = "Sobre o que? Desistimos dos caçadores.",
  ui_story_5028_50280601_116_dialog_content = "Está dizendo... <color=#FFB400>Eclipses!</color>",
  ui_story_5028_50280602_1_dialog_content = "Cada vez! Essas pragas!",
  ui_story_5028_50280602_2_dialog_content = "Por que eles estão em todos os lugares? Eu deveria reconsiderar minha carreira. Seria muito mais fácil ser um eclipsitologista.",
  ui_story_5028_50280602_3_dialog_content = "Graças a Deus nos avisou, ou estaríamos cercados.",
  ui_story_5028_50280602_4_dialog_content = "Peko peko!",
  ui_story_5028_50280602_5_dialog_content = "Bem, nós definitivamente não podemos comê-lo. E o seu julgamento?",
  ui_story_5028_50280602_6_dialog_content = "Vou precisar pensar em outra coisa. Eu não seria um grande extrozoólogo se prejudicasse animais maravilhosos para meu próprio benefício.",
  ui_story_5028_50280602_7_dialog_content = "Eu nunca, mesmo que isso signifique nunca completar meu julgamento.",
  ui_story_5028_50280602_8_dialog_content = "Ah, mas o que eu vou fazer?",
  ui_story_5028_50280602_9_dialog_content = "Peko...",
  ui_story_5028_50280602_10_dialog_content = "Ei...",
  ui_story_5028_50280602_11_dialog_content = "Gloo...",
  ui_story_5028_50280602_12_dialog_content = "Obrigado por me consolar.",
  ui_story_5028_50280602_13_dialog_content = "Tem que haver alguma outra maneira.",
  ui_story_5028_50280602_14_dialog_content = "Deve haver uma maneira de nos ajudar sem prejudicá-lo.",
  ui_story_5028_50280602_15_dialog_content = "Eu sei!",
  ui_story_5028_50280602_16_dialog_content = "Peko, você quer ouvir meu plano perfeito?",
  ui_story_5028_50280602_17_dialog_content = "Peko!",
  ui_story_5028_50280602_17X1_dialog_content = "Afe!",
  ui_story_5028_50280602_18_dialog_content = "Hum? Está se aconchegando em você de felicidade.",
  ui_story_5028_50280602_19_dialog_content = "Heheh! Essa é a minha afinidade com os animais!",
  ui_story_5028_50280602_19X1_dialog_content = "Ok, ok... Então, qual é o seu plano?",
  ui_story_5028_50280602_19X2_dialog_content = "Seria difícil para os outros, mas é moleza para mim.",
  ui_story_5028_50280602_19X3_dialog_content = "Lembrar? Eu posso entender bestas maravilhosas.",
  ui_story_5028_50280602_19X4_dialog_content = "Então, tudo o que preciso fazer é esconder Peko no colo ou no bolso durante o julgamento.",
  ui_story_5028_50280602_19X5_dialog_content = "Ele pode sussurrar as respostas para mim!",
  ui_story_5028_50280602_19X6_dialog_content = "Assim, passarei no julgamento e surpreenderei meu estúpido mestre!",
  ui_story_5028_50280602_19X7_dialog_content = "Poderia ser realmente assim tão simples? Eu realmente não compro...",
  ui_story_5028_50280602_20_dialog_content = "Peko peko!",
  ui_story_5028_50280602_20X1_dialog_content = "Você pode por favor se esconder dentro do meu bolso...",
  ui_story_5028_50280602_20X2_dialog_content = "E me diga as respostas corretas em segredo?",
  ui_story_5028_50280602_20X3_dialog_content = "Peko-Peko!",
  ui_story_5028_50280602_20X4_dialog_content = "Heheh! Excelente!",
  ui_story_5028_50280602_21_dialog_content = "Vai ajudar e quer viajar conosco!",
  ui_story_5028_50280602_22_dialog_content = "Peko!",
  ui_story_5028_50280602_22X1_dialog_content = "Isto é perfeito! Agora podemos voltar para o meu mestre!",
  ui_story_5028_50280602_23_dialog_content = "Quero dizer, já temos praticamente um zoológico inteiro nos seguindo. Tenho certeza que mais um não vai doer.",
  ui_story_5028_50280602_24_dialog_content = "Heehee... Você é uma pessoa muito bondosa, PlayerName.",
  ui_story_5028_50280602_25_dialog_content = "O que? Você diz que é um coelho Peko sortudo porque foi resgatado das garras de um monstro assustador no passado?",
  ui_story_5028_50280602_26_dialog_content = "Isso é incrível! Tenho certeza que você será um amuleto da sorte para nossa jornada. Estamos contando com você!",
  ui_story_5028_50280602_27_dialog_content = "Peko!",
  ui_story_5028_50280602_28_dialog_content = "Revy! Carregar!",
  ui_story_5028_50280602_29_dialog_content = "<color=#e8d9bb>Bate, bate!</color>",
  ui_story_5028_50280602_30_dialog_content = "Queime tudo! Manticora!",
  ui_story_5028_50280602_31_dialog_content = "L-Vamos sair daqui! Esses caras são loucos!",
  ui_story_5028_50280602_32_dialog_content = "Ouça! Th-O <color=#FFB400>Chicote de Ferro</color> e nosso chefe <color=#FFB400>Gary</color> nunca vai te perdoar por isso!",
  ui_story_5028_50280602_33_dialog_content = "Eles fugiram.",
  ui_story_5028_50280602_34_dialog_content = "Viemos procurar um celestita, mas tudo o que encontramos foi uma gangue de caçadores violentos...",
  ui_story_5028_50280602_35_dialog_content = "O que eles estavam caçando aqui? Eu me pergunto se isso tem a ver com PlayerNamesituação?",
  ui_story_5028_50280602_36_dialog_content = "Tch... Devíamos ter agarrado e interrogado um deles enquanto tínhamos oportunidade.",
  ui_story_5028_50280602_37_dialog_content = "Yoohoo! Não é PlayerNameos amigos?",
  ui_story_5028_50280602_38_dialog_content = "Lola? O que faz aqui?",
  ui_story_5028_50280602_39_dialog_content = "Eu estava no meio da entrega de correspondência quando ouvi tiros, então vim investigar. Algum de vocês está ferido?",
  ui_story_5028_50280602_40_dialog_content = "Estávamos procurando o celestita quando um grupo de caçadores nos atacou.",
  ui_story_5028_50280602_41_dialog_content = "Sem vítimas. Os caçadores já se foram.",
  ui_story_5028_50280602_42_dialog_content = "Huh? Você disse \"o celestita\"? Isso significa PlayerName desapareceu?",
  ui_story_5028_50280602_43_dialog_content = "Espere, agora que você mencionou... Acho que vi sinais de um acampamento improvisado no meu caminho para cá! Talvez possamos encontrar algumas pistas lá?",
  ui_story_5028_50280602_44_dialog_content = "Deixe-me acompanhá-lo até lá primeiro, depois seguirei meu caminho.",
  ui_story_5028_50280602_45_dialog_content = "Por que parece que nos transformamos em algum tipo de grupo de turismo?",
  ui_story_5028_50280602_46_dialog_content = "Não é mais divertido assim? Pegando todos os tipos de vistas, chutando as bundas de todos os tipos de inimigos...",
  ui_story_5028_50280602_47_dialog_content = "Ah sim, é um feriado de verdade...",
  ui_story_5028_50280701_1_dialog_content = "Prova: Resista à mais doce tentação",
  ui_story_5028_50280701_2_dialog_content = "Nuvens do mais suave branco, e tenros ramos verdes ♪",
  ui_story_5028_50280701_3_dialog_content = "Fia e amigos marcham em direção a pontos turísticos invisíveis ♫",
  ui_story_5028_50280701_4_dialog_content = "Com um Caelestite a tiracolo, o mundo fica bem sereno ♪",
  ui_story_5028_50280701_5_dialog_content = "Ei, ei, ei ♫",
  ui_story_5028_50280701_6_dialog_content = "Você parece estar de bom humor.",
  ui_story_5028_50280701_7_dialog_content = "Heehe! Eu nunca pensei que estaríamos a apenas um passo de completar todos os testes tão rapidamente!",
  ui_story_5028_50280701_8_dialog_content = "E é tudo graças a você, PlayerName! Você, Kyllo e os outros são a razão de tudo ter corrido tão bem!",
  ui_story_5028_50280701_9_dialog_content = "Estou tão surpreso quanto.",
  ui_story_5028_50280701_10_dialog_content = "No começo, pensei que você não seria capaz de lidar com muitas dificuldades e que desistiria rapidamente para que eu ficasse livre das garras dessa missão esquecida por Deus.",
  ui_story_5028_50280701_11_dialog_content = "Aposto que você nunca imaginou que eu seria tão apaixonado por bestas maravilhosas, hein?",
  ui_story_5028_50280701_12_dialog_content = "Agora, se pudéssemos fazer algo sobre a maneira beligerante como você fala com as pessoas...",
  ui_story_5028_50280701_13_dialog_content = "Não não. Essa é minha peculiaridade especial, sem ela eu perderia tanto carisma!",
  ui_story_5028_50280701_14_dialog_content = "Faz sentido, suponho. Isso é parte do que faz você, bem... Você.",
  ui_story_5028_50280701_15_dialog_content = "Heehee!",
  ui_story_5028_50280701_16_dialog_content = "(Na verdade, eu sei que por baixo de seu exterior, Fia é uma pessoa gentil e gentil no coração.)",
  ui_story_5028_50280701_16X_dialog_content = "(Essas criaturinhas também estão cientes disso.)",
  ui_story_5028_50280701_17_dialog_content = "(Por mais simples que sejam, eles são inteligentes o suficiente para distinguir o real do falso... E a bondade da crueldade.)",
  ui_story_5028_50280701_18_dialog_content = "(O relacionamento próximo deles é prova suficiente de que Fia é uma criança doce e atenciosa.)",
  ui_story_5028_50280701_19_dialog_content = "... É? Por que você está zoneando?",
  ui_story_5028_50280701_20_dialog_content = "Você está com sede? Aqui, tome um pouco da minha água.",
  ui_story_5028_50280701_21_dialog_content = "Devemos estar a cerca de meio dia de caminhada da casa do meu mestre. Apenas espere um pouco mais.",
  ui_story_5028_50280701_22_dialog_content = "Oh! N-Não, obrigado, não estou com sede.",
  ui_story_5028_50280701_23_dialog_content = "Eu só estava pensando... O que você está planejando fazer quando seu aprendizado terminar?",
  ui_story_5028_50280701_24_dialog_content = "Planos futuros, hein? Acho que vou viajar pelo mundo e aprender tudo que puder sobre bestas maravilhosas. Depois disso, devo ser capaz de escrever um livro que até ofusque o trabalho do meu mestre!",
  ui_story_5028_50280701_25_dialog_content = "Isso definitivamente soa como você, tudo bem...",
  ui_story_5028_50280701_26_dialog_content = "Heehe! Quais são seus planos, PlayerName?",
  ui_story_5028_50280701_27_dialog_content = "Descobrir o que fazer com o Drakolion, suponho.",
  ui_story_5028_50280701_28_dialog_content = "Eu não quero ter que lidar com um enorme dragão voador pelo resto da minha vida, sabe?",
  ui_story_5028_50280701_29_dialog_content = "Relaxe, eu vou ajudá-lo a descobrir as coisas.",
  ui_story_5028_50280701_30_dialog_content = "O Drakolion provavelmente libertará o Colossus após o término da temporada de acasalamento.",
  ui_story_5028_50280701_31_dialog_content = "Eu certamente espero que sim.",
  ui_story_5028_50280701_32_dialog_content = "Soroz tem voado em círculos acima de nós esse tempo todo. Deve estar esgotado.",
  ui_story_5028_50280701_33_dialog_content = "Confie em mim, eu tenho a ciência e o know-how para apoiar minhas teorias!",
  ui_story_5028_50280701_34_dialog_content = "Ei!",
  ui_story_5028_50280701_35_dialog_content = "Certo, certo.",
  ui_story_5028_50280701_36_dialog_content = "... Huh? O que é isso?",
  ui_story_5028_50280701_37_dialog_content = "Isto se parece com um <color=#FFB400>estátua</color> De algum tipo.",
  ui_story_5028_50280701_38_dialog_content = "Acho que nunca vi uma estátua como esta antes.",
  ui_story_5028_50280701_39_dialog_content = "(Que estranho... Esta estátua me enche de uma poderosa sensação de conforto e familiaridade.)",
  ui_story_5028_50280701_40_dialog_content = "Er... Você acha que devemos ir oferecer uma oração, ou algo assim? Podemos pedir que ele os abençoe com um final suave para suas provações.",
  ui_story_5028_50280701_41_dialog_content = "Acho que não faria mal... Vamos!",
  ui_story_5028_50280701_42_dialog_content = "(À medida que nos aproximamos da estátua, essa sensação vertiginosa de conforto fica mais avassaladora.)",
  ui_story_5028_50280701_43_dialog_content = "Posso não saber seu nome, mas por favor... Conceda-me sua bênção, para que eu possa completar minhas provas e me tornar um verdadeiro extrozoólogo.",
  ui_story_5028_50280701_44_dialog_content = "E, por favor, abençoe o Drakolion com um amor recém-descoberto, para que Soroz possa finalmente retornar a PlayerNamelado de.",
  ui_story_5028_50280701_45_dialog_content = "E também abençoe Kyllo...",
  ui_story_5028_50280701_46_dialog_content = "Por favor...",
  ui_story_5028_50280701_47_dialog_content = "...",
  ui_story_5028_50280701_48_dialog_content = "Huh? Espere... Algo não parece certo.",
  ui_story_5028_50280701_49_dialog_content = "Parabéns, Fia!",
  ui_story_5028_50280701_50_dialog_content = "Parabéns por completar seus testes e se tornar o maior extrozoologista do mundo!",
  ui_story_5028_50280701_51_dialog_content = "Huh...? Mestre?! Eu sou o maior?",
  ui_story_5028_50280701_52_dialog_content = "Isso mesmo! Agora, por favor, sente-se.",
  ui_story_5028_50280701_53_dialog_content = "Minhas conquistas são pálidas em comparação com as suas, Fia. Quando se trata de animais maravilhosos, ninguém mais no mundo chega perto de saber tanto quanto você!",
  ui_story_5028_50280701_54_dialog_content = "A diferença entre nós é como o dia e a noite! Eu só espero que você encontre em seu coração para me aceitar como seu aprendiz, para que eu possa aprender tudo que puder com você!",
  ui_story_5028_50280701_55_dialog_content = "Heehee... Eu não sou tão bom assim, mas vou pensar nisso!",
  ui_story_5028_50280701_56_dialog_content = "Senhorita Fia.",
  ui_story_5028_50280701_57_dialog_content = "Huh? Quem é Você?",
  ui_story_5028_50280701_58_dialog_content = "Seus grandes feitos são conhecidos em todo o país, e eu sou um de seus fãs.",
  ui_story_5028_50280701_59_dialog_content = "Seus seguidores estão prontos para ajudá-lo e apoiá-lo em sua próxima aventura.",
  ui_story_5028_50280701_60_dialog_content = "Fia! Fia! Fia!",
  ui_story_5028_50280701_61_dialog_content = "Uau! Eles são todos meus fãs?",
  ui_story_5028_50280701_62_dialog_content = "Ele Ele! Suponho que, naturalmente, grandes conquistas atraem admiradores como ímãs.",
  ui_story_5028_50280701_63_dialog_content = "Espere... Acho que esqueci alguém importante.",
  ui_story_5028_50280701_64_dialog_content = "PlayerName! Onde está a PlayerName?",
  ui_story_5028_50280701_65_dialog_content = "<color=#e8d9bb>Enquanto isso...</color>",
  ui_story_5028_50280701_66_dialog_content = "Huh... Por que estou de volta ao Colossus? Onde estou?",
  ui_story_5028_50280701_67_dialog_content = "Tanto Lumamber! Isso é ótimo! Não estou sonhando, estou?",
  ui_story_5028_50280701_68_dialog_content = "Ahh! Qualquer que seja. Vou recrutar Aurorianos com o Lumamber imediatamente! Deixe-me começar com 100 puxadas!",
  ui_story_5028_50280701_69_dialog_content = "<color=#e8d9bb>Tum—!</color>",
  ui_story_5028_50280701_70_dialog_content = "<color=#e8d9bb>Tump, Tump—!</color>",
  ui_story_5028_50280701_71_dialog_content = "Hum? Alguém está lutando...?",
  ui_story_5028_50280701_72_dialog_content = "Acorde, seu idiota!",
  ui_story_5028_50280701_73_dialog_content = "Por que eu ouço alguém me xingando?",
  ui_story_5028_50280701_74_dialog_content = "J-Apenas mais dez puxadas!",
  ui_story_5028_50280701_75_dialog_content = "Graagh!",
  ui_story_5028_50280701_76_dialog_content = "Ahh!",
  ui_story_5028_50280701_77_dialog_content = "E- Eclipsitas?!",
  ui_story_5028_50280701_78_dialog_content = "O-o que está acontecendo?",
  ui_story_5028_50280701_79_dialog_content = "F-Fia? Onde estamos...? E de onde vieram esses Eclipses? E quem é você?!",
  ui_story_5028_50280701_80_dialog_content = "Pare de balbuciar e levante-se e lute!",
  ui_story_5028_50280701_81_dialog_content = "<size=45>Graaaah!</size>",
  ui_story_5028_50280701_82_dialog_content = "Fia!",
  ui_story_5028_50280701_83_dialog_content = "G-Entendi! PlayerName, vamos fazer isso! Kyllo!",
  ui_story_5028_50280702_1_dialog_content = "Não acredito que fomos atacados por Eclipsites.",
  ui_story_5028_50280702_2_dialog_content = "Mas como? A última coisa de que me lembro foi rezar para aquela estátua.",
  ui_story_5028_50280702_3_dialog_content = "Então, de repente... sonhei que me tornei o maior extrozoólogo do mundo.",
  ui_story_5028_50280702_4_dialog_content = "Sim, o mesmo aqui... Só que eu estava sonhando com pilhas brilhantes de roxo e dourado...",
  ui_story_5028_50280702_5_dialog_content = "E então, muitos aurorianos que eu já conheci vieram para o meu lado, e eu até me tornei um bom amigo de alguns que não estão mais conosco.",
  ui_story_5028_50280702_6_dialog_content = "Vocês dois realmente têm algumas fantasias interessantes...",
  ui_story_5028_50280702_7_dialog_content = "Você disse que estava rezando para uma estátua mais cedo, certo?",
  ui_story_5028_50280702_8_dialog_content = "Sim, por quê?",
  ui_story_5028_50280702_9_dialog_content = "Você orou para um ídolo estranho... E você nem sabia o que era?",
  ui_story_5028_50280702_10_dialog_content = "Se você está realmente alheio ao perigo, pode esquecer tudo sobre se tornar um extrozoólogo.",
  ui_story_5028_50280702_11_dialog_content = "Você ainda tem tempo para receber educação obrigatória em Illumina. Pelo menos você poderia conseguir um emprego em uma fábrica de armas em algum lugar depois da formatura.",
  ui_story_5028_50280702_12_dialog_content = "O que você disse?!?",
  ui_story_5028_50280702_13_dialog_content = "Quem diabos você pensa que é, falando assim comigo?!",
  ui_story_5028_50280702_14_dialog_content = "Não pense que pode dizer o que quiser só porque me ajudou uma vez!",
  ui_story_5028_50280702_15_dialog_content = "Pronto para atacar, Kyllo!",
  ui_story_5028_50280702_16_dialog_content = "...",
  ui_story_5028_50280702_17_dialog_content = "Kyllo?",
  ui_story_5028_50280702_18_dialog_content = "Essas bestas maravilhosas não estão conosco... Eu não consigo senti-las.",
  ui_story_5028_50280702_19_dialog_content = "Idiota.",
  ui_story_5028_50280702_20_dialog_content = "Não tenho motivos para lhe dizer quem sou.",
  ui_story_5028_50280702_21_dialog_content = "Mas eu posso dizer... Você quer se tornar um extrozoólogo apesar de ser tão ingênuo e descuidado.",
  ui_story_5028_50280702_22_dialog_content = "Onde está você, Kylo? Você não está brincando de esconde-esconde, certo?",
  ui_story_5028_50280702_23_dialog_content = "Se eu fosse você, já desistiria!",
  ui_story_5028_50280702_24_dialog_content = "Eles não são brinquedos para você brincar como quiser, ou animais de estimação para você mimar e mimar.",
  ui_story_5028_50280702_25_dialog_content = "Sem dedicação ou determinação, você nunca superará os obstáculos à frente... Você não chegará nem na metade do caminho antes de ser quebrado.",
  ui_story_5028_50280702_26_dialog_content = "Kylo... Kylo...",
  ui_story_5028_50280702_27_dialog_content = "Sua imaturidade também prejudicará todos os outros, incluindo seus chamados \"amigos\".",
  ui_story_5028_50280702_28_dialog_content = "V-você... Você sabe onde eles estão, não sabe?",
  ui_story_5028_50280702_29_dialog_content = "Por favor, estou implorando... Diga-me onde Kyllo e os outros estão!",
  ui_story_5028_50280702_30_dialog_content = "Você não ouviu nada do que acabei de dizer, idiota?",
  ui_story_5028_50280702_31_dialog_content = "Não há sinal de Kyllo e dos outros aqui... Ou de nossos suprimentos e equipamentos.",
  ui_story_5028_50280702_32_dialog_content = "Agora não é hora de se preocupar com essas coisas! Por favor... Diga-me onde eles estão!",
  ui_story_5028_50280702_33_dialog_content = "Meu Mestre confiou em mim com eles... Eles são meus amigos mais queridos, então se você sabe alguma coisa sobre onde eles podem estar, mesmo a menor pista... Eu preciso que você me diga!",
  ui_story_5028_50280702_34_dialog_content = "... Esse olhar estúpido em seu rosto é realmente embaraçoso.",
  ui_story_5028_50280702_35_dialog_content = "Estou indo embora. Você pode ficar aqui para o resto de sua vida, por tudo que me importa.",
  ui_story_5028_50280702_36_dialog_content = "Esses seus \"amigos\" problemáticos não vão esperar o dia todo enquanto você continua deprimido e sentindo pena de si mesmo.",
  ui_story_5028_50280702_37_dialog_content = "As crianças são mesmo uma dor...",
  ui_story_5028_50280702_38_dialog_content = "Fia!",
  ui_story_5028_50280702_39_dialog_content = "Sim!",
  ui_story_5028_50280702_40_dialog_content = "Nossas coisas podem ter sumido, mas o que mais importa agora é encontrar Kyllo e os outros!",
  ui_story_5028_50280702_41_dialog_content = "Espera, Fia!",
  ui_story_5028_50280702_42_dialog_content = "Parece que aquela garota deixou algo para trás...",
  ui_story_5028_50280702_43_dialog_content = "É uma bússola... E algum outro equipamento essencial para sobreviver no deserto.",
  ui_story_5028_50280702_44_dialog_content = "Não é meu próprio equipamento, mas parece bem novo... Aposto que pertence a ela. Ela deve ter deixado para nós de propósito.",
  ui_story_5028_50280702_45_dialog_content = "Ela disse um monte de coisas maldosas agora, mas ela pode realmente ser uma boa pessoa.",
  ui_story_5028_50280702_46_dialog_content = "Sim! Eu terei que agradecê-la apropriadamente na próxima vez que nos encontrarmos.",
  ui_story_5028_50280702_47_dialog_content = "Você sabe, ela parece um pouco familiar... Eu sinto que já a vi em algum lugar antes.",
  ui_story_5028_50280702_48_dialog_content = "Kyllo!",
  ui_story_5028_50280702_49_dialog_content = "Ei!!!",
  ui_story_5028_50280702_50_dialog_content = "Gloo...",
  ui_story_5028_50280702_51_dialog_content = "Hiya!",
  ui_story_5028_50280702_52_dialog_content = "Peko!",
  ui_story_5028_50280702_53_dialog_content = "Graças a Deus... Eles estavam esperando por nós na estátua o tempo todo!",
  ui_story_5028_50280702_54_dialog_content = "Mas o que nos fez adormecer em primeiro lugar? E como fomos parar ali?",
  ui_story_5028_50280702_55_dialog_content = "Ei! Olá!",
  ui_story_5028_50280702_56_dialog_content = "Parece que Kyllo está apontando para a estátua...",
  ui_story_5028_50280702_57_dialog_content = "Talvez haja algo de errado com isso?",
  ui_story_5028_50280702_58_dialog_content = "Ai...",
  ui_story_5028_50280702_59_dialog_content = "Ele... Ele se moveu agora mesmo! A estátua se moveu!",
  ui_story_5028_50280702_60_dialog_content = "Não... Essa coisa não é uma estátua!",
  ui_story_5028_50280702_61_dialog_content = "É um <color=#FFB400>Coruja Lutumi</color>, um tipo de besta maravilhosa! Eu nunca esperei encontrar um aqui, embora...",
  ui_story_5028_50280702_62_dialog_content = "Meu Mestre uma vez me disse que eles são tão raros que já podem ter sido extintos. Mesmo a Enciclopédia Exótica quase não tem informações sobre eles...",
  ui_story_5028_50280702_63_dialog_content = "Tudo o que sabemos é que ele finge ser uma estátua e tenta suas vítimas a adorar em transe.",
  ui_story_5028_50280702_63X_dialog_content = "Uma vez que eles adormecem, a Coruja Lutumi os rouba de qualquer valor que possa encontrar.",
  ui_story_5028_50280702_64_dialog_content = "Gaah... Graaah...",
  ui_story_5028_50280702_65_dialog_content = "Valores? Mas para que precisa deles?",
  ui_story_5028_50280702_66_dialog_content = "É mais provável que seja atraído por objetos brilhantes, como moedas, como muitos outros animais.",
  ui_story_5028_50280702_67_dialog_content = "Huuu!",
  ui_story_5028_50280702_68_dialog_content = "Oh não, está fugindo!",
  ui_story_5028_50280702_69_dialog_content = "Ei!",
  ui_story_5028_50280702_70_dialog_content = "Ótimo trabalho, Kylo! Não deixe escapar!",
  ui_story_5028_50280702_71_dialog_content = "Ah! Peguei vocês!",
  ui_story_5028_50280702_72_dialog_content = "Gaaah!",
  ui_story_5028_50280702_73_option_content = "Agite a coruja Lutumi",
  ui_story_5028_50280702_74_dialog_content = "Olhar, PlayerName! Algumas de nossas coisas caíram de seu corpo!",
  ui_story_5028_50280702_75_option_content = "Continue tremendo",
  ui_story_5028_50280702_76_dialog_content = "Cau ca!",
  ui_story_5028_50280702_77_dialog_content = "<color=#e8d9bb>Agite agite agite!</color>",
  ui_story_5028_50280702_78_dialog_content = "Gaaah!",
  ui_story_5028_50280702_79_dialog_content = "Mais coisas continuam caindo! Uma lata da Illumina, um pouco de Nightium... E olha, até uma pedra preciosa de Northland!",
  ui_story_5028_50280702_80_dialog_content = "Quem sabe quantas pessoas foram vítimas desse cara ao longo dos anos... Vamos deixar suas coisas aqui.",
  ui_story_5028_50280702_81_dialog_content = "Heehee... Tudo bem, seu pássaro travesso, é hora de fazer uma escolha.",
  ui_story_5028_50280702_82_dialog_content = "Gruau?",
  ui_story_5028_50280702_83_dialog_content = "Você quer que eu distribua sua punição aqui e agora?",
  ui_story_5028_50280702_84_dialog_content = "Cau ca cau!!",
  ui_story_5028_50280702_85_dialog_content = "Ou você vai desistir de seus caminhos de ladrão e se juntar a mim em minha jornada?",
  ui_story_5028_50280702_86_dialog_content = "Ai...",
  ui_story_5028_50280702_87_dialog_content = "Gaaah!",
  ui_story_5028_50280702_88_dialog_content = "Hehehe, pensei que sim! Agora vamos nos mexer!",
  ui_story_5028_50280702_89_dialog_content = "Estamos a caminho de ver meu Mestre. Tenho certeza de que ele ficará emocionado em vê-lo e ver até onde seu querido aprendiz chegou!",
  ui_story_5028_50280702_90_dialog_content = "Ufa...",
  ui_story_5028_50280702_91_dialog_content = "Ron...",
  ui_story_5028_50280702_92_dialog_content = "Zzz... Gram! Outro!!",
  ui_story_5028_50280702_93_dialog_content = "Nós caímos no sono?",
  ui_story_5028_50280702_94_dialog_content = "Acordar! Acordar!",
  ui_story_5028_50280702_95_dialog_content = "Temos caído nessa!",
  ui_story_5028_50280702_96_dialog_content = "Heh... Parece que todos nós fomos fodidos pelo truque daquela estátua estúpida.",
  ui_story_5028_50280702_97_dialog_content = "Eu continuei dizendo que não deveríamos ter orado para isso, mas nãooo...",
  ui_story_5028_50280702_98_dialog_content = "Romance é um absurdo. Você está começando a delirar com a velhice ou algo assim?",
  ui_story_5028_50280702_99_dialog_content = "Basta olhar para isto... Todas as nossas coisas se foram.",
  ui_story_5028_50280702_100_dialog_content = "Do que você está falando?! Eu só rezei para que um dia eu te vencesse...",
  ui_story_5028_50280702_101_dialog_content = "Se você tem tempo para zombar de mim, por que não o usa para encontrar nosso equipamento perdido?",
  ui_story_5028_50280702_102_dialog_content = "Onde está aquela estátua que precisa de um chute no traseiro?",
  ui_story_5028_50280702_103_dialog_content = "Foi-se?",
  ui_story_5028_50280702_104_dialog_content = "Espere, eu vejo algo ali.",
  ui_story_5028_50280702_105_dialog_content = "Ei, Smokey... Esta não é a sua palheta de metal?",
  ui_story_5028_50280702_106_dialog_content = "É isso. Er, quero dizer... Na verdade, é um abridor de garrafas!",
  ui_story_5028_50280702_107_dialog_content = "Todo o resto está aqui?",
  ui_story_5028_50280702_108_dialog_content = "As coisas estão aqui. Estátua não.",
  ui_story_5028_50280702_109_dialog_content = "Também... sinto cheiro de celestite.",
  ui_story_5028_50280801_1_dialog_content = "Oh, maaaasterrrr! Adivinhe quem voltou?",
  ui_story_5028_50280801_2_dialog_content = "Demorou, mas finalmente completei seus testes malucos!",
  ui_story_5028_50280801_X2_dialog_content = "Mas apesar do que você me disse, Kyllo nunca \"evoluiu\". O que há com isso?",
  ui_story_5028_50280801_3_dialog_content = "Desculpe-nos...",
  ui_story_5028_50280801_4_dialog_content = "(Este lugar... é terrivelmente desarrumado!)",
  ui_story_5028_50280801_5_dialog_content = "(Todos esses livros espalhados por todo o lugar... O Mestre dela não sabe pegar depois de si mesmo?!)",
  ui_story_5028_50280801_6_dialog_content = "Então, o que você diz, Mestre? Meu aprendizado está finalmente completo, ou...",
  ui_story_5028_50280801_7_dialog_content = "O que aconteceu aqui? Que bagunça!",
  ui_story_5028_50280801_8_dialog_content = "Oh... Quer dizer que nem sempre é assim?",
  ui_story_5028_50280801_9_dialog_content = "Não... quer dizer, as bagunças dele têm uma certa ordem.",
  ui_story_5028_50280801_10_dialog_content = "O que pode parecer uma pilha aleatória de livros é na verdade uma seleção cuidadosamente organizada de informações valiosas.",
  ui_story_5028_50280801_11_dialog_content = "Ele classifica todos os livros em pilhas com base em suas categorias.",
  ui_story_5028_50280801_12_dialog_content = "Ele também tende a deixar os livros que não terminou de ler bem abertos no topo das pilhas. Por isso parecem desorganizados.",
  ui_story_5028_50280801_13_dialog_content = "Mas olhe! A categoria desta pilha é Entomologia, mas os dois livros mais importantes são sobre criaturas aquáticas.",
  ui_story_5028_50280801_14_dialog_content = "Meu mestre calvo de meia-idade pode não parecer muito confiável, mas ele nunca perderia seus livros assim!",
  ui_story_5028_50280801_15_dialog_content = "Então isso significa... mais alguém estava aqui, mexendo nos livros de Vic?",
  ui_story_5028_50280801_16_dialog_content = "É bem possível... Mas a prioridade é encontrá-lo logo!",
  ui_story_5028_50280801_17_dialog_content = "Mestre! Para onde você fugiu dessa vez?! Venha para fora!",
  ui_story_5028_50280801_18_dialog_content = "<size=45>Olá?!</size>",
  ui_story_5028_50280801_19_option_content = "Vic!",
  ui_story_5028_50280801_20_dialog_content = "...",
  ui_story_5028_50280801_21_dialog_content = "Acho que ele não está aqui...",
  ui_story_5028_50280801_22_dialog_content = "As gavetas foram puxadas e sua cadeira está fora do lugar... E as portas do armário, que ele explicitamente me proíbe de tocar... estão abertas.",
  ui_story_5028_50280801_23_dialog_content = "Parece que Vic saiu com pressa.",
  ui_story_5028_50280801_24_dialog_content = "E a sala está em total desordem. Não me diga...",
  ui_story_5028_50280801_25_dialog_content = "Receio que esteja certo sobre este. Vic pode ter sido sequestrado...",
  ui_story_5028_50280801_26_dialog_content = "Ele deve ter mentido para mim todo esse tempo, então ele fugiu em vez de esperar que eu voltasse!!!",
  ui_story_5028_50280801_27_dialog_content = "Hã?",
  ui_story_5028_50280801_28_dialog_content = "Não pode haver outra explicação!",
  ui_story_5028_50280801_29_dialog_content = "D-Você não acha que devemos pelo menos considerar a possibilidade de ele ter sido sequestrado?",
  ui_story_5028_50280801_30_dialog_content = "O quê?!",
  ui_story_5028_50280801_31_dialog_content = "Huh? Er... O-Claro! Eu já pensei nisso!",
  ui_story_5028_50280801_32_dialog_content = "É só que... Eu realmente não consigo pensar em alguém que iria querer sequestrar alguém como meu Mestre, sabe?",
  ui_story_5028_50280801_33_dialog_content = "Indiferente como ele é, ele bebe como um peixe, e ele não tem nem dois Nightium para esfregar na carteira...",
  ui_story_5028_50280801_34_dialog_content = "Uh... Você realmente deveria estar falando sobre ele assim? Ele é seu mestre, afinal...",
  ui_story_5028_50280801_35_dialog_content = "De qualquer forma, o que você acha que devemos fazer agora?",
  ui_story_5028_50280801_36_dialog_content = "Bem, se não encontrarmos meu mestre, nunca poderei me formar em um extrozoologista de pleno direito.",
  ui_story_5028_50280801_37_dialog_content = "Então acho que devemos começar procurando por ele.",
  ui_story_5028_50280801_38_dialog_content = "Então vamos procurar na área qualquer pista que possa nos apontar na direção de Vic.",
  ui_story_5028_50280801_39_dialog_content = "Hmph. O Mestre deve gostar muito de deixar outras pessoas preocupadas.",
  ui_story_5028_50280801_40_dialog_content = "Tudo bem, então! Hora de caçar pistas!",
  ui_story_5028_50280801_41_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5028_50280801_42_dialog_content = "<color=#e8d9bb>Oba! Esmagar!</color>",
  ui_story_5028_50280801_43_dialog_content = "Para para para!",
  ui_story_5028_50280801_44_dialog_content = "Você chama isso de \"caça às pistas\"?! Você está praticamente demolindo a cena do crime!",
  ui_story_5028_50280801_45_dialog_content = "Eu acabei de derrubar algumas coisas, só isso! Eu juro que estou procurando o máximo que posso!",
  ui_story_5028_50280801_46_dialog_content = "Nesse ritmo, seu \"olhar\" vai derrubar a casa em nossas cabeças...",
  ui_story_5028_50280801_47_dialog_content = "Eu não sou tão imprudente!",
  ui_story_5028_50280801_48_dialog_content = "Hmm... Deixe-me cuidar disso.",
  ui_story_5028_50280801_49_dialog_content = "Caso contrário, a casa, assim como as pistas, seriam todas destruídas.",
  ui_story_5028_50280801_50_dialog_content = "Ora, você...!",
  ui_story_5028_50280801_51_dialog_content = "E teríamos um dia bastante ocupado no final.",
  ui_story_5028_50280801_52_dialog_content = "Agora, por onde devo começar minha pesquisa?",
  ui_story_5028_50280801_53_option_content = "Inspecione a mesa",
  ui_story_5028_50280801_54_dialog_content = "Todas as suas gavetas foram retiradas. Parece que alguém vasculhou apressadamente seu conteúdo...",
  ui_story_5028_50280801_55_dialog_content = "Meu Mestre geralmente joga coisas nas gavetas, mas as gavetas têm categorias, assim como seus livros.",
  ui_story_5028_50280801_56_dialog_content = "O que esta gaveta vazia deveria conter?",
  ui_story_5028_50280801_57_dialog_content = "Deixe-me pensar... Ele parecia manter algumas anotações sobre bestas maravilhosas lá.",
  ui_story_5028_50280801_58_dialog_content = "Quando meu Mestre me confiou Kyllo pela primeira vez, ele pegou essas notas e as examinou antes de tomar sua decisão final.",
  ui_story_5028_50280801_59_dialog_content = "Só que não vejo as anotações dele em lugar nenhum...",
  ui_story_5028_50280801_60_dialog_content = "Espere, há um pedaço de papel debaixo da mesa!",
  ui_story_5028_50280801_61_dialog_content = "Mostre-me!",
  ui_story_5028_50280801_62_dialog_content = "É um desenho de um círculo com um \"X\" dentro dele...",
  ui_story_5028_50280801_63_dialog_content = "A caligrafia parece apressada, e a tinta ainda está um pouco fresca... Isso não pode ter sido escrito há tanto tempo!",
  ui_story_5028_50280801_64_dialog_content = "Isso poderia ser uma mensagem secreta de algum tipo?",
  ui_story_5028_50280801_65_dialog_content = "Não sei...",
  ui_story_5028_50280801_66_option_content = "Inspecione as estantes",
  ui_story_5028_50280801_67_dialog_content = "Os livros nesta estante estão todos bem organizados.",
  ui_story_5028_50280801_68_dialog_content = "Mas isso é porque meu Mestre não gosta muito de ler esses livros... E como ele não é do tipo que limpa regularmente, todos esses livros têm uma espessa camada de poeira sobre eles.",
  ui_story_5028_50280801_69_dialog_content = "Olha, aquele livro na prateleira de cima não pega poeira! Como se tivesse sido lido regularmente...",
  ui_story_5028_50280801_70_dialog_content = "Devemos dar uma olhada mais de perto!",
  ui_story_5028_50280801_71_dialog_content = "Grr... Eu não consigo chegar lá!",
  ui_story_5028_50280801_72_dialog_content = "Pfft!",
  ui_story_5028_50280801_73_dialog_content = "Não é engraçado! Pare de rir!",
  ui_story_5028_50280801_74_dialog_content = "Se você é tão alto, PlayerName, apenas pegue isso para mim.",
  ui_story_5028_50280801_75_dialog_content = "Ei! Aqui está.",
  ui_story_5028_50280801_76_dialog_content = "Hum? Há uma foto antiga escondida entre as páginas deste livro.",
  ui_story_5028_50280801_77_dialog_content = "Parece Master Vic, mas a outra metade da foto foi arrancada...",
  ui_story_5028_50280801_78_dialog_content = "Deve ser muito importante para o meu Mestre se ele o guardou todo esse tempo.",
  ui_story_5028_50280801_79_dialog_content = "A outra pessoa na foto... Quem poderia ser?",
  ui_story_5028_50280801_80_dialog_content = "Estamos procurando há tanto tempo que parece que minhas pernas estão prestes a cair, mas quase não fizemos nenhum progresso...",
  ui_story_5028_50280801_81_dialog_content = "O que vamos fazer agora?",
  ui_story_5028_50280801_82_dialog_content = "...",
  ui_story_5028_50280801_83_dialog_content = "Er, Fia...?",
  ui_story_5028_50280801_84_dialog_content = "De repente você sente um calafrio descendo pelas costas? Porque eu faço...",
  ui_story_5028_50280801_85_dialog_content = "Eu... eu também sinto...",
  ui_story_5028_50280801_86_dialog_content = "Mas por que...",
  ui_story_5028_50280801_87_dialog_content = "Ahhh!",
  ui_story_5028_50280801_88_dialog_content = "É... É ela de novo!!",
  ui_story_5028_50280801_89_dialog_content = "Uma coisa é se você veio roubar o lugar, já que não há realmente nada de valor aqui...",
  ui_story_5028_50280801_90_dialog_content = "Mas destruir a casa assim... é absolutamente imperdoável.",
  ui_story_5028_50280801_91_dialog_content = "Vai ser um processo trabalhoso arrumar todos esses livros...",
  ui_story_5028_50280801_92_dialog_content = "Com as portas dos armários abertas, essas coleções dentro acumulavam muita poeira. Levará dias para limpar essa bagunça...",
  ui_story_5028_50280801_93_dialog_content = "O que é pior, o mapa de bestas maravilhosas e aqueles manuscritos preciosos, ambos os quais me levaram anos de pesquisa meticulosa para compilar... estão longe de serem vistos!",
  ui_story_5028_50280801_94_dialog_content = "Y-Sim! Eu não poderia concordar mais!",
  ui_story_5028_50280801_95_dialog_content = "M-Mas não se preocupe, senhorita!",
  ui_story_5028_50280801_96_dialog_content = "Faremos tudo o que pudermos para...",
  ui_story_5028_50280801_97_dialog_content = "Não.",
  ui_story_5028_50280801_98_dialog_content = "Para me compensar? Por favor... Você nunca poderia esperar pagar pelos meus arquivos inestimáveis!",
  ui_story_5028_50280801_99_dialog_content = "Espere o que?! Mas nós não os roubamos!!",
  ui_story_5028_50280801_100_dialog_content = "Ele está falando a verdade! Viemos procurar o Mestre Vic, mas ele sumiu... E a casa estava assim quando chegamos aqui!",
  ui_story_5028_50280801_101_dialog_content = "Uh, exceto por algumas coisas que encontrei enquanto procurava por pistas: uma cadeira, dois vasos, três copos de vidro...",
  ui_story_5028_50280801_102_dialog_content = "Espere por favor, Fia!",
  ui_story_5028_50280801_103_dialog_content = "Salve isso. Eu peguei vocês ladrões em flagrante.",
  ui_story_5028_50280801_104_dialog_content = "Inicialmente, pensei que fossem apenas dois entusiastas normais de bestas maravilhosas... mas agora sei que não passam de criminosos de baixa vida.",
  ui_story_5028_50280801_105_dialog_content = "Apenas se declare culpado e pague o que deve.",
  ui_story_5028_50280801_110_dialog_content = "Você está mesmo ouvindo, seu bandido? Já dissemos que não fomos nós!",
  ui_story_5028_50280801_112_dialog_content = "Caramba?!",
  ui_story_5028_50280801_113_dialog_content = "O-o que diabos?! Você não pode simplesmente começar a atacar assim aqui!!",
  ui_story_5028_50280801_114_dialog_content = "Eu também não quero brigar com você. Afinal, apenas mover meus dedos ou meus tentáculos é exaustivo o suficiente.",
  ui_story_5028_50280801_X114_dialog_content = "Então eu vou te dar uma última chance de se explicar.",
  ui_story_5028_50280801_115_dialog_content = "Não fomos nós, eu juro...",
  ui_story_5028_50280801_116_dialog_content = "Ahhh!",
  ui_story_5028_50280801_117_dialog_content = "<color=#e8d9bb>Cabuum!</color>",
  ui_story_5028_50280801_118_dialog_content = "Th-Há um buraco enorme onde aquele tentáculo atingiu agora...",
  ui_story_5028_50280801_119_dialog_content = "Eu teria sido um caso perdido se isso me atingisse!",
  ui_story_5028_50280801_120_dialog_content = "Isso mesmo. Você estaria em um mundo de dor.",
  ui_story_5028_50280801_121_dialog_content = "Pare por favor! Nós realmente não viemos aqui para roubar nada!",
  ui_story_5028_50280801_122_dialog_content = "Estávamos apenas procurando por pistas! Estamos tentando rastrear Vic!",
  ui_story_5028_50280801_123_dialog_content = "Mestre... desapareceu? Mas se vocês dois não são os culpados, então quem deveria ser?",
  ui_story_5028_50280801_124_dialog_content = "Também não sabemos...",
  ui_story_5028_50280801_125_dialog_content = "Mas conseguimos encontrar algumas pistas!",
  ui_story_5028_50280801_126_dialog_content = "Pistas, hein? Encontrar pistas pode ser uma dor demais, e o raciocínio pode ser uma dor ainda maior. Você também pode cuspir.",
  ui_story_5028_50280801_127_dialog_content = "Então me diga, o que vocês dois encontraram?",
  ui_story_5028_50280801_128_dialog_content = "O Mestre deixou isso para trás, um desenho de um círculo com um \"X\" dentro dele. Achamos que foi desenhado recentemente!",
  ui_story_5028_50280801_129_dialog_content = "Sim. Também encontramos esta fotografia dentro de um livro.",
  ui_story_5028_50280801_130_dialog_content = "Espere... Vic é o Mestre a quem você tem se referido todo esse tempo?",
  ui_story_5028_50280801_131_dialog_content = "Nossa, é verdade!",
  ui_story_5028_50280801_132_dialog_content = "Sim, eu estudei com ele por um tempo. Agora que terminei com suas provações, meu aprendizado está prestes a ser concluído!",
  ui_story_5028_50280801_133_dialog_content = "Kyllo aqui está a minha prova: foi-me confiada pelo meu Mestre!",
  ui_story_5028_50280801_134_dialog_content = "É... Kyllo?",
  ui_story_5028_50280801_135_dialog_content = "Lo? Lo lo ...",
  ui_story_5028_50280801_136_dialog_content = "Aí está você! O que você está fazendo, dormindo entre esses livros? Venha para fora!",
  ui_story_5028_50280801_137_dialog_content = "Esse é exatamente o Kyllo de Vic. E também não te rejeitou...",
  ui_story_5028_50280801_138_dialog_content = "Bem, já que está disposto a confiar em você, não tenho muitos motivos para continuar duvidando de você.",
  ui_story_5028_50280801_139_dialog_content = "Ah, então AGORA você acredita em mim!",
  ui_story_5028_50280801_140_dialog_content = "Infelizmente... Parece que ele se meteu em alguns problemas enquanto eu estava procurando por bestas maravilhosas.",
  ui_story_5028_50280801_141_dialog_content = "Babysitting é definitivamente a parte mais difícil.",
  ui_story_5028_50280801_142_dialog_content = "Eu não sou uma criança!",
  ui_story_5028_50280801_143_dialog_content = "Quem exatamente você é? E como você sabe tanto sobre meu Mestre?",
  ui_story_5028_50280801_144_dialog_content = "Quem sou eu? Ah, quem sou eu mesmo...",
  ui_story_5028_50280801_145_dialog_content = "Eu sei que as relações entre as pessoas podem ser um verdadeiro aborrecimento para lembrar às vezes...",
  ui_story_5028_50280801_146_dialog_content = "Simplificando, se Vic é a pessoa que você chama de Mestre, então isso mais ou menos me torna seu superior.",
  ui_story_5028_50280801_147_dialog_content = "Meu nome é <color=#FFB400>Shira</color>.",
  ui_story_5028_50280801_148_dialog_content = "Shira",
  ui_story_5028_50280801_X148_dialog_content = "21 anos de idade",
  ui_story_5028_50280801_X149_dialog_content = "A misteriosa garota polvo",
  ui_story_5028_50280801_149_dialog_content = "M-Meu sênior?! Mas por que meu Mestre nunca me contou sobre você?!",
  ui_story_5028_50280801_150_dialog_content = "Afinal, ele nunca explica nada perfeitamente claro.",
  ui_story_5028_50280801_151_dialog_content = "Às vezes, até eu tenho dificuldade em descobrir se ele mente para mim mais do que me ensina.",
  ui_story_5028_50280801_152_dialog_content = "Lidar com ele pode ser totalmente irritante às vezes.",
  ui_story_5028_50280801_153_dialog_content = "Obrigado por todo o trabalho duro.",
  ui_story_5028_50280801_154_dialog_content = "Mas está tudo bem... Já estou acostumado com isso.",
  ui_story_5028_50280801_155_dialog_content = "Bem, vamos voltar ao assunto em questão. Ainda não tenho certeza sobre o significado desta foto.",
  ui_story_5028_50280801_156_dialog_content = "Vic pode ter mencionado algo sobre isso antes, mas isso escapou da minha mente.",
  ui_story_5028_50280801_157_dialog_content = "Ei... Você não deveria ter uma memória muito boa ou algo assim?",
  ui_story_5028_50280801_158_dialog_content = "De que outra forma você poderia se lembrar de tanto conhecimento detalhado sobre tantos animais maravilhosos?",
  ui_story_5028_50280801_159_dialog_content = "Muita dor para lembrar de algo irrelevante para bestas maravilhosas.",
  ui_story_5028_50280801_160_dialog_content = "Ei!",
  ui_story_5028_50280801_161_dialog_content = "No entanto... Eu sei exatamente o que este símbolo significa.",
  ui_story_5028_50280801_162_dialog_content = "É uma mensagem escondida deixada por Vic. Significa que ele foi sequestrado.",
  ui_story_5028_50280801_163_dialog_content = "Há muitos bandidos na área, então ele costumava deixar símbolos como este para que eu pudesse encontrá-lo e resgatá-lo.",
  ui_story_5028_50280801_164_dialog_content = "Então ele realmente foi sequestrado!",
  ui_story_5028_50280801_165_dialog_content = "Droga... Eles devem enviar uma nota de resgate a qualquer minuto, certo?",
  ui_story_5028_50280801_166_dialog_content = "\"Se você quiser ver seu Mestre novamente, traga dez milhões de Nightium para o seguinte local...\" Eu nunca poderia pagar...",
  ui_story_5028_50280801_167_dialog_content = "O que é pior, se ele chutasse o balde... Eu nunca poderia me formar em extrozoologista!",
  ui_story_5028_50280801_168_dialog_content = "Eu não acho que suas aspirações de carreira sejam nosso maior problema agora!!!",
  ui_story_5028_50280801_169_dialog_content = "Ainda assim... não consigo entender.",
  ui_story_5028_50280801_170_dialog_content = "Vic é roubado com tanta frequência, mas está falido de brincadeira.",
  ui_story_5028_50280801_171_dialog_content = "E geralmente, esses ladrões apenas causam um tumulto antes de sair sem nada. Na pior das hipóteses, eles podem atacá-lo por causa de seus problemas.",
  ui_story_5028_50280801_172_dialog_content = "Mas desta vez, parece que alguém o invadiu e o sequestrou...",
  ui_story_5028_50280801_173_dialog_content = "Por que alguém iria para todo esse problema?",
  ui_story_5028_50280801_174_dialog_content = "Afinal, Vic não podia oferecer nada de valor além de consumir comida e água.",
  ui_story_5028_50280801_175_dialog_content = "Neste ponto, não sei se me sinto mal por seu Mestre ou seus sequestradores...",
  ui_story_5028_50280801_176_dialog_content = "Hmph... Eu sugiro que você se preocupe mais consigo mesmo em um momento como este.",
  ui_story_5028_50280801_177_dialog_content = "E-Se você diz...",
  ui_story_5028_50280801_178_dialog_content = "Quanto a quem poderia ter feito isso, não me diga...",
  ui_story_5028_50280801_179_dialog_content = "Essa não...",
  ui_story_5028_50280801_180_dialog_content = "Ei, espere!",
  ui_story_5028_50280801_181_dialog_content = "Quem você acha que sequestrou meu Mestre?! Ei!!!",
  ui_story_5028_50280801_182_dialog_content = "Incrível... Ela simplesmente se retirou de nossa vista em um instante.",
  ui_story_5028_50280801_183_dialog_content = "Meu mestre está desaparecido, e meu superior fugiu sem dizer mais nada.",
  ui_story_5028_50280801_184_dialog_content = "Eca! Não entendo porque os dois tem que ser assim!!",
  ui_story_5028_50280801_185_dialog_content = "L-Vamos tentar conversar com Shira, ok?",
  ui_story_5028_50280801_186_dialog_content = "Parece que ela fugiu na direção da cidade. Vamos nessa direção primeiro.",
  ui_story_5028_50280801_187_dialog_content = "Tem muita gente na rua. Alguém deve ter visto para onde ela foi.",
  ui_story_5028_50280801_188_dialog_content = "Sim!",
  ui_story_5028_50280901_1_dialog_content = "Perdoe-me, mas por acaso você viu uma garota de cabelos brancos com tentáculos passar por aqui?",
  ui_story_5028_50280901_4_dialog_content = "Bem, se não é a pequena Fia!",
  ui_story_5028_50280901_5_dialog_content = "E quem é esse? Um amigo?",
  ui_story_5028_50280901_6_dialog_content = "Huh? Não é aquele cara que vendia jornais?",
  ui_story_5028_50280901_7_dialog_content = "Isso aqui, é PlayerName, meu parceiro.",
  ui_story_5028_50280901_8_dialog_content = "Estamos no meio de uma busca agora. Você tem alguma pista?",
  ui_story_5028_50280901_12_dialog_content = "Não sei nada sobre uma jovem, mas acho que seu mestre Vic precisa de ajuda!",
  ui_story_5028_50280901_13_dialog_content = "S-Sim, como extrozoologista profissional, estou bem ciente de seu desaparecimento... Estamos procurando por ele agora.",
  ui_story_5028_50280901_14_dialog_content = "Eu sabia.",
  ui_story_5028_50280901_15_dialog_content = "Eu vi que ele foi levado por um homem alto não muito tempo atrás.",
  ui_story_5028_50280901_16_dialog_content = "Eu contei ao pessoal do Shadowlord sobre o caso. Eu me pergunto se eles fizeram algo sobre isso...",
  ui_story_5028_50280901_17_dialog_content = "Um homem alto, hein? Você se lembra de como ele era?",
  ui_story_5028_50280901_18_dialog_content = "Desculpe, mas ele estava de costas para mim. Tudo o que eu podia ver era ele carregando seu Mestre para fora da cidade nas costas.",
  ui_story_5028_50280901_19_dialog_content = "Mas eu me lembro claramente de sua roupa. Muito parecido com os usados pelos bandidos nas proximidades.",
  ui_story_5028_50280901_20_dialog_content = "Bandidos?",
  ui_story_5028_50280901_21_dialog_content = "Também estamos plenamente conscientes desta situação. Você pode deixar o resto comigo agora.",
  ui_story_5028_50280901_22_dialog_content = "Não seja rude, Fia.",
  ui_story_5028_50280901_23_dialog_content = "Se o pior acontecer, pagar o Shadowlord por sua ajuda é sempre uma opção...",
  ui_story_5028_50280901_24_dialog_content = "Não se preocupe, somos mais do que capazes de lidar com isso sozinhos.",
  ui_story_5028_50280901_25_dialog_content = "Muito bem, então. Boa sorte!",
  ui_story_5028_50280901_26_dialog_content = "Ai... eu adoraria pedir ajuda...",
  ui_story_5028_50280901_27_dialog_content = "Mas meu Mestre não tem como pagar...",
  ui_story_5028_50280901_28_dialog_content = "Podemos realmente esperar enfrentar esses bandidos com apenas nós dois?",
  ui_story_5028_50280901_29_dialog_content = "O que você quer dizer com \"só nós dois\"?",
  ui_story_5028_50280901_30_dialog_content = "Não se esqueça, eu sou um extrozoologista profissional! Eu tenho toneladas de bestas maravilhosas que podem nos dar sua força!",
  ui_story_5028_50280901_31_dialog_content = "Peko peko!",
  ui_story_5028_50280901_32_dialog_content = "Gloo...",
  ui_story_5028_50280901_33_dialog_content = "Hum-hum! Vocês também querem resgatar meu Mestre, certo?",
  ui_story_5028_50280901_34_dialog_content = "Com sua ajuda, eu sei que podemos fazer isso!",
  ui_story_5028_50280901_35_dialog_content = "Olá!",
  ui_story_5028_50280901_36_dialog_content = "Não consigo entender o que você está dizendo agora, mas você tem minha palavra: farei o que for preciso para resgatar meu Mestre!",
  ui_story_5028_50280901_37_dialog_content = "Um misterioso bandido obcecado por conhecimento sequestrou Vic apesar de ser pobre...",
  ui_story_5028_50280901_38_dialog_content = "Eu me pergunto como vamos rastreá-los?",
  ui_story_5028_50280901_39_dialog_content = "Será que realmente teremos que contar com a ajuda do Shadowlord?",
  ui_story_5028_50280901_40_dialog_content = "Deve haver uma maneira melhor...",
  ui_story_5028_50280901_41_dialog_content = "Deixa eu pensar...",
  ui_story_5028_50280901_42_dialog_content = "Além de seus alvos, suponho que os bandidos deveriam ficar de olho em outras gangues.",
  ui_story_5028_50280901_43_dialog_content = "Afinal, eles só se preocupam com seu território, não com a lei.",
  ui_story_5028_50280901_44_dialog_content = "Se conseguirmos colocar as mãos em um bandido, talvez consigamos alguma informação sobre o paradeiro do meu Mestre!",
  ui_story_5028_50280901_45_dialog_content = "Soa como um plano! Só... Onde vamos encontrar um bandido?",
  ui_story_5028_50280901_46_dialog_content = "Onde encontrar um bandido, você diz?",
  ui_story_5028_50280901_47_dialog_content = "Isso é fácil!",
  ui_story_5028_50280901_48_dialog_content = "Você e eu só temos que fingir que somos um casal de viajantes ricos e crédulos, PlayerName!",
  ui_story_5028_50280901_49_dialog_content = "Vamos começar com...",
  ui_story_5028_50280901_50_dialog_content = "Espere... V-você não pode estar querendo dizer...?",
  ui_story_5028_50280901_51_dialog_content = "Nã-uh! De jeito nenhum! Sem chance!",
  ui_story_5028_50280901_52_dialog_content = "Você tem alguma ideia do quanto eu trabalhei para juntar tanto Nightium desde que deixei o mundo subterrâneo?!",
  ui_story_5028_50280901_53_dialog_content = "M-Mas PlayerName... Você não quer me ajudar a resgatar meu Mestre?",
  ui_story_5028_50280901_54_dialog_content = "...",
  ui_story_5028_50280901_55_dialog_content = "Você aguenta me ver nunca me tornar um extrozoólogo?",
  ui_story_5028_50280901_56_dialog_content = "...",
  ui_story_5028_50280901_57_dialog_content = "Boo-hoo... Tudo bem... Vou ter que encontrar outra maneira...",
  ui_story_5028_50280901_58_dialog_content = "Eu salvarei meu Mestre, sozinho! Mesmo se eu for capturado e torturado por esses bandidos, eu ainda não vou pedir sua ajuda novamente, PlayerName!",
  ui_story_5028_50280901_X58_dialog_content = "Booooom!!!",
  ui_story_5028_50280901_X59_dialog_content = "...",
  ui_story_5028_50280901_X60_dialog_content = "Por que eeeee!!!",
  ui_story_5028_50280901_59_dialog_content = "<color=#e8d9bb>Algum tempo depois...</color>",
  ui_story_5028_50280901_60_dialog_content = "Maçãs doces! Taiyaki! Especialidades da Ilha das Nuvens!",
  ui_story_5028_50280901_61_dialog_content = "Você aí! Sentindo um pouco de fome?",
  ui_story_5028_50280901_62_dialog_content = "Como você sabia? Levaremos dez de tudo! Seu deleite!",
  ui_story_5028_50280901_63_dialog_content = "Y-Sim! Meu mimo...!",
  ui_story_5028_50280901_64_dialog_content = "Eu sabia que vocês eram frios caras! Um momento, por favor!",
  ui_story_5028_50280901_65_dialog_content = "Uau... Olhe para todos esses petiscos saborosos!",
  ui_story_5028_50280901_66_dialog_content = "(Por que eu concordei em fazer parte desse plano estúpido?!)",
  ui_story_5028_50280901_67_dialog_content = "(Vice não vai deixar isso passar quando ela descobrir que gastei tanto dinheiro...)",
  ui_story_5028_50280901_68_dialog_content = "Om-nom-nom... Delicioso!",
  ui_story_5028_50280901_69_dialog_content = "Eu vou ter outro!",
  ui_story_5028_50280901_70_dialog_content = "Imediatamente, senhorita!",
  ui_story_5028_50280901_71_dialog_content = "(Por favor... Isso foi o valor de dez dias de pagamento agora...)",
  ui_story_5028_50280901_72_dialog_content = "...",
  ui_story_5028_50280901_73_dialog_content = "(Espere... Aquela pessoa ali está olhando para nós?)",
  ui_story_5028_50280901_74_dialog_content = "Estamos sendo observados. Acho que finalmente atraímos a atenção de um bandido.",
  ui_story_5028_50280901_75_dialog_content = "No momento ideal. Estou quase terminando de lanchar, também! Hora do próximo passo.",
  ui_story_5028_50280901_76_dialog_content = "*Tosse*",
  ui_story_5028_50280901_77_dialog_content = "Ah, aqueles eram realmente um deleite! Vamos fazer algumas compras agora?",
  ui_story_5028_50280901_78_dialog_content = "Naturalmente, você vai me comprar o que meu coraçãozinho desejar, certo?",
  ui_story_5028_50280901_79_dialog_content = "E-Este é realmente o próximo passo?!",
  ui_story_5028_50280901_80_dialog_content = "<size=45>A-HEM!!!</size>",
  ui_story_5028_50280901_81_dialog_content = "Ai! Certo, certo, pare de me chutar!",
  ui_story_5028_50280901_82_dialog_content = "Eu... eu entendo! Eu prometo...",
  ui_story_5028_50280901_83_dialog_content = "Eu compro o que você quiser!",
  ui_story_5028_50280901_84_dialog_content = "Agora é isso que eu gosto de ouvir!",
  ui_story_5028_50280901_85_dialog_content = "(Eu nunca vou ser capaz de falar sobre isso!)",
  ui_story_5028_50280901_86_dialog_content = "(Me perdoe, Vice. Estou ficando sem dinheiro... De novo...)",
  ui_story_5028_50280901_87_dialog_content = "(Perdoe-me, Soroz. Falta a taxa de manutenção do próximo mês... De novo...)",
  ui_story_5028_50280901_88_dialog_content = "...",
  ui_story_5028_50280901_89_dialog_content = "Olhe para lá. Isso não parece PlayerName?",
  ui_story_5028_50280901_90_dialog_content = "Isso não se parece apenas com ele... É ele!",
  ui_story_5028_50280901_91_dialog_content = "Infelizmente, ele está muito longe para que meu chicote o alcance. Que pena...",
  ui_story_5028_50280901_93_dialog_content = "Navegador-!",
  ui_story_5028_50280901_94_dialog_content = "Espere por nós-!",
  ui_story_5028_50280901_95_dialog_content = "Ele pode não ser capaz de nos ouvir a esta distância. Esta rua é bastante movimentada, afinal.",
  ui_story_5028_50280901_96_dialog_content = "Então pare de gaguejar. Basta alcançá-lo.",
  ui_story_5028_50280901_97_dialog_content = "<color=#e8d9bb>Fora da cidade</color>",
  ui_story_5028_50280901_98_dialog_content = "(Fia na verdade está me levando para os arredores da cidade, onde há menos pessoas ao redor...)",
  ui_story_5028_50280901_99_dialog_content = "Sim, este lugar deve fazer muito bem!",
  ui_story_5028_50280901_100_dialog_content = "Estou completamente exausto, PlayerName. Vamos parar aqui e descansar um pouco!",
  ui_story_5028_50280901_101_dialog_content = "Er, o-ok...",
  ui_story_5028_50280901_102_dialog_content = "Mas isso não nos colocará em ainda mais perigo?",
  ui_story_5028_50280901_103_dialog_content = "Já que estou aqui, com o que você tem que se preocupar?",
  ui_story_5028_50280901_104_dialog_content = "Vocês dois parecem estar se divertindo muito, hein?",
  ui_story_5028_50280901_105_dialog_content = "Esse é o cara que está nos seguindo esse tempo todo!",
  ui_story_5028_50280901_106_dialog_content = "Heh, se você já percebeu isso, então não vou perder mais tempo medindo palavras...",
  ui_story_5028_50280901_107_dialog_content = "Por que vocês dois garotos de aparência rica não vêm dar uma volta comigo?",
  ui_story_5028_50280901_108_dialog_content = "Parece que não temos escolha, PlayerName... Vamos com ele por enquanto.",
  ui_story_5028_50280901_109_dialog_content = "O quê?!",
  ui_story_5028_50280901_110_dialog_content = "Vê, amigo? Essa garotinha entende. Agora coloque as mãos atrás das costas para que possamos amarrá-lo bem...",
  ui_story_5028_50280901_111_dialog_content = "(O que diabos está acontecendo? Eu preciso saber antes que seja tarde demais!)",
  ui_story_5028_50280901_112_option_content = "(Força Impulso!)",
  ui_story_5028_50280901_113_dialog_content = "(Fia, você pode me ouvir? O que exatamente está acontecendo agora?!)",
  ui_story_5028_50280901_114_dialog_content = "(Uau! N-não isso de novo!!)",
  ui_story_5028_50280901_115_dialog_content = "(Acalme-se. Eu só quero uma carona para o esconderijo deles.)",
  ui_story_5028_50280901_116_dialog_content = "(Isso nos poupará muito tempo e energia.)",
  ui_story_5028_50280901_117_dialog_content = "(Você está brincando comigo?!)",
  ui_story_5028_50280901_118_dialog_content = "(Apenas sente-se e aproveite o show, confie em mim! Agora, temos que ser um pouco pacientes...)",
  ui_story_5028_50280901_119_dialog_content = "Afinal, hoje é o nosso dia de sorte, rapazes! Mesmo que alguns outros idiotas nos tenham batido em nossa primeira marca...",
  ui_story_5028_50280901_120_dialog_content = "Nossos prêmios de consolação não parecem nada ruins! Hahaha!",
  ui_story_5028_50280901_121_dialog_content = "Terminou de amarrá-los? Bom, agora vamos indo...",
  ui_story_5028_50280901_122_dialog_content = "Argh!",
  ui_story_5028_50280901_123_dialog_content = "Procurar pessoas é uma verdadeira dor...",
  ui_story_5028_50280901_124_dialog_content = "Eu nunca gostaria de ficar preso caçando bandidos durante meu intervalo... Não até que eu precise.",
  ui_story_5028_50280901_125_dialog_content = "Shira!? O que você está fazendo aqui?",
  ui_story_5028_50280901_126_dialog_content = "O que estou fazendo aqui? Hein, o que você está fazendo aqui?",
  ui_story_5028_50280901_127_dialog_content = "Achei que tinha dito para você parar de me causar mais problemas.",
  ui_story_5028_50280901_128_dialog_content = "Mas você ainda achou por bem me perseguir... e agora está fazendo palhaçadas com esses bandidos!",
  ui_story_5028_50280901_129_option_content = "Estamos sendo sequestrados!",
  ui_story_5028_50280901_130_option_content = "Obviamente não \"palhaçada\"!",
  ui_story_5028_50280901_131_dialog_content = "Isso faz parte do nosso plano, mas agora você estragou tudo!",
  ui_story_5028_50280901_133_dialog_content = "Plano? Foda-se. Eu ainda vou continuar com minhas próprias coisas.",
  ui_story_5028_50280901_134_dialog_content = "Só espero que vocês dois parem de ficar no meu caminho.",
  ui_story_5028_50280901_136_dialog_content = "Ugh, ugh... Droga... Como essa garota pode ser tão poderosa?!",
  ui_story_5028_50280901_137_dialog_content = "Vamos, rapazes! Vamos ensinar-lhe uma lição que ela não vai esquecer tão cedo!",
  ui_story_5028_50280901_138_dialog_content = "Também não quero vocês idiotas no meu caminho.",
  ui_story_5028_50280901_139_dialog_content = "Tudo que eu quero ouvir é uma resposta legal e honesta, entendeu?",
  ui_story_5028_50280901_140_dialog_content = "Urgh...!",
  ui_story_5028_50280901_141_dialog_content = "Agora me diga... Onde diabos está Vic?",
  ui_story_5028_50280901_142_dialog_content = "Faça-o curto e doce, cara. Sufocar a vida fora de você assim é muito cansativo, sabe?",
  ui_story_5028_50280901_143_dialog_content = "Urgh... E-foi <color=#FFB400>Gary</color>... Era ele e sua gangue de caçadores... O Chicote de Ferro!",
  ui_story_5028_50280901_144_dialog_content = "Então era ele o tempo todo.",
  ui_story_5028_50280901_145_dialog_content = "Gary? Por que esse nome soa tão familiar...?",
  ui_story_5028_50280901_146_dialog_content = "Não há tempo. Precisamos pegar aquele Peko Rabbit logo para Gary.",
  ui_story_5028_50280901_147_dialog_content = "Eu me lembro agora! Ouvimos aqueles dois bandidos mencionarem alguém chamado Gary enquanto procurávamos um Peko Rabbit!",
  ui_story_5028_50280901_148_dialog_content = "Oh? Sério? Não me lembro de nada disso...",
  ui_story_5028_50280901_149_dialog_content = "Gary... Então ele é o culpado por trás do número decrescente de bestas maravilhosas.",
  ui_story_5028_50280901_150_dialog_content = "Você conhece esse cara?",
  ui_story_5028_50280901_151_dialog_content = "Não há uma maneira fácil de dizer isso. Além disso, não tem nada a ver com você.",
  ui_story_5028_50280901_152_dialog_content = "Onde Gary está se escondendo?",
  ui_story_5028_50280901_153_dialog_content = "Th-Há uma caverna na montanha cerca de seis milhas ao norte! Esse é o esconderijo dele...",
  ui_story_5028_50280901_154_dialog_content = "Aff!",
  ui_story_5028_50280901_155_dialog_content = "Que dor...",
  ui_story_5028_50280901_156_dialog_content = "Ei! Não saia correndo assim de novo!",
  ui_story_5028_50280901_157_dialog_content = "Vamos, PlayerName! Depois dela!",
  ui_story_5028_50280901_158_dialog_content = "Não podemos nos dar ao luxo de perdê-la desta vez!",
  ui_story_5028_50280901_159_dialog_content = "Certo, tudo bem!",
  ui_story_5028_50280901_160_dialog_content = "<color=#e8d9bb>Alguns minutos depois...</color>",
  ui_story_5028_50280901_161_dialog_content = "Todas essas pessoas foram nocauteadas.",
  ui_story_5028_50280901_162_dialog_content = "Huh? Me pergunto por que esses caras estão apenas deitados por aqui?",
  ui_story_5028_50280901_163_dialog_content = "Você os reconhece, Smokey?",
  ui_story_5028_50280901_164_dialog_content = "Eles são apenas alguns bandidos itinerantes que apareceram perto de Umbraton recentemente. Todos eles podem queimar até ficarem crocantes, por tudo que me importa.",
  ui_story_5028_50280901_165_dialog_content = "Hum... Esses sinais de batalha ainda são muito recentes.",
  ui_story_5028_50280901_166_dialog_content = "Se nos apressarmos, podemos ser capazes de acompanhar PlayerName.",
  ui_story_5028_50280901_168_dialog_content = "Vamos acelerar o ritmo.",
  ui_story_5028_50280901_169_dialog_content = "O que poderia PlayerName estar disposto a?",
  ui_story_5028_50280901_170_dialog_content = "<color=#e8d9bb>Fora da Fortaleza dos Bandidos</color>",
  ui_story_5028_50280901_171_dialog_content = "Este deve ser o lugar.",
  ui_story_5028_50280901_172_dialog_content = "Uau... Você é muito rápido, sabia?",
  ui_story_5028_50280901_173_dialog_content = "Aquela abertura ali deve ser a entrada do esconderijo deles, certo?",
  ui_story_5028_50280901_174_dialog_content = "E-Espere por nós!",
  ui_story_5028_50280901_175_dialog_content = "Ei! Olá!",
  ui_story_5028_50280901_176_dialog_content = "Por que você está apontando <color=#FFB400>aquela direção</color>, Shira?",
  ui_story_5028_50280901_177_dialog_content = "Há um monte de bestas maravilhosas?!",
  ui_story_5028_50280901_178_dialog_content = "Onde? Deixe-me ver!",
  ui_story_5028_50280901_179_dialog_content = "E não apenas bestas maravilhosas... Há muitos Eclipsitas também!",
  ui_story_5028_50280901_180_dialog_content = "Graaah—!!",
  ui_story_5028_50280901_181_dialog_content = "Oh não, nós fomos vistos!",
  ui_story_5028_50280901_182_dialog_content = "Vai, Kylo!",
  ui_story_5028_50280901_183_dialog_content = "Ugh... Não outra luta...",
  ui_story_5028_50280902_1_dialog_content = "Kyllo!",
  ui_story_5028_50280902_2_dialog_content = "Lo lo lo ... lo!",
  ui_story_5028_50280902_3_dialog_content = "Graagh!",
  ui_story_5028_50280902_4_dialog_content = "Cuidado para não prejudicar nenhuma dessas feras maravilhosas!",
  ui_story_5028_50280902_5_dialog_content = "Eles são espectadores inocentes em tudo isso!",
  ui_story_5028_50280902_6_dialog_content = "Peko!",
  ui_story_5028_50280902_7_dialog_content = "Não tenha medo, eu não vou te machucar. Venha comigo.",
  ui_story_5028_50280902_8_dialog_content = "Peko Peko!!!",
  ui_story_5028_50280902_9_dialog_content = "Ei! Por que você assustou assim?!",
  ui_story_5028_50280902_10_dialog_content = "Eu não estava tentando! Eu acabei de...",
  ui_story_5028_50280902_11_dialog_content = "Graaah—!!",
  ui_story_5028_50280902_12_dialog_content = "Argh! Que dor!",
  ui_story_5028_50280902_13_dialog_content = "(Shira parece um pouco frustrada...?)",
  ui_story_5028_50280902_14_dialog_content = "(E parece que as feras maravilhosas não estão dispostas a chegar perto dela. Assim como as que são amigas de Fia...)",
  ui_story_5028_50280902_15_dialog_content = "Bem, os Eclipsites estão todos cuidados. Essas bestas maravilhosas também são assustadas por Shira.",
  ui_story_5028_50280902_16_dialog_content = "Hmph, nenhum deles jamais se opôs à Fia, uma verdadeira extrozoóloga!",
  ui_story_5028_50280902_17_dialog_content = "Mas você não acha estranho? Por que Gary conseguiu manter Eclipsitas e bestas maravilhosas juntos?",
  ui_story_5028_50280902_18_dialog_content = "E era como se estivessem protegendo a caverna.",
  ui_story_5028_50280902_X18_dialog_content = "Eles são treinados para ser assim.",
  ui_story_5028_50280902_19_dialog_content = "Espere... Eclipsites podem ser treinados como outras feras?!",
  ui_story_5028_50280902_20_dialog_content = "Não tenho certeza, mas há um boato de que Gary colocou as mãos <color=#FFB400>um chicote que pode forçar os animais a obedecer seus comandos</color>.",
  ui_story_5028_50280902_21_dialog_content = "Talvez aquele chicote também pudesse ser usado para controlar Eclipsitas.",
  ui_story_5028_50280902_22_dialog_content = "Afinal, usar a violência para forçar os outros à submissão é uma segunda natureza para os bandidos.",
  ui_story_5028_50280902_23_dialog_content = "Então aquelas bestas maravilhosas também estavam sendo forçadas a lutar por eles?",
  ui_story_5028_50280902_24_dialog_content = "Eu diria que é muito provável que tenham sido submetidos ao mesmo tipo de \"treinamento\".",
  ui_story_5028_50280902_25_dialog_content = "Bandidos não são estudiosos; eles usam os métodos mais brutais para realizar seus planos, independentemente dos sentimentos da fera.",
  ui_story_5028_50280902_26_dialog_content = "Mas como eles podem ser tão sem coração?",
  ui_story_5028_50280902_27_dialog_content = "Você também.",
  ui_story_5028_50280902_28_dialog_content = "Vejo que você não sabe nada sobre bestas maravilhosas de qualquer maneira. Você apenas segue os livros e as palavras de Vic para lidar com eles.",
  ui_story_5028_50280902_29_dialog_content = "Chamar-se de extrozoologista, apesar de não ter autocontrole e fazer o que quiser.",
  ui_story_5028_50280902_30_dialog_content = "A este respeito, você não é diferente de Vic.",
  ui_story_5028_50280902_31_dialog_content = "Eu não sou como ele!",
  ui_story_5028_50280902_32_dialog_content = "Se você insiste em negar, deixe-me fazer algumas perguntas.",
  ui_story_5028_50280902_33_dialog_content = "Que temperatura você deve manter para os ovos da coruja Lutumi em sua segunda fase de incubação?",
  ui_story_5028_50280902_34_dialog_content = "Eu conheço esse! 30! Ou talvez... 40?",
  ui_story_5028_50280902_35_dialog_content = "Está 42,5 graus, e cada ovo precisa ser virado a cada seis horas.",
  ui_story_5028_50280902_36_dialog_content = "Eles têm que ser invertidos?!",
  ui_story_5028_50280902_37_dialog_content = "É claro. Caso contrário, a incubação falhará completamente.",
  ui_story_5028_50280902_38_dialog_content = "Eu sabia disso!",
  ui_story_5028_50280902_39_dialog_content = "Eu só tenho que passar por esse caderno mais uma vez!",
  ui_story_5028_50280902_40_dialog_content = "Ver? Você até confia em uma folha de dicas para saber como cuidar das feras maravilhosas que você afirma serem tão importantes para você...",
  ui_story_5028_50280902_41_dialog_content = "Esse é o tipo de pessoa descuidada e pouco profissional que você é.",
  ui_story_5028_50280902_42_dialog_content = "E-eu...",
  ui_story_5028_50280902_43_dialog_content = "Booooom!!!",
  ui_story_5028_50280902_44_dialog_content = "F-Fia?!",
  ui_story_5028_50280902_45_dialog_content = "É por isso que eu sempre digo... As criancinhas são a maior dor que existe.",
  ui_story_5028_50280902_46_dialog_content = "Eu não sou uma criança! Eu não sou!",
  ui_story_5028_50280902_47_dialog_content = "Só uma criança negaria ser assim.",
  ui_story_5028_50280902_48_dialog_content = "Aconselho-o a recuar enquanto ainda pode, e liberar seus amiguinhos de volta para onde eles pertencem.",
  ui_story_5028_50280902_49_dialog_content = "É o bastante! Você não pode ver o quão ruim você está fazendo ela se sentir?",
  ui_story_5028_50280902_50_dialog_content = "Argh!",
  ui_story_5028_50280902_51_dialog_content = "Você é parte da razão pela qual ela é assim também.",
  ui_story_5028_50280902_52_dialog_content = "Hã?",
  ui_story_5028_50280902_53_dialog_content = "Se você não disciplinar uma criança mimada como ela, ela nunca aprenderá a crescer.",
  ui_story_5028_50280902_54_dialog_content = "Se vocês continuarem sendo tão imprudentes como sempre foram, mais cedo ou mais tarde... Vocês vão se encontrar em um mundo de dor.",
  ui_story_5028_50280902_55_dialog_content = "Assim como eu fiz.",
  ui_story_5028_50280902_56_dialog_content = "Uau! Fique, fique onde está!",
  ui_story_5028_50280902_57_dialog_content = "Esse cara com certeza adora decolar sem outra palavra, não é?",
  ui_story_5028_50280902_58_dialog_content = "Ela correu direto para dentro da caverna.",
  ui_story_5028_50280902_59_dialog_content = "Ela continuou falando sozinha... e... e até me acusou de...",
  ui_story_5028_50280902_60_dialog_content = "Você está bem, Fia?",
  ui_story_5028_50280902_61_dialog_content = "Olá!",
  ui_story_5028_50280902_62_dialog_content = "Eu... eu nunca vou desistir tão fácil! Nunca!!!",
  ui_story_5028_50280902_63_dialog_content = "O quê?!",
  ui_story_5028_50280902_64_dialog_content = "Estou tão determinado a me tornar um extrozoologista. Este ridículo nunca pode me segurar!",
  ui_story_5028_50280902_65_dialog_content = "Vamos alcançá-la!",
  ui_story_5028_50280902_66_dialog_content = "Todos os guardas na entrada foram nocauteados. Esta é a nossa chance de entrar e resgatar meu Mestre!",
  ui_story_5028_50280902_67_dialog_content = "Ela disse que o nome dela é Shira, certo?",
  ui_story_5028_50280902_68_dialog_content = "Eu definitivamente vou mostrar a ela o quão capaz eu sou!",
  ui_story_5028_50281001_1_dialog_content = "Esta é a base escondida de Gary? Que mau gosto.",
  ui_story_5028_50281001_2_dialog_content = "Há gaiolas imundas e vazias espalhadas por todo o lugar. Cheira muito mal.",
  ui_story_5028_50281001_3_dialog_content = "Receio que muitas bestas maravilhosas estavam sendo mantidas aqui até recentemente.",
  ui_story_5028_50281001_4_dialog_content = "Todas as jaulas foram deixadas abertas, mas não há feras à vista...",
  ui_story_5028_50281001_5_dialog_content = "Shira os libertou em seu caminho?",
  ui_story_5028_50281001_6_dialog_content = "Espere...",
  ui_story_5028_50281001_7_dialog_content = "Cuidado, Fia. Sinto muitas bestas maravilhosas vindo por aqui.",
  ui_story_5028_50281001_8_dialog_content = "Mova-se ou você será esmagado!",
  ui_story_5028_50281001_9_dialog_content = "Hã?",
  ui_story_5028_50281001_10_dialog_content = "O quê?!",
  ui_story_5028_50281001_11_dialog_content = "Espere, o que está acontecendo aqui?",
  ui_story_5028_50281001_12_dialog_content = "É melhor alguém me dizer agora!",
  ui_story_5028_50281001_13_dialog_content = "Ei você! Diga-me, o que diabos aconteceu aqui?",
  ui_story_5028_50281001_14_dialog_content = "Glória!",
  ui_story_5028_50281001_15_dialog_content = "O-O quê?!",
  ui_story_5028_50281001_16_dialog_content = "Você diz que há um estranho aterrorizante e assassino esperando à frente?",
  ui_story_5028_50281001_17_dialog_content = "E que esse estranho foi quem te libertou antes de correr mais fundo na caverna?",
  ui_story_5028_50281001_18_dialog_content = "Um estranho terrível e assassino...",
  ui_story_5028_50281001_19_option_content = "Poderia estar falando sobre o líder dos bandidos?",
  ui_story_5028_50281001_20_dialog_content = "Não seja tão ingênuo, PlayerName.",
  ui_story_5028_50281001_21_dialog_content = "O líder dessa gangue de bandidos nunca deixaria uma única besta maravilhosa escapar sob seu comando.",
  ui_story_5028_50281001_22_dialog_content = "Y-Sim, você está certo.",
  ui_story_5028_50281001_23_dialog_content = "A pessoa de quem está falando... provavelmente é Shira.",
  ui_story_5028_50281001_24_dialog_content = "Então o \"cara assustador\" tem aterrorizado tantas feras ultimamente... Você não acha...",
  ui_story_5028_50281001_25_option_content = "Poderia ser Shira também?",
  ui_story_5028_50281001_26_dialog_content = "Então é assim que as feras maravilhosas a veem, hein? Terrível e assassino...",
  ui_story_5028_50281001_27_dialog_content = "Não posso dizer que não se alinha com sua atitude podre ou aquele rosto dela.",
  ui_story_5028_50281001_28_dialog_content = "Eu ficaria com medo se eu fosse uma fera também!",
  ui_story_5028_50281001_29_dialog_content = "Mas agora não é hora de se preocupar com essas feras. Eles não parecem estar feridos e podem fugir daqui por conta própria.",
  ui_story_5028_50281001_30_dialog_content = "Precisamos continuar procurando pelo Mestre Vic.",
  ui_story_5028_50281001_31_dialog_content = "Claro.",
  ui_story_5028_50281001_32_dialog_content = "Está escuro como breu aqui. não consigo ver nada...",
  ui_story_5028_50281001_33_dialog_content = "Eles estavam mantendo aqueles pobres animais no escuro assim o tempo todo?",
  ui_story_5028_50281001_34_dialog_content = "É tão desanimador...",
  ui_story_5028_50281001_35_dialog_content = "Hmph! O que você é, com medo do escuro? Eu nunca soube que o último celestita era um gato tão medroso!",
  ui_story_5028_50281001_36_dialog_content = "É... Fia? L-Olhe para trás...",
  ui_story_5028_50281001_37_dialog_content = "Por que, para que você possa me assustar? Desculpe amigo, isso é tão clichê.",
  ui_story_5028_50281001_38_dialog_content = "Vocês dois... ainda me seguiram até aqui.",
  ui_story_5028_50281001_39_dialog_content = "Uau!!!",
  ui_story_5028_50281001_40_dialog_content = "O-o que você pensa que está fazendo, se esgueirando atrás de mim assim?!",
  ui_story_5028_50281001_41_dialog_content = "L-Vamos deixar uma coisa clara! V-você não me assustou agora!",
  ui_story_5028_50281001_42_dialog_content = "...",
  ui_story_5028_50281001_43_dialog_content = "Shira? Vic não está com você?",
  ui_story_5028_50281001_44_dialog_content = "Victor? Não, ele ainda está amarrado em uma parte mais profunda da caverna.",
  ui_story_5028_50281001_45_dialog_content = "Então por que você não o resgatou?",
  ui_story_5028_50281001_46_dialog_content = "Desamarrá-lo seria muito doloroso. Carregar ele seria uma dor ainda maior.",
  ui_story_5028_50281001_47_dialog_content = "Ei! Você não acha que usa muito essa desculpa?!",
  ui_story_5028_50281001_48_dialog_content = "Além disso, mesmo que eu o libertasse, não há como saber se ele se meteria em problemas ainda maiores.",
  ui_story_5028_50281001_49_dialog_content = "Não sei como ele espera proteger bestas maravilhosas com essa mente dispersa.",
  ui_story_5028_50281001_50_dialog_content = "Isso é algo melhor deixar para alguém mais profissional.",
  ui_story_5028_50281001_51_dialog_content = "Bem, pelo menos podemos concordar em algo: nosso Mestre é realmente pouco confiável.",
  ui_story_5028_50281001_52_dialog_content = "Mas como um extrozoólogo, farei tudo ao meu alcance para proteger as feras maravilhosas do mundo em seu lugar!",
  ui_story_5028_50281001_53_dialog_content = "Hmph. Qualquer que seja.",
  ui_story_5028_50281001_54_dialog_content = "Vic está lá. Se você quiser resgatá-lo, vá em frente.",
  ui_story_5028_50281001_55_dialog_content = "Apenas tente não ficar no meu caminho.",
  ui_story_5028_50281001_56_dialog_content = "Grr... Ela está olhando para mim de novo!",
  ui_story_5028_50281001_57_dialog_content = "Droga... Eu juro, um dia desses, eu vou acabar com ela com minhas habilidades!",
  ui_story_5028_50281001_58_dialog_content = "Ei!!!",
  ui_story_5028_50281001_59_dialog_content = "Você também acha, não é Kyllo?",
  ui_story_5028_50281001_60_dialog_content = "Vamos tirar o meu Mestre daqui!",
  ui_story_5028_50281001_61_dialog_content = "<color=#e8d9bb>Nas profundezas da Fortaleza de Gary</color>",
  ui_story_5028_50281001_62_dialog_content = "Mestre Vic!",
  ui_story_5028_50281001_63_dialog_content = "Você se meteu em uma verdadeira confusão desta vez, Mestre...",
  ui_story_5028_50281001_64_dialog_content = "Nesse caso, vou desamarrá-lo gentilmente.",
  ui_story_5028_50281001_65_dialog_content = "Uau! Eu sabia que você viria em meu socorro mais cedo ou mais tarde!",
  ui_story_5028_50281001_66_dialog_content = "E nem um minuto tarde demais! Minhas mãos ficaram dormentes com essas restrições...",
  ui_story_5028_50281001_67_dialog_content = "E quem pode ser?",
  ui_story_5028_50281001_68_dialog_content = "Olá, Vic. Meu nome é PlayerName, e eu sou-",
  ui_story_5028_50281001_69_option_content = "Eu sou o celestita que Fia capturou.",
  ui_story_5028_50281001_70_dialog_content = "Sim!",
  ui_story_5028_50281001_71_dialog_content = "Este é um celestita, uma das bestas mais raras que já peguei!",
  ui_story_5028_50281001_72_dialog_content = "Só resta um em toda a existência!",
  ui_story_5028_50281001_73_option_content = "Sou amigo da Fia.",
  ui_story_5028_50281001_74_dialog_content = "Isso mesmo! Ele é outro dos meus maravilhosos companheiros animais!",
  ui_story_5028_50281001_75_dialog_content = "O único celestita em todo o mundo!",
  ui_story_5028_50281001_76_dialog_content = "Oh? E você conseguiu pegá-lo?",
  ui_story_5028_50281001_77_dialog_content = "Pode apostar!",
  ui_story_5028_50281001_78_dialog_content = "E não só isso – completei todas as tarefas que você me atribuiu.",
  ui_story_5028_50281001_79_dialog_content = "Mais impressionante...",
  ui_story_5028_50281001_80_dialog_content = "Certamente não serei um extrozoólogo se não conseguir lidar com algumas coisinhas assim.",
  ui_story_5028_50281001_81_dialog_content = "Você encontrando um celestita significa que a próxima fase do meu plano está melhorando.",
  ui_story_5028_50281001_82_dialog_content = "E o que é isso?",
  ui_story_5028_50281001_83_dialog_content = "O último passo em seu caminho para completar seu aprendizado é parar o plano nefasto de Gary!",
  ui_story_5028_50281001_84_dialog_content = "Espere um segundo!",
  ui_story_5028_50281001_85_dialog_content = "Você não disse isso sobre o que eu acabei de fazer?",
  ui_story_5028_50281001_86_dialog_content = "Naturalmente, tive que preservar uma camada de sigilo. Sua verdadeira última missão agora é revelada. De qualquer forma, não é assim que acontece a maioria das grandes aventuras?",
  ui_story_5028_50281001_87_dialog_content = "Não confiável! Eu sabia que não posso acreditar em suas palavras!",
  ui_story_5028_50281001_88_dialog_content = "Sobre o que vocês dois estão...",
  ui_story_5028_50281001_89_dialog_content = "Alguém pode me dizer o que diabos está acontecendo?",
  ui_story_5028_50281001_90_dialog_content = "De qualquer forma, qual é a treta entre você e esse Gary? E por que diabos ele iria querer seqüestrar você?",
  ui_story_5028_50281001_91_dialog_content = "É uma longa história...",
  ui_story_5028_50281001_92_dialog_content = "Houve um tempo em que contei Gary entre meus amigos mais próximos.",
  ui_story_5028_50281001_93_dialog_content = "Meu fascínio por essas criaturas extraordinárias me levou a lugares inusitados. Encontrei-me evitado pela maioria na sociedade educada.",
  ui_story_5028_50281001_94_dialog_content = "Mas Gary não se cansou de mim quando soube da minha experiência em extrozoologia. Ele ficava dia e noite para sondar as profundezas do meu conhecimento.",
  ui_story_5028_50281001_95_dialog_content = "Achei que tinha encontrado uma alma gêmea, um colega especialista procurando avançar os limites de nosso campo.",
  ui_story_5028_50281001_96_dialog_content = "Isto é, até que um dia, eu estava bebendo em um estupor em uma taverna de Umbraton quando ele me perguntou—",
  ui_story_5028_50281001_97_dialog_content = "Já que você sabe tanto sobre essas criaturas maravilhosas, Vic.",
  ui_story_5028_50281001_98_dialog_content = "Certamente você também deve saber qual animal é o mais poderoso?",
  ui_story_5028_50281001_99_dialog_content = "O mais poderoso... um-animal?",
  ui_story_5028_50281001_100_dialog_content = "Ah. Claro que sim, hic—",
  ui_story_5028_50281001_101_dialog_content = "O animal mais poderoso do nosso mundo é... <color=#FFB400>Kyllo</color>!",
  ui_story_5028_50281001_102_dialog_content = "Heh. Faça um Kyllo confiar em você, e ouso dizer que o mundo inteiro seria... sua ostra!",
  ui_story_5028_50281001_103_dialog_content = "Com Kyllos ao seu lado... hic... você poderia quebrar os portões de Gannon City, e chutar as portas de Lumopolis, fácil!",
  ui_story_5028_50281001_104_dialog_content = "A pergunta de Gary não foi simplesmente motivada por um senso de curiosidade, suponho?",
  ui_story_5028_50281001_105_dialog_content = "Heh. Levei tanto tempo para descobrir suas verdadeiras intenções.",
  ui_story_5028_50281001_106_dialog_content = "Havia apenas uma razão pela qual ele fez amizade comigo.",
  ui_story_5028_50281001_107_dialog_content = "O que foi isso, exatamente?",
  ui_story_5028_50281001_108_dialog_content = "Vingança. Ele queria vingança, particularmente contra todas as bestas maravilhosas.",
  ui_story_5028_50281001_109_dialog_content = "Por quê?",
  ui_story_5028_50281001_110_dialog_content = "Caramba se eu sei!",
  ui_story_5028_50281001_111_dialog_content = "No final do dia, ele simplesmente desapareceu de mim depois disso.",
  ui_story_5028_50281001_112_dialog_content = "A próxima vez que ele apareceu foi durante aquele sequestro.",
  ui_story_5028_50281001_113_dialog_content = "Mestre Vic, qual seria o sentido de seqüestrá-lo? Você não é exatamente rico. Na verdade, você parece um pouco duro.",
  ui_story_5028_50281001_114_dialog_content = "Dói-me ouvir você dizer isso, Fia.",
  ui_story_5028_50281001_115_dialog_content = "Apenas responda a sério por um momento!",
  ui_story_5028_50281001_116_dialog_content = "Ai!",
  ui_story_5028_50281001_117_dialog_content = "Ele queria saber onde Kyllos se aninhava.",
  ui_story_5028_50281001_118_dialog_content = "O quê?!",
  ui_story_5028_50281001_119_dialog_content = "Então eu acho que ele realmente acredita que domesticar Kyllos lhe dará tudo o que ele precisa e incomparável?",
  ui_story_5028_50281001_120_dialog_content = "Mas isso não é nada mais do que outra fantasia gerada pela sua imaginação hiperativa?",
  ui_story_5028_50281001_121_dialog_content = "...",
  ui_story_5028_50281001_122_dialog_content = "Se você estiver certo sobre os Kyllos, então o mundo inteiro pode estar em perigo...",
  ui_story_5028_50281001_123_dialog_content = "Não se preocupe. Tenho certeza que vai dar certo.",
  ui_story_5028_50281001_124_dialog_content = "Gary nunca pode influenciar os eventos mundiais, mesmo que de alguma forma conseguisse todos os Kyllo.",
  ui_story_5028_50281001_125_dialog_content = "Podemos deixá-lo com seus dispositivos.",
  ui_story_5028_50281001_126_dialog_content = "...",
  ui_story_5028_50281001_127_dialog_content = "<size=50>Não!</size>",
  ui_story_5028_50281001_128_dialog_content = "Nenhum extrozoologista profissional com qualquer honra, como o meu futuro eu, poderia ficar parado e ver isso acontecer!",
  ui_story_5028_50281001_129_dialog_content = "Ei!",
  ui_story_5028_50281001_130_dialog_content = "Ahhh...",
  ui_story_5028_50281001_131_dialog_content = "Estamos falando de um bando de bandidos escravizando essas bestas maravilhosas para suas maldades! Você acha que eles se importam com eles ou os tratam bem?",
  ui_story_5028_50281001_132_dialog_content = "Se deixarmos esse Gary capturá-los, ele os colocará no moedor de carne até que eles façam o que ele quer!",
  ui_story_5028_50281001_133_dialog_content = "Forçar essas belas criaturas a trair seus instintos é grosseiramente imoral – e não pode ser tolerado!",
  ui_story_5028_50281001_134_dialog_content = "Oi! Esse é o espírito!",
  ui_story_5028_50281001_135_dialog_content = "Vamos continuar canalizando esses sentimentos enquanto localizamos Gary e interrompemos seu plano maluco!",
  ui_story_5028_50281001_136_dialog_content = "Eu lhe darei o benefício da dúvida mais uma vez – apenas uma vez, pelo bem dos Kyllos!",
  ui_story_5028_50281001_137_dialog_content = "Meus maravilhosos companheiros e eu trabalharemos juntos para resolver essa ameaça maligna!",
  ui_story_5028_50281001_138_dialog_content = "Então eu juro como um extrozoologista em ascensão!",
  ui_story_5028_50281001_139_dialog_content = "E posso contar com todos vocês, Kyllo, Peko, Glooey, Bica e PlayerName, não posso?",
  ui_story_5028_50281001_140_dialog_content = "Ei!",
  ui_story_5028_50281001_141_dialog_content = "Peko peko!",
  ui_story_5028_50281001_142_dialog_content = "Gloo...",
  ui_story_5028_50281001_143_dialog_content = "Oi oi!",
  ui_story_5028_50281001_144_dialog_content = "Ah... ok?",
  ui_story_5028_50281001_145_dialog_content = "Ok! Vamos então!",
  ui_story_5028_50281001_146_dialog_content = "Vocês parecem quase prontos para derrubar uma fortaleza. Acho que minha presença aqui é um tanto supérflua então...",
  ui_story_5028_50281001_147_dialog_content = "Seu estimado Mestre deve, portanto, aguardar notícias de seu retorno seguro de casa – ai, ai, ai!",
  ui_story_5028_50281001_148_dialog_content = "Fácil lá! Os braços e pernas do seu pobre velho mestre não estão à altura desse tipo de punição cruel e incomum!",
  ui_story_5028_50281001_149_dialog_content = "Perdoe-me por pensar o contrário depois que um certo alguém disse que era um \"eterno jovem de 18 anos\".",
  ui_story_5028_50281001_150_dialog_content = "A-ha-ha...",
  ui_story_5028_50281001_151_dialog_content = "Isso não é tudo feito principalmente por você, Mestre?",
  ui_story_5028_50281001_152_dialog_content = "Não deixe para os outros uma bagunça que você fez e pode ajudar a limpar!",
  ui_story_5028_50281001_153_dialog_content = "Eu só vou te ajudar—",
  ui_story_5028_50281001_154_dialog_content = "Se você disser, por exemplo:",
  ui_story_5028_50281001_155_dialog_content = "\"Por favor, ajude-me, ó poderosa extrozoóloga Fia, a lidar com esses Eclipsitas!\"",
  ui_story_5028_50281001_156_dialog_content = "Haha. Não estamos saltando a arma um pouco? Precisamos descobrir o plano mestre de Gary primeiro.",
  ui_story_5028_50281001_157_dialog_content = "Bem, nesse caso, que tal eu deixar você lidar com aqueles Eclipsitas no caminho de volta?",
  ui_story_5028_50281001_158_dialog_content = "Hahaha... Ah?!",
  ui_story_5028_50281001_159_dialog_content = "Ah! Rugido!",
  ui_story_5028_50281001_160_dialog_content = "Ai! Ajuda!",
  ui_story_5028_50281001_161_dialog_content = "Eu não posso segurá-los sozinho!",
  ui_story_5028_50281002_1_dialog_content = "Ai... minhas pobres costas...",
  ui_story_5028_50281002_2_dialog_content = "Não sou fã de treinos de alta intensidade.",
  ui_story_5028_50281002_3_dialog_content = "Acho que você se subestima. Afinal, você não é muito mais velho do que eu, Vic, é?",
  ui_story_5028_50281002_4_dialog_content = "Nunca julgue um livro pela sua capa, PlayerName.",
  ui_story_5028_50281002_5_dialog_content = "Posso ser um eterno jovem de 18 anos, mas as experiências que tive seriam bastante numerosas pelos seus padrões.",
  ui_story_5028_50281002_6_dialog_content = "Lá vai você de novo, homem bobo. Tão perspicaz!",
  ui_story_5028_50281002_7_dialog_content = "Infelizmente, sua credibilidade está se esgotando!",
  ui_story_5028_50281002_8_dialog_content = "Boo-hoo, estou honestamente com o coração partido, Fia.",
  ui_story_5028_50281002_9_dialog_content = "(Vic está prestes a chorar?!)",
  ui_story_5028_50281002_10_dialog_content = "Certamente não há maior profundidade de solidão do que um Mestre ser abandonado e desprezado por seus aprendizes?",
  ui_story_5028_50281002_11_dialog_content = "Acho que entendo por que Shira nem sequer lhe deu a hora do dia quando você precisava de ajuda. Você é trabalho duro.",
  ui_story_5028_50281002_12_dialog_content = "Ei! Shira está atualmente muito ocupada com seus próprios problemas, muito obrigado. Por isso ela não interveio.",
  ui_story_5028_50281002_13_dialog_content = "Problemas? Que problemas?",
  ui_story_5028_50281002_14_dialog_content = "Que tipo de problema poderia inspirá-la a deixar seu Mestre para bandidos?",
  ui_story_5028_50281002_15_dialog_content = "Shira, pobre criança, está enfeitiçada pelo mesmo interesse apaixonado por bestas maravilhosas que todos nós compartilhamos.",
  ui_story_5028_50281002_16_dialog_content = "Infelizmente, seus esforços foram atolados por um pouco de azar. Você notou algo incomum sobre ela?",
  ui_story_5028_50281002_17_dialog_content = "Você está se referindo a...",
  ui_story_5028_50281002_18_dialog_content = "Seus pés com tentáculos?",
  ui_story_5028_50281002_19_dialog_content = "Hmm... Você poderia colocar assim.",
  ui_story_5028_50281002_20_dialog_content = "As bestas maravilhosas têm medo dela?",
  ui_story_5028_50281002_21_dialog_content = "De fato. Perceptivo de você.",
  ui_story_5028_50281002_22_dialog_content = "Um infeliz incidente fundiu as pernas de Shira com as de um polvo próximo.",
  ui_story_5028_50281002_23_dialog_content = "Como os animais a amavam antigamente. Após sua transformação, eles agora se aproximam com medo à distância, se é que se aproximam.",
  ui_story_5028_50281002_24_dialog_content = "Um polvo representa uma espécie estranha e aterrorizante para a maioria dos animais.",
  ui_story_5028_50281002_25_dialog_content = "Foi um golpe terrível para Shira, com certeza. Mas nada que diminua sua paixão pelo campo.",
  ui_story_5028_50281002_26_dialog_content = "Se sua paixão mudou, podemos dizer que mudou apenas para bestas maravilhosas.",
  ui_story_5028_50281002_27_dialog_content = "O que você quer dizer?",
  ui_story_5028_50281002_28_dialog_content = "Não me diga que você não notou nada?",
  ui_story_5028_50281002_29_dialog_content = "Ela se importa profundamente com bestas maravilhosas, eu vou dar a ela isso...",
  ui_story_5028_50281002_30_dialog_content = "Mas ela passou a me ver como nada mais do que um \"hobbyist\"!",
  ui_story_5028_50281002_31_dialog_content = "Ela me considera tão amadora, ela nem confia na segurança dos meus métodos.",
  ui_story_5028_50281002_32_dialog_content = "... Isso lhe parece uma opinião fundamentada?",
  ui_story_5028_50281002_33_dialog_content = "...",
  ui_story_5028_50281002_34_dialog_content = "Oh, Shira, sinto muito pelo nosso Mestre...",
  ui_story_5028_50281002_35_dialog_content = "Vejo que a mesma atitude atingiu você também, Fia.",
  ui_story_5028_50281002_36_dialog_content = "De qualquer forma, não é o primeiro mal-entendido com o qual tive que lidar em minha vida, e não será o último.",
  ui_story_5028_50281002_37_dialog_content = "Para resumir, Shira não gostou dos meus métodos \"extemporâneos\" e concentra todos os seus esforços em se tornar uma extrozoóloga profissional.",
  ui_story_5028_50281002_38_dialog_content = "Um \"extrozoólogo profissional\"? Existe uma coisa dessas?",
  ui_story_5028_50281002_39_dialog_content = "Bem, ela vasculhou muitos materiais arcanos e projetou muitos métodos para observar bestas maravilhosas.",
  ui_story_5028_50281002_40_dialog_content = "Por exemplo, atribuindo marcas de tornozelo a bestas maravilhosas que ela encontra na natureza antes de liberá-las de volta.",
  ui_story_5028_50281002_41_dialog_content = "Então, quando ela captura apenas um tipo específico de animais maravilhosos, ela pode obter uma estimativa aproximada de sua população total pelo número de marcas de tornozelo.",
  ui_story_5028_50281002_42_dialog_content = "Então foi Shira quem colocou todas aquelas etiquetas nos pés dos Drakolions?",
  ui_story_5028_50281002_43_dialog_content = "Sim. Nós provavelmente. Quem mais faria isso, exceto ela?",
  ui_story_5028_50281002_44_dialog_content = "Venha para pensar sobre isso, ela veio com algumas técnicas bacanas. Alguns deles, tenho que admitir, são muito engenhosos!",
  ui_story_5028_50281002_45_dialog_content = "Mas com o passar do tempo, nossas \"diferenças de opinião\" só pioraram!",
  ui_story_5028_50281002_46_dialog_content = "Ela culpa seu acidente parcialmente por sua falta de conhecimento, mas também por meu... erro.",
  ui_story_5028_50281002_47_dialog_content = "Ela deixou de me considerar um praticante sem seriedade para uma espécie de perigo a ser desprezado!",
  ui_story_5028_50281002_48_dialog_content = "Huh? Então você é responsável pelo que aconteceu com Shira?",
  ui_story_5028_50281002_49_dialog_content = "Não, absolutamente não! Isso é o que significa acidente! Ninguém teve culpa!",
  ui_story_5028_50281002_50_dialog_content = "Shira queria saber de onde ela veio e estava buscando conhecimento de seu passado.",
  ui_story_5028_50281002_51_dialog_content = "Percebi que ela tinha um pequeno polvo, então a aconselhei a verificar o habitat de onde seu amiguinho veio.",
  ui_story_5028_50281002_52_dialog_content = "Como eu poderia saber que ela mapearia um navio até o fundo do oceano e depois teria a sorte podre de atingir uma tempestade de raios...",
  ui_story_5028_50281002_53_dialog_content = "Aquele pequeno polvo se fundiu com Shira para salvar sua vida através de seus extraordinários poderes de regeneração.",
  ui_story_5028_50281002_54_dialog_content = "Tudo o que fiz foi revelar a maneira de encontrar o habitat dos polvos e nada mais errado.",
  ui_story_5028_50281002_55_dialog_content = "Hmph, você não vai conseguir minha simpatia mesmo com essa cara de \"Estou prestes a chorar\".",
  ui_story_5028_50281002_56_dialog_content = "Isso é o que acontece quando você dá conselhos errados de forma irresponsável.",
  ui_story_5028_50281002_57_dialog_content = "Se você quer acertar as coisas, a primeira coisa que temos a fazer é encontrar o habitat dos Kyllos e impedir o plano maluco de Gary!",
  ui_story_5028_50281002_58_dialog_content = "Suspiro, você tem todas as marcas de um aprendiz, Fia, mas nada de respeito.",
  ui_story_5028_50281002_59_dialog_content = "Parece que depois de um longo sequestro, ainda tenho que aguentar uma viagem de estômago vazio...",
  ui_story_5028_50281002_60_dialog_content = "Está com fome?",
  ui_story_5028_50281002_61_dialog_content = "Este pão sírio vai te encher!",
  ui_story_5028_50281002_62_dialog_content = "Ooh? Detecto cheiro de farinha e um brilho dourado crocante...? Não se importe se eu começar agora...",
  ui_story_5028_50281002_63_dialog_content = "Nom-nom, minha fome o transformou no pão achatado mais delicioso que se possa imaginar!",
  ui_story_5028_50281002_64_dialog_content = "De alguma forma parece familiar... Espere. Por que você está carregando um pão sírio com você, Fia?",
  ui_story_5028_50281002_65_dialog_content = "Porque eu pensei que os vagabundos que sequestraram meu Mestre poderiam não ter tido consideração o suficiente para fornecer refeições.",
  ui_story_5028_50281002_66_dialog_content = "Então eu trouxe provisões especiais.",
  ui_story_5028_50281002_67_dialog_content = "Nom-nom, um grande aprendiz de fato é aquele que considera as necessidades de seu Mestre!",
  ui_story_5028_50281002_68_dialog_content = "Embora eu deva dizer que os comprei há alguns dias. Espero que não tenham ido mal.",
  ui_story_5028_50281002_69_dialog_content = "Nom—tosse, ei!",
  ui_story_5028_50281002_70_dialog_content = "Victor?!",
  ui_story_5028_50281002_71_dialog_content = "Tosse, estou bem agora. Por enquanto, de qualquer maneira.",
  ui_story_5028_50281002_72_dialog_content = "Gostaria de um pouco mais? Trouxe alguns outros com sabores diferentes.",
  ui_story_5028_50281002_73_dialog_content = "T-Tudo bem. Eu já estou cheio. Em apenas um.",
  ui_story_5028_50281002_74_dialog_content = "Vamos então!",
  ui_story_5028_50281002_75_dialog_content = "E pare aquele homem mau e sua trama!",
  ui_story_5028_50281002_76_dialog_content = "Então esses foram os bandidos que sequestraram PlayerName?",
  ui_story_5028_50281002_77_dialog_content = "Parecem bastante estranhos.",
  ui_story_5028_50281002_78_dialog_content = "Com o que você se importa? Vamos entrar e limpar o chão com eles. Isso soa como um plano suficiente para você?",
  ui_story_5028_50281002_79_dialog_content = "Quão imprudente, Smokey.",
  ui_story_5028_50281002_80_dialog_content = "Não era o que eu esperava de um membro da nobreza.",
  ui_story_5028_50281002_81_dialog_content = "Shhh. Sem discutir.",
  ui_story_5028_50281002_82_dialog_content = "Tsc...",
  ui_story_5028_50281002_83_dialog_content = "Vamos apenas segui-los. Então vamos entrar e resgatar PlayerName quando surge a oportunidade!",
  ui_story_5028_50281101_1_dialog_content = "<color=#e8d9bb>O habitat dos Kyllos</color>",
  ui_story_5028_50281101_2_dialog_content = "Devo admitir que você tem algumas habilidades, minha jovem.",
  ui_story_5028_50281101_3_dialog_content = "Mas quanto tempo você pode segurar?",
  ui_story_5028_50281101_4_dialog_content = "Gary",
  ui_story_5028_50281101_X4_dialog_content = "38 anos",
  ui_story_5028_50281101_X5_dialog_content = "Um vilão que sai por aí capturando bestas maravilhosas.",
  ui_story_5028_50281101_5_dialog_content = "Se você se rebaixar a ponto de usar essas criaturas contra mim, posso ver que você é alguém que preciso parar...",
  ui_story_5028_50281101_6_dialog_content = "E posso ver que você é alguém com o poder de derrotar facilmente os Eclipsites.",
  ui_story_5028_50281101_7_dialog_content = "No entanto, você está tão prejudicado por seu amor imaginário pelos animais que não está disposto a fazer o que é necessário.",
  ui_story_5028_50281101_8_dialog_content = "Melhor suportar seu ataque ultrajante, eu acho? Pobre tolo.",
  ui_story_5028_50281101_9_dialog_content = "Cale-se.",
  ui_story_5028_50281101_10_dialog_content = "Pelo menos eu sei quem responsabilizar por todos esses crimes.",
  ui_story_5028_50281101_11_dialog_content = "E quem fez esses pobres animais maravilhosos cativos de guerra!",
  ui_story_5028_50281101_12_dialog_content = "cativos de guerra? Heh. Ridículo!",
  ui_story_5028_50281101_13_dialog_content = "Como você ousa chamar criaturas tão simples e brutais de \"cativas\" de qualquer tipo? Eles não são mais cativos do que qualquer outro animal de carga.",
  ui_story_5028_50281101_14_dialog_content = "Na verdade, esses brutos estúpidos não merecem compartilhar os recursos do mundo e seu ar conosco!",
  ui_story_5028_50281101_15_dialog_content = "Você... cale a boca!",
  ui_story_5028_50281101_16_dialog_content = "*Ronca*",
  ui_story_5028_50281101_17_dialog_content = "Hã?!",
  ui_story_5028_50281101_18_dialog_content = "Vai. Mate ela.",
  ui_story_5028_50281101_19_dialog_content = "Desengane essa tola de suas noções ridículas.",
  ui_story_5028_50281101_20_dialog_content = "Graah! Rugido!",
  ui_story_5028_50281101_21_dialog_content = "Por favor, não...",
  ui_story_5028_50281101_22_dialog_content = "Parem-nos!",
  ui_story_5028_50281101_23_dialog_content = "Ei!",
  ui_story_5028_50281101_24_dialog_content = "Belo tiro, Fia!",
  ui_story_5028_50281101_25_dialog_content = "Obrigado. Não me diga que você está surpreso que eu possa lutar?",
  ui_story_5028_50281101_26_dialog_content = "Shira, você está bem?",
  ui_story_5028_50281101_27_dialog_content = "Por que você é...",
  ui_story_5028_50281101_28_dialog_content = "Você está seguro agora. Estamos aqui para parar Gary!",
  ui_story_5028_50281101_29_dialog_content = "Vic nos contou tudo.",
  ui_story_5028_50281101_30_dialog_content = "Nós vamos ajudá-lo a parar Gary!",
  ui_story_5028_50281101_31_dialog_content = "Saia daqui! Não podemos arriscar.",
  ui_story_5028_50281101_32_dialog_content = "Esse cara é um punhado!",
  ui_story_5028_50281101_33_dialog_content = "Estou chocado que ela tenha conseguido chamar alguma cavalaria.",
  ui_story_5028_50281101_34_dialog_content = "E eu pensei que você teria fugido depois do que aconteceu, Vic.",
  ui_story_5028_50281101_35_dialog_content = "Não sou tão covarde quanto você pensa, Gary.",
  ui_story_5028_50281101_36_dialog_content = "Se você vai entrar em força, talvez eu tenha que me ajudar com alguma ajuda também.",
  ui_story_5028_50281101_37_dialog_content = "Tenho grande prazer em revelar o poder desses terríveis brutos!",
  ui_story_5028_50281101_X37_dialog_content = "Dirija esses Eclipses aqui também. Juntos agora!",
  ui_story_5028_50281101_38_dialog_content = "Argh...",
  ui_story_5028_50281101_39_dialog_content = "Separá-los.",
  ui_story_5028_50281101_40_dialog_content = "Sim, chefe!",
  ui_story_5028_50281101_41_dialog_content = "Aaarrgh!",
  ui_story_5028_50281101_42_dialog_content = "Greve, Kylo, PlayerName!",
  ui_story_5028_50281101_43_dialog_content = "Ei!",
  ui_story_5028_50281101_44_dialog_content = "Huh? E eu?",
  ui_story_5028_50281101_45_dialog_content = "Pare de espaçar! Dê as ordens!",
  ui_story_5028_50281102_1_dialog_content = "Fraco. Tão terrivelmente fraco...",
  ui_story_5028_50281102_2_dialog_content = "Como é que você pode ter feras tão poderosas ao seu lado e ainda não saber nada de como usá-las?",
  ui_story_5028_50281102_3_dialog_content = "Ora, sua...!",
  ui_story_5028_50281102_4_dialog_content = "Esta lição é por conta da casa: dobrar uma criatura para fazer sua vontade na batalha, faça assim...",
  ui_story_5028_50281102_5_dialog_content = "Levantem-se, preguiças patéticas, e destruam-nos!",
  ui_story_5028_50281102_6_dialog_content = "Rugido!!!",
  ui_story_5028_50281102_7_dialog_content = "Você... treinou esse Drakolion?",
  ui_story_5028_50281102_8_dialog_content = "Rugido!!!",
  ui_story_5028_50281102_9_dialog_content = "Ei!",
  ui_story_5028_50281102_10_dialog_content = "Pare com essa loucura! Nenhuma besta maravilhosa quer lutar contra ninguém!",
  ui_story_5028_50281102_11_dialog_content = "Eles não querem?",
  ui_story_5028_50281102_12_dialog_content = "Haha! Ainda bem que não preciso me preocupar com o que essas feras querem!",
  ui_story_5028_50281102_13_dialog_content = "Eu só preciso que eles me temam e me respeitem o suficiente para sacrificar suas vidas!",
  ui_story_5028_50281102_14_dialog_content = "Você ficou totalmente louco! E eu, como extrozoologista, vou cobrar de você!",
  ui_story_5028_50281102_15_dialog_content = "Ótimo trabalho, meu brilhante aprendiz! Você consegue!",
  ui_story_5028_50281102_16_dialog_content = "Seu encorajamento é tão vão quanto inútil.",
  ui_story_5028_50281102_17_dialog_content = "Ó meu Deus. Meu aprendiz está se voltando contra mim novamente...",
  ui_story_5028_50281102_18_dialog_content = "Palavras tão fortes de uma coisa tão pequena!",
  ui_story_5028_50281102_19_dialog_content = "Pena que você não tem forças para apoiá-lo.",
  ui_story_5028_50281102_20_dialog_content = "Roooor!",
  ui_story_5028_50281102_21_dialog_content = "Aaaargh!",
  ui_story_5028_50281102_22_dialog_content = "Fia!!!",
  ui_story_5028_50281102_23_dialog_content = "Hã?!",
  ui_story_5028_50281102_24_dialog_content = "Oh céus. Estamos sendo esmagados...",
  ui_story_5028_50281102_25_dialog_content = "Nós nos rendemos! Por favor, deixe-nos ir.",
  ui_story_5028_50281102_26_dialog_content = "O que você tem? Você não vai oferecer o mínimo de resistência?",
  ui_story_5028_50281102_27_dialog_content = "Que resistência? Não podemos fazer nada.",
  ui_story_5028_50281102_28_dialog_content = "Ele levou você e Fia para sair, não foi?",
  ui_story_5028_50281102_29_dialog_content = "PlayerName é um celestita, não um auroriano. Ele não pode lutar.",
  ui_story_5028_50281102_30_dialog_content = "E já tenho problemas suficientes com minhas pobres pernas e braços.",
  ui_story_5028_50281102_31_dialog_content = "Portanto, nossa única escolha é nos render.",
  ui_story_5028_50281102_32_dialog_content = "Você tem que pelo menos tentar oferecer alguma resistência...",
  ui_story_5028_50281102_33_dialog_content = "Que resistência? Eu digo que escolhemos a sobrevivência prática.",
  ui_story_5028_50281102_34_dialog_content = "Você acha que eu vou deixar você sair daqui se você se render?",
  ui_story_5028_50281102_35_dialog_content = "Não, você vai ficar comigo até poder testemunhar meu momento de grandeza!",
  ui_story_5028_50281102_36_dialog_content = "Prenda-os firmemente e escolte-os para as celas.",
  ui_story_5028_50281102_37_dialog_content = "Sim, chefe!",
  ui_story_5028_50281102_38_dialog_content = "Heh. Você tornou a vida muito difícil para nós da última vez. Agora podemos expressar nossa \"gratidão\".",
  ui_story_5028_50281102_39_dialog_content = "Ei! Olá!",
  ui_story_5028_50281102_40_dialog_content = "Kyllo!",
  ui_story_5028_50281102_41_dialog_content = "Argh!",
  ui_story_5028_50281102_42_dialog_content = "Pare!",
  ui_story_5028_50281102_43_dialog_content = "Não tão apertado! Estou propenso a espasmos no braço. Ai!",
  ui_story_5028_50281102_44_dialog_content = "Ai...",
  ui_story_5028_50281102_45_dialog_content = "É isso então. Estamos completamente e totalmente ferrados...",
  ui_story_5028_50281102_46_dialog_content = "Abra bem os olhos e observe o que estou prestes a lhe mostrar.",
  ui_story_5028_50281102_47_dialog_content = "Mostrarei ao mundo o quão aterrorizantes e poderosos são esses brutos até que a noção esteja firmemente implantada na mente de todos.",
  ui_story_5028_50281102_48_dialog_content = "Oh. Então esse era o seu plano mestre o tempo todo?",
  ui_story_5028_50281102_49_dialog_content = "O que há com você e besta maravilhosa? Por que você os odeia tanto?",
  ui_story_5028_50281102_50_dialog_content = "Duvido que um \"amante de animais\" como você entenderia.",
  ui_story_5028_50281102_51_dialog_content = "Tudo o que você precisa saber é que eu os considero responsáveis por me privar do que mais importava.",
  ui_story_5028_50281102_52_dialog_content = "\"Aquilo que mais importava\"... Hein?",
  ui_story_5028_50281102_53_dialog_content = "Você é irritante, não é?",
  ui_story_5028_50281102_54_dialog_content = "Eu estava a caminho de prender essas criaturas quando você decidiu jogar uma chave inglesa nos trabalhos.",
  ui_story_5028_50281102_55_dialog_content = "Tudo bem. Eu posso me dar ao luxo de ser paciente.",
  ui_story_5028_50281102_56_dialog_content = "Desde que este pequeno não escape...",
  ui_story_5028_50281102_57_dialog_content = "Ei, ei!",
  ui_story_5028_50281102_58_dialog_content = "O que foi?",
  ui_story_5028_50281102_59_dialog_content = "Está fazendo os mesmos sons que um Kyllo, mesmo que pareça um pouco estranho.",
  ui_story_5028_50281102_60_dialog_content = "Também é Kyllo?",
  ui_story_5028_50281102_61_dialog_content = "Toda a minha experiência está me dizendo que sim, eles são da mesma espécie.",
  ui_story_5028_50281102_62_dialog_content = "Existe outro tipo de Kyllo? Como acabou ficando assim?",
  ui_story_5028_50281102_63_dialog_content = "Existem muitas possibilidades.",
  ui_story_5028_50281102_64_dialog_content = "Evolução repentina, fatores ambientais e variação sub-racial podem ser responsáveis por essas diferenças individuais.",
  ui_story_5028_50281102_65_dialog_content = "Parece completamente diferente do meu Kyllo. Tem certeza que são da mesma espécie?",
  ui_story_5028_50281102_66_dialog_content = "Algumas possibilidades podem explicar isso – uh, na verdade nenhuma me vem à mente.",
  ui_story_5028_50281102_67_dialog_content = "Precisamos que você seja mais confiável agora!",
  ui_story_5028_50281102_68_dialog_content = "Heh, valorize esses preciosos momentos cheios de diversão. Eles serão seus últimos.",
  ui_story_5028_50281102_69_dialog_content = "Por que você está fazendo isso?",
  ui_story_5028_50281102_70_dialog_content = "Embora esses brutos não possam entender a linguagem humana, eles podem responder a gritos de sua própria espécie.",
  ui_story_5028_50281102_71_dialog_content = "Ei, ei!",
  ui_story_5028_50281102_72_dialog_content = "Com isso, posso atrair todos os Kyllos por aqui para a minha rede. Então será um processo simples de treinamento.",
  ui_story_5028_50281102_73_dialog_content = "Haha... Hahahahaha!!",
  ui_story_5028_50281102_74_dialog_content = "E todos os Aurorianos de Astra logo saberão de que terrores temíveis eles são capazes!",
  ui_story_5028_50281102_75_dialog_content = "E une-te a mim na mesma dor.",
  ui_story_5028_50281102_76_dialog_content = "Fique de olho neles. Não os deixe escapar.",
  ui_story_5028_50281102_77_dialog_content = "Sim, chefe!",
  ui_story_5028_50281102_78_dialog_content = "<color=#e8d9bb>base do Gary</color>",
  ui_story_5028_50281102_79_dialog_content = "Em que você vá!",
  ui_story_5028_50281102_80_dialog_content = "Não tão áspero!",
  ui_story_5028_50281102_81_dialog_content = "Vou pisar em você quando sair daqui!",
  ui_story_5028_50281102_82_dialog_content = "Sim, esse é o espírito, Fia.",
  ui_story_5028_50281102_83_dialog_content = "Eu não posso acreditar que você ainda está sendo irreverente em um momento como este.",
  ui_story_5028_50281102_84_dialog_content = "Você não tem senso de adequação. Meu Deus, estamos em perigo mortal!",
  ui_story_5028_50281102_85_dialog_content = "Cale-se! Mais uma espiada de você e eu terei todos vocês pendurados!",
  ui_story_5028_50281102_86_dialog_content = "...",
  ui_story_5028_50281102_87_dialog_content = "...",
  ui_story_5028_50281102_88_dialog_content = "Eu não estou te ouvindo! Se você quer que eu pare de falar, então eu vou – oof!",
  ui_story_5028_50281102_89_dialog_content = "Esfrie por alguns minutos enquanto penso em um plano, OK?",
  ui_story_5028_50281102_90_dialog_content = "(O que devo fazer? Não consigo pensar em nada sozinho...)",
  ui_story_5028_50281102_91_dialog_content = "(Ah, certo! Já que não posso falar, por que não uso minha habilidade psíquica para me comunicar com todo mundo?)",
  ui_story_5028_50281102_92_dialog_content = "(Dessa forma, esses bandidos não devem ser capazes de nos notar discutindo.)",
  ui_story_5028_50281102_93_option_content = "Aumento de Força!",
  ui_story_5028_50281102_94_dialog_content = "Fia! Você pode me ouvir?",
  ui_story_5028_50281102_95_dialog_content = "Uau! PlayerName, você pode pelo menos me dar um aviso antes de usar seu poder?",
  ui_story_5028_50281102_96_dialog_content = "Eu sinto Muito. É emergência!",
  ui_story_5028_50281102_97_dialog_content = "Victor?",
  ui_story_5028_50281102_98_dialog_content = "Ah sim, habilidades psíquicas de Caelestite, imagino? Ah, os velhos tempos...",
  ui_story_5028_50281102_99_dialog_content = "E Shira!",
  ui_story_5028_50281102_100_dialog_content = "Eu te escuto.",
  ui_story_5028_50281102_101_dialog_content = "Fia, vamos discutir como podemos fugir!",
  ui_story_5028_50281102_102_dialog_content = "Uma corrida para isso? E como vão fazer isso?",
  ui_story_5028_50281102_103_dialog_content = "Eles pegaram meu Kyllo, e o resto não é páreo para esses bandidos.",
  ui_story_5028_50281102_104_dialog_content = "Você perguntou a Shira? Ela é extremamente forte, mesmo que um pouco estranha. Talvez ela tenha algumas ideias.",
  ui_story_5028_50281102_105_dialog_content = "Shira, você consegue pensar em alguma coisa? Existe alguma maneira de usar os poderes dessas bestas maravilhosas para escapar?",
  ui_story_5028_50281102_106_dialog_content = "Em vez de pensar em uma maneira de colocar essas pobres criaturas contra esses bandidos do mal...",
  ui_story_5028_50281102_107_dialog_content = "Acho que posso ter mais sorte em me livrar dessas malditas cordas.",
  ui_story_5028_50281102_108_dialog_content = "Não deve ser muito difícil arrancá-los assim que eu me recuperar.",
  ui_story_5028_50281102_109_dialog_content = "Mas se eles não nos ajudarem em nada, então... Vic, alguma ideia?",
  ui_story_5028_50281102_110_dialog_content = "Não estamos com tanta pressa, PlayerName.",
  ui_story_5028_50281102_111_dialog_content = "Podemos ter sido imobilizados, mas este pode ser um bom momento para usar suas habilidades celestitas para verificar nossos arredores.",
  ui_story_5028_50281102_112_dialog_content = "Nosso destino está em suas mãos, PlayerName.",
  ui_story_5028_50281102_113_dialog_content = "Bem desse jeito? Em mim?",
  ui_story_5028_50281102_114_dialog_content = "Vou dar o meu melhor.",
  ui_story_5028_50281102_115_option_content = "Aumento de Força!",
  ui_story_5028_50281102_116_dialog_content = "...",
  ui_story_5028_50281102_117_dialog_content = "(Há bandidos patrulhando nas proximidades...)",
  ui_story_5028_50281102_118_dialog_content = "(Algumas bestas maravilhosas enjauladas).",
  ui_story_5028_50281102_119_dialog_content = "(Muitas feras maravilhosas que se parecem com Kyllos?)",
  ui_story_5028_50281102_120_dialog_content = "Vic, não é ótimo. Os bandidos capturaram um monte de Kyllos!",
  ui_story_5028_50281102_121_dialog_content = "Minha nossa. Então ele realmente conseguiu?",
  ui_story_5028_50281102_122_dialog_content = "Não devemos ter muito com o que nos preocupar, a menos que ele consiga despertar as habilidades de Kyllos.",
  ui_story_5028_50281102_123_dialog_content = "Certo. Vou olhar ao redor novamente. Acho que posso sentir alguma atividade distante.",
  ui_story_5028_50281102_124_dialog_content = "Isso é Revy, escondido em algum lixo.",
  ui_story_5028_50281102_125_dialog_content = "Espere, Revy?!",
  ui_story_5028_50281102_126_dialog_content = "PlayerName! Você finalmente me notou!",
  ui_story_5028_50281102_127_dialog_content = "Nós tínhamos acabado de começar e você desapareceu em mim, PlayerName.",
  ui_story_5028_50281102_128_dialog_content = "Isso mesmo, começamos a jogar quando Fia me levou para ajudá-la.",
  ui_story_5028_50281102_129_dialog_content = "Desculpe.",
  ui_story_5028_50281102_130_dialog_content = "Estamos procurando por você há séculos!",
  ui_story_5028_50281102_131_dialog_content = "Nós? Você tem outros com você? Deixe-me dar outra olhada!",
  ui_story_5028_50281102_132_dialog_content = "Isso é Genevieve...",
  ui_story_5028_50281102_133_dialog_content = "PlayerName, você tem um monte de novos companheiros lá?",
  ui_story_5028_50281102_134_dialog_content = "Você é muito popular, PlayerName.",
  ui_story_5028_50281102_135_dialog_content = "Eu viro minha cabeça por um momento e então, uau! Veja quantos seguidores você tem.",
  ui_story_5028_50281102_136_dialog_content = "E é isso Smokey? E ela fez as pazes com Genevieve?",
  ui_story_5028_50281102_137_dialog_content = "Oh. Esses amigos estão com você?",
  ui_story_5028_50281102_138_dialog_content = "Eu estava ansioso por um pouco de diversão ardente.",
  ui_story_5028_50281102_139_dialog_content = "Oh não, por favor, não tire sarro de mim!",
  ui_story_5028_50281102_140_dialog_content = "Excelente. Acho que todos nós juntos seremos capazes de mudar isso definitivamente!",
  ui_story_5028_50281102_141_dialog_content = "Estou em apuros e preciso da sua ajuda!",
  ui_story_5028_50281102_142_dialog_content = "É claro. PlayerName é meu amigo, e estarei sempre aqui para ajudar!",
  ui_story_5028_50281102_143_dialog_content = "Todos nós viemos aqui apenas para encontrá-lo, PlayerName.",
  ui_story_5028_50281102_144_dialog_content = "Obrigada!",
  ui_story_5028_50281102_145_dialog_content = "Fia, Shira, Vic: temos uma saída!",
  ui_story_5028_50281102_146_dialog_content = "Encontrei algumas pessoas para nos ajudar!",
  ui_story_5028_50281102_147_dialog_content = "Huh. Isso levou séculos!",
  ui_story_5028_50281102_148_dialog_content = "Enquanto você estava vagando com sua telepatia, eu já criei um extremamente <color=#FFB400>plano brilhante</color>.",
  ui_story_5028_50281102_149_dialog_content = "Huh? Q-Que plano você inventou?",
  ui_story_5028_50281102_150_dialog_content = "Nunca subestime um extrozoologista!",
  ui_story_5028_50281102_151_dialog_content = "É com isso que começamos, e então vamos...",
  ui_story_5028_50281201_1_dialog_content = "<color=#e8d9bb>Fora da base de Gary</color>",
  ui_story_5028_50281201_2_dialog_content = "O que você acha? Você acha que o plano do chefe pode realmente funcionar?",
  ui_story_5028_50281201_3_dialog_content = "Shh... Silêncio.",
  ui_story_5028_50281201_4_dialog_content = "Não expresse suas dúvidas ou ele vai te enforcar na árvore por uma noite inteira e gelada.",
  ui_story_5028_50281201_5_dialog_content = "E o que era tudo aquilo que Vic estava dizendo?",
  ui_story_5028_50281201_6_dialog_content = "Parece que o chefe realmente acreditou nele!",
  ui_story_5028_50281201_7_dialog_content = "<color=#e8d9bb>Toot-toot</color>",
  ui_story_5028_50281201_8_dialog_content = "Ouça. O chefe tem outro pedido.",
  ui_story_5028_50281201_9_dialog_content = "O que? O que acabou de dizer?",
  ui_story_5028_50281201_10_dialog_content = "<color=#e8d9bb>Toot-toot</color>",
  ui_story_5028_50281201_11_dialog_content = "São... intrusos!",
  ui_story_5028_50281201_12_dialog_content = "Do noroeste!",
  ui_story_5028_50281201_13_dialog_content = "Vamos!",
  ui_story_5028_50281201_14_dialog_content = "Ufa... Onde eles estão?",
  ui_story_5028_50281201_15_dialog_content = "Diabos? Não há nada aqui...",
  ui_story_5028_50281201_16_dialog_content = "<color=#e8d9bb>Toot-toot, toot—</color>",
  ui_story_5028_50281201_17_dialog_content = "O que? Esse é o sinal para tomar café da manhã?",
  ui_story_5028_50281201_18_dialog_content = "Há algo errado com o sistema de sinalização? Quem está fazendo isso?",
  ui_story_5028_50281201_19_dialog_content = "Excelente! O primeiro passo do meu plano mestre é um sucesso retumbante!",
  ui_story_5028_50281201_20_dialog_content = "Coisa boa Revy pegou o livro de sinais do bandido...",
  ui_story_5028_50281201_21_dialog_content = "E o Peko Rabbit fez um ótimo trabalho ao comê-lo!",
  ui_story_5028_50281201_22_dialog_content = "Peko peko!",
  ui_story_5028_50281201_23_dialog_content = "Tudo depende de você agora, Caelestite!",
  ui_story_5028_50281201_24_dialog_content = "Não estou exatamente confortável com isso, mas depois de sofrer tantos quase acidentes...",
  ui_story_5028_50281201_25_dialog_content = "Acho que minhas habilidades de fuga melhoraram tremendamente!",
  ui_story_5028_50281201_26_dialog_content = "Ei, seus bandidos estúpidos! Venha me pegar!",
  ui_story_5028_50281201_27_dialog_content = "O que é isso? Um cativo escapou!",
  ui_story_5028_50281201_28_dialog_content = "Segura aí!",
  ui_story_5028_50281201_29_dialog_content = "Uhh?",
  ui_story_5028_50281201_30_dialog_content = "Esta é a maneira de correr - perto do habitat original dos Kyllos.",
  ui_story_5028_50281201_31_dialog_content = "Soroz parou por aqui quando estava procurando Gary, e...",
  ui_story_5028_50281201_32_dialog_content = "Aquele sujeito que estava perseguindo Soroz ainda está aqui!",
  ui_story_5028_50281201_33_dialog_content = "*Rugindo*",
  ui_story_5028_50281201_34_dialog_content = "Olhe para lá!",
  ui_story_5028_50281201_35_dialog_content = "Que diabos? Outro Drakolion?",
  ui_story_5028_50281201_36_dialog_content = "Rugido!!!",
  ui_story_5028_50281201_37_dialog_content = "Urgh—!",
  ui_story_5028_50281201_38_dialog_content = "Rápido, reporte-se ao chefe!",
  ui_story_5028_50281201_39_dialog_content = "Certo, tudo bem!",
  ui_story_5028_50281201_40_dialog_content = "Esquisito. Os Drakolions acabaram de voar. E por que ainda está tão escuro?",
  ui_story_5028_50281201_41_dialog_content = "Ai!",
  ui_story_5028_50281201_42_dialog_content = "Oi oi! Oi!",
  ui_story_5028_50281201_43_dialog_content = "Excelente! Da próxima vez você não terá que comer uma pedra tão grande...",
  ui_story_5028_50281201_44_dialog_content = "Quem está chamando? O que aconteceu?",
  ui_story_5028_50281201_45_dialog_content = "Ahh!",
  ui_story_5028_50281201_46_dialog_content = "Glória!",
  ui_story_5028_50281201_47_dialog_content = "Isso é algum tipo de brincadeira? O que? O chão está escorregadio de repente?",
  ui_story_5028_50281201_48_dialog_content = "Cau ca!",
  ui_story_5028_50281201_49_dialog_content = "Que diabos?",
  ui_story_5028_50281201_50_dialog_content = "Como estou... tão cansado...",
  ui_story_5028_50281201_51_dialog_content = "Ufa...",
  ui_story_5028_50281201_52_dialog_content = "O plano está indo bem.",
  ui_story_5028_50281201_53_dialog_content = "Eles têm os bandidos em apuros.",
  ui_story_5028_50281201_54_dialog_content = "Nada mal. Estou quase impressionado.",
  ui_story_5028_50281201_55_dialog_content = "Bem, você sabe, afinal, Fia é minha aprendiz, então a excelência é de se esperar.",
  ui_story_5028_50281201_56_dialog_content = "Como não ter sucesso quando sou um extrozoologista profissional?",
  ui_story_5028_50281201_57_dialog_content = "Nem mesmo um dos bandidos apareceu.",
  ui_story_5028_50281201_58_dialog_content = "Um momento, PlayerName. Vou abrir a gaiola e desamarrar você.",
  ui_story_5028_50281201_59_dialog_content = "Ufa. Isso foi muito bom de sua parte.",
  ui_story_5028_50281201_60_dialog_content = "Ei!",
  ui_story_5028_50281201_61_dialog_content = "Meu Kylo! Maravilhoso, você está ileso!",
  ui_story_5028_50281201_62_dialog_content = "A primeira fase do nosso plano foi um sucesso impressionante.",
  ui_story_5028_50281201_63_dialog_content = "Agora é hora de encontrar e parar Gary.",
  ui_story_5028_50281201_64_dialog_content = "Fia.",
  ui_story_5028_50281201_65_dialog_content = "Por que você está olhando assim para mim?",
  ui_story_5028_50281201_66_dialog_content = "Pare de olhar para baixo em mim!",
  ui_story_5028_50281201_67_dialog_content = "Eu não quis dizer isso!",
  ui_story_5028_50281201_68_dialog_content = "No final do dia, você ainda é uma criança.",
  ui_story_5028_50281201_69_dialog_content = "Eu te disse, eu não sou!",
  ui_story_5028_50281201_70_dialog_content = "Você deveria me chamar de extrozoologista!",
  ui_story_5028_50281201_71_dialog_content = "Multar. Um título um pouco longo, se você me perguntar, e difícil de lembrar.",
  ui_story_5028_50281201_72_dialog_content = "Ora, você...!",
  ui_story_5028_50281201_73_dialog_content = "De qualquer forma, suas ações provaram que você é mais do que igual a qualquer título.",
  ui_story_5028_50281201_74_dialog_content = "Você... cresceu.",
  ui_story_5028_50281201_75_dialog_content = "Hã?",
  ui_story_5028_50281201_76_dialog_content = "Você está... me elogiando?",
  ui_story_5028_50281201_77_dialog_content = "Posso nem sempre estar ciente dos detalhes, mas tenho talento de verdade!",
  ui_story_5028_50281201_78_dialog_content = "E eu posso descobrir qualquer coisa sobre meus companheiros!",
  ui_story_5028_50281201_79_dialog_content = "Huh! Agora você sabe que eu sou um extrozoologista muito poderoso!",
  ui_story_5028_50281201_80_dialog_content = "Não se precipite. Você fez bem, mas eu não nos consideraria iguais ainda.",
  ui_story_5028_50281201_81_dialog_content = "Para que isso aconteça, você teria que primeiro...",
  ui_story_5028_50281201_82_dialog_content = "Eu estava me perguntando sobre o que era todo aquele barulho. Eu deveria saber que vocês, idiotas arrependidos, eram os responsáveis.",
  ui_story_5028_50281201_83_dialog_content = "Ei!",
  ui_story_5028_50281201_84_dialog_content = "O bandido voltou!",
  ui_story_5028_50281201_85_dialog_content = "Ele é aquele que sequestrou você, PlayerName?",
  ui_story_5028_50281201_86_dialog_content = "Que patético da parte dele ordenar Eclipsites por aí.",
  ui_story_5028_50281201_87_dialog_content = "Huh? Eu não posso acreditar em você e eu vejo olho no olho em algo, Genevieve.",
  ui_story_5028_50281201_88_dialog_content = "\"Olho no olho\" você mesmo!",
  ui_story_5028_50281201_89_dialog_content = "Que maluco terrível. Devíamos mesmo queimar esta base em cinzas.",
  ui_story_5028_50281201_90_dialog_content = "Caramba. Sem chance. Absolutamente não.",
  ui_story_5028_50281201_91_dialog_content = "O lugar está cheio de Kyllos que Gary capturou! Seria um desastre para os Kyllos!",
  ui_story_5028_50281201_92_dialog_content = "O que é isso? Mais tolos? Sem dúvida sua, broto de feijão?",
  ui_story_5028_50281201_93_dialog_content = "Não me chame de broto de feijão!",
  ui_story_5028_50281201_94_dialog_content = "Por que todos vocês estão tão ansiosos para salvar esses brutos?",
  ui_story_5028_50281201_95_dialog_content = "Não são brutos, são nossos amigos e companheiros!",
  ui_story_5028_50281201_96_dialog_content = "Companheiros? Haha! Não, eles não são companheiros. Eles são brutos.",
  ui_story_5028_50281201_97_dialog_content = "Você acha que eles são companheiros. Sua crença é unilateral.",
  ui_story_5028_50281201_98_dialog_content = "Quando as fichas caem, um animal é apenas um animal.",
  ui_story_5028_50281201_99_dialog_content = "Apenas espere até que você não tenha mais valor para eles. Eles vão se virar contra você e te rasgar em pedaços.",
  ui_story_5028_50281201_100_dialog_content = "Você é louco! Seu maluco lunático!",
  ui_story_5028_50281201_101_dialog_content = "Ei, garoto.",
  ui_story_5028_50281201_102_dialog_content = "Meu nome é Fia!",
  ui_story_5028_50281201_103_dialog_content = "Qualquer que seja. O cara é só um maluco. Quem sabe o que o está motivando?",
  ui_story_5028_50281201_104_dialog_content = "Você não pode convencer alguém assim do erro de seus caminhos. A única persuasão que eles entendem é...",
  ui_story_5028_50281201_105_dialog_content = "Continue.",
  ui_story_5028_50281201_106_dialog_content = "Era...?",
  ui_story_5028_50281201_107_dialog_content = "Força.",
  ui_story_5028_50281201_108_dialog_content = "Uau. Esta resposta é tão Shira.",
  ui_story_5028_50281201_109_dialog_content = "Você quer lutar então?",
  ui_story_5028_50281201_110_dialog_content = "Ah! Maravilhoso.",
  ui_story_5028_50281201_111_dialog_content = "Eu tenho o prazer de derrotá-lo então, não uma, mas duas vezes. E assim será para sempre.",
  ui_story_5028_50281201_112_dialog_content = "Graaah—!!",
  ui_story_5028_50281202_1_dialog_content = "Kyllo, pegue-o!",
  ui_story_5028_50281202_2_dialog_content = "Ei!",
  ui_story_5028_50281202_3_dialog_content = "Muito lento e desajeitado para o meu gosto.",
  ui_story_5028_50281202_4_dialog_content = "Gaaah!",
  ui_story_5028_50281202_5_dialog_content = "Revy, proteja a Fia!",
  ui_story_5028_50281202_6_dialog_content = "Eu não vou deixar você se safar disso!",
  ui_story_5028_50281202_7_dialog_content = "Chicote!",
  ui_story_5028_50281202_8_dialog_content = "Que tal isso? Meus companheiros lhe mostram uma coisa ou duas?",
  ui_story_5028_50281202_9_dialog_content = "Err...",
  ui_story_5028_50281202_10_dialog_content = "Você tem truques suficientes para salvar sua pele no campo de batalha.",
  ui_story_5028_50281202_11_dialog_content = "Devo dizer que esses aurorianos me deram um bocado de problemas, não é?",
  ui_story_5028_50281202_12_dialog_content = "Que tal tentarmos isso?",
  ui_story_5028_50281202_13_dialog_content = "Seu chicote - é <color=#FFB400>brilhando</color>!",
  ui_story_5028_50281202_14_dialog_content = "Cuidado, galera!",
  ui_story_5028_50281202_15_dialog_content = "Ei... Ei...!",
  ui_story_5028_50281202_16_dialog_content = "Kyllo? Kyllo!",
  ui_story_5028_50281202_17_dialog_content = "Peko...",
  ui_story_5028_50281202_18_dialog_content = "Seu psicopata! O que é que você fez?!",
  ui_story_5028_50281202_19_dialog_content = "Tudo a seu tempo, garoto.",
  ui_story_5028_50281202_20_dialog_content = "Em um momento, você poderá observar seus adoráveis amigos animais arrancando seu estômago do seu corpo!",
  ui_story_5028_50281202_21_dialog_content = "Eles nunca fariam isso!",
  ui_story_5028_50281202_22_dialog_content = "Ataque seu chicote!",
  ui_story_5028_50281202_23_dialog_content = "Eu sei!",
  ui_story_5028_50281202_24_dialog_content = "Ei!",
  ui_story_5028_50281202_25_dialog_content = "Eu não posso acreditar quantos Eclipsites ele tem sob seu polegar...",
  ui_story_5028_50281202_26_dialog_content = "A grande coisa sobre Eclipsites é que você pode ter quantos quiser.",
  ui_story_5028_50281202_27_dialog_content = "Mesmo que todos morram, há um suprimento infinito de novos para preencher seu lugar.",
  ui_story_5028_50281202_28_dialog_content = "Todos, agora!",
  ui_story_5028_50281202_29_dialog_content = "<color=#e8d9bb>Ei!</color>",
  ui_story_5028_50281202_30_dialog_content = "Esse é o seu Kyllo chorando?",
  ui_story_5028_50281202_31_dialog_content = "<color=#e8d9bb>Ei... Ei!</color>",
  ui_story_5028_50281202_32_dialog_content = "N-Não, não é!",
  ui_story_5028_50281202_33_dialog_content = "Seus gritos estão vindo de todos ao nosso redor!",
  ui_story_5028_50281202_34_dialog_content = "Isso não é bom…",
  ui_story_5028_50281202_35_dialog_content = "Ele não estava mirando no Kyllo de Fia, mas todos os Kyllos mantidos em cativeiro em sua base!",
  ui_story_5028_50281202_36_dialog_content = "Oh céus. Isto não é bom.",
  ui_story_5028_50281202_37_dialog_content = "Não podemos ficar aqui. Alguém tem que resgatá-los!",
  ui_story_5028_50281202_38_dialog_content = "Shira!",
  ui_story_5028_50281202_39_dialog_content = "Hã?",
  ui_story_5028_50281202_40_dialog_content = "Você se considera um especialista em bestas maravilhosas, certo?",
  ui_story_5028_50281202_41_dialog_content = "Mas você está ferido. Não se preocupe com a batalha. Apenas escolte-os para fora daqui!",
  ui_story_5028_50281202_42_dialog_content = "Você está às portas da morte e, no entanto, tudo em que consegue pensar são seus preciosos amigos Kyllo?",
  ui_story_5028_50281202_43_dialog_content = "É uma maravilha que algum de vocês tenha sobrevivido até a idade adulta.",
  ui_story_5028_50281202_44_dialog_content = "Graah! Rugido!",
  ui_story_5028_50281202_45_dialog_content = "Tempo de luta, irmãos!",
  ui_story_5028_50281202_46_dialog_content = "Argh!",
  ui_story_5028_50281202_47_dialog_content = "Vamos ver quantos consigo desta vez, um, dois, três...",
  ui_story_5028_50281202_48_dialog_content = "Eu tenho montes.",
  ui_story_5028_50281202_49_dialog_content = "Muito devagar! Eles vão ter o lugar em chamas em nenhum momento.",
  ui_story_5028_50281202_50_dialog_content = "É assim mesmo? Então vamos ver qual de nós consegue mais no menor tempo!",
  ui_story_5028_50281202_51_dialog_content = "Ei, ei!",
  ui_story_5028_50281202_52_dialog_content = "Vic nunca te contou? Bestas maravilhosas têm medo de mim.",
  ui_story_5028_50281202_53_dialog_content = "Então deixe-me assegurar-lhe, como um colega especialista, que em breve será história antiga!",
  ui_story_5028_50281202_54_dialog_content = "O quê?",
  ui_story_5028_50281202_55_dialog_content = "Vamos, Drakolion!",
  ui_story_5028_50281202_56_dialog_content = "Rugido-",
  ui_story_5028_50281202_57_dialog_content = "(Fia... chama o Drakolion.)",
  ui_story_5028_50281202_58_dialog_content = "Grr...",
  ui_story_5028_50281202_59_dialog_content = "Desculpe impor a você, mas você poderia, por favor...",
  ui_story_5028_50281202_60_dialog_content = "Ajude Shira a encontrar as outras feras maravilhosas na floresta e leve-as para longe daqui!",
  ui_story_5028_50281202_61_dialog_content = "Shira!",
  ui_story_5028_50281202_62_dialog_content = "...",
  ui_story_5028_50281202_63_dialog_content = "(Shira se aproxima lentamente do Drakolion...)",
  ui_story_5028_50281202_64_dialog_content = "...!",
  ui_story_5028_50281202_65_dialog_content = "(Maravilhoso. É aceitar a presença dela!)",
  ui_story_5028_50281202_66_dialog_content = "É real...",
  ui_story_5028_50281202_67_dialog_content = "Obrigado, \"Extrozoólogo Fia\"!",
  ui_story_5028_50281202_68_dialog_content = "Então vai logo! Agora!",
  ui_story_5028_50281202_69_dialog_content = "Hahahaha!",
  ui_story_5028_50281202_70_dialog_content = "Por que ele está rindo?",
  ui_story_5028_50281202_71_dialog_content = "É difícil acreditar no bando de idiotas que você é.",
  ui_story_5028_50281202_72_dialog_content = "Liderar algumas feras e um broto de feijão aqui tenta me impedir?",
  ui_story_5028_50281202_73_dialog_content = "Queria deixar o melhor para o final, mas só tenho que abrir uma exceção...",
  ui_story_5028_50281202_74_dialog_content = "Deixe-me mostrar-lhe porque eu sou imparável.",
  ui_story_5028_50281202_75_dialog_content = "Se revele!",
  ui_story_5028_50281202_76_dialog_content = "Ei...",
  ui_story_5028_50281202_77_dialog_content = "É a voz de um Kyllo...?",
  ui_story_5028_50281202_78_dialog_content = "Aquele Kylo?",
  ui_story_5028_50281202_79_dialog_content = "Isso não é suficiente para me assustar!",
  ui_story_5028_50281202_80_dialog_content = "Ei!",
  ui_story_5028_50281202_81_dialog_content = "Caramba-?!",
  ui_story_5028_50281202_82_dialog_content = "P-Por que todos eles se parecem com Eclipsites?",
  ui_story_5028_50281202_83_dialog_content = "E por que todos eles soam como Kyllos?",
  ui_story_5028_50281202_84_dialog_content = "Ei, ei! Ei!",
  ui_story_5028_50281202_85_dialog_content = "Essa criatura realmente é o mesmo Kyllo agora.",
  ui_story_5028_50281202_86_dialog_content = "O maior poder dos Kyllos é <color=#FFB400>metamorfose</color>.",
  ui_story_5028_50281202_87_dialog_content = "Com um pouco de incentivo, qualquer Kyllo pode se transformar na forma de qualquer criatura e usar suas habilidades.",
  ui_story_5028_50281202_88_dialog_content = "Como você deixou de fora algo tão importante!?",
  ui_story_5028_50281202_89_dialog_content = "Uh, não tinha me ocorrido mencionar isso até agora. Também não sabia que os Kyllos podiam usar essa habilidade quando aterrorizados.",
  ui_story_5028_50281202_90_dialog_content = "Em última análise, os Kyllos só o usarão para proteger um companheiro confiável.",
  ui_story_5028_50281202_91_dialog_content = "Na verdade, é mais inacreditável do que eu esperava...",
  ui_story_5028_50281202_92_dialog_content = "Este não é certamente um momento apropriado para sorrir?",
  ui_story_5028_50281202_93_dialog_content = "É assustador! Como vamos lidar com isso?",
  ui_story_5028_50281202_94_dialog_content = "É bom que você me tenha para responder a isso.",
  ui_story_5028_50281202_95_dialog_content = "Kyllos tem um forte senso de confiança e lealdade. Ganhe a confiança deles e o mundo será sua ostra.",
  ui_story_5028_50281202_96_dialog_content = "E, claro, a única coisa que pode vencer um Kyllo é outro Kyllo.",
  ui_story_5028_50281301_1_dialog_content = "Ei!",
  ui_story_5028_50281301_2_dialog_content = "Ei, ei!",
  ui_story_5028_50281301_3_dialog_content = "Droga! O que podemos fazer contra os poderes de Gary!",
  ui_story_5028_50281301_4_dialog_content = "Lute um pouco mais, por que não? Sear o terror deste dia no fundo do seu coração!",
  ui_story_5028_50281301_5_dialog_content = "... E então terei o prazer de enviar meus brutos a todos os cantos e recantos de todo o Astra.",
  ui_story_5028_50281301_6_dialog_content = "Hahahahahahahahaha!",
  ui_story_5028_50281301_7_dialog_content = "Tchau, garoto.",
  ui_story_5028_50281301_8_dialog_content = "Agora, PlayerName!",
  ui_story_5028_50281301_9_dialog_content = "Use seu poder para mostrar a esses Kyllos o quanto você acredita e confia em Fia!",
  ui_story_5028_50281301_10_dialog_content = "Huh? Meu poder?",
  ui_story_5028_50281301_11_dialog_content = "Você sabe, aquela coisa mental que você faz. Vamos, pense!",
  ui_story_5028_50281301_12_dialog_content = "(Meu poder...)",
  ui_story_5028_50281301_13_dialog_content = "(Meu único poder é a habilidade psíquica, e isso apenas ajuda as pessoas a conversarem umas com as outras.)",
  ui_story_5028_50281301_14_dialog_content = "(Falar um com o outro, mas... Fia não tem como se comunicar com o Kyllo?!)",
  ui_story_5028_50281301_15_dialog_content = "Simplificando, tente sentir os pensamentos e sentimentos de Kyllo e transferi-los para Fia.",
  ui_story_5028_50281301_16_dialog_content = "Fia cuidará do resto!",
  ui_story_5028_50281301_17_dialog_content = "Huh? Posso sentir os pensamentos de Kyllo?",
  ui_story_5028_50281301_18_dialog_content = "Claro que você pode. Nunca se esqueça de que você é um celestita!",
  ui_story_5028_50281301_19_dialog_content = "Ok, vou dar uma chance!",
  ui_story_5028_50281301_20_option_content = "Aumento de Força!",
  ui_story_5028_50281301_21_dialog_content = "Eu preciso sentir os pensamentos de Kyllo...",
  ui_story_5028_50281301_22_dialog_content = "Ei, ei! Ei!",
  ui_story_5028_50281301_23_dialog_content = "É muito medo. Há algum poder que ele não usou e... parece que está sendo impedido de usá-los.",
  ui_story_5028_50281301_24_dialog_content = "Ei! Ei!",
  ui_story_5028_50281301_25_dialog_content = "Eu sinto uma emoção que eu acho que significa que você quer proteger alguma coisa?",
  ui_story_5028_50281301_26_dialog_content = "Proteger algo? Proteger?",
  ui_story_5028_50281301_27_dialog_content = "Fia! Kyllo quer protegê-lo!",
  ui_story_5028_50281301_28_dialog_content = "O quê?!",
  ui_story_5028_50281301_29_dialog_content = "Ei, ei! Ei!",
  ui_story_5028_50281301_30_dialog_content = "Está dizendo que quer me proteger?",
  ui_story_5028_50281301_31_dialog_content = "Ei, ei! Ei, ei!",
  ui_story_5028_50281301_32_dialog_content = "Acho que está de acordo com o que você está pensando, e é muito ansioso!",
  ui_story_5028_50281301_33_dialog_content = "Ele está muito ansioso... e ele concorda...",
  ui_story_5028_50281301_34_dialog_content = "Então é isso que esse choro significa?",
  ui_story_5028_50281301_35_dialog_content = "Eu percebi! Eu finalmente percebi!",
  ui_story_5028_50281301_36_dialog_content = "Descobriu? Descobriu o quê?",
  ui_story_5028_50281301_37_dialog_content = "Graças a você, finalmente descobri o que significam os gritos de Kyllo.",
  ui_story_5028_50281301_38_dialog_content = "Em outras palavras, decodifiquei a linguagem dos Kyllos!",
  ui_story_5028_50281301_39_dialog_content = "Você fez?",
  ui_story_5028_50281301_40_dialog_content = "Lo, lo, lo! Ei, ei!",
  ui_story_5028_50281301_41_dialog_content = "O-o que está dizendo...?",
  ui_story_5028_50281301_42_dialog_content = "Está dizendo: \"Quero proteger Fia.\"",
  ui_story_5028_50281301_43_dialog_content = "Ei!",
  ui_story_5028_50281301_44_dialog_content = "Huh? Kyllo, você está dizendo que falar comigo deu a você um novo poder?",
  ui_story_5028_50281301_45_dialog_content = "Então use!",
  ui_story_5028_50281301_46_dialog_content = "Uau, o Kyllo está brilhando!",
  ui_story_5028_50281301_47_dialog_content = "O Kyllo está mudando de forma...",
  ui_story_5028_50281301_48_dialog_content = "Fia e Kyllo, usem seu novo poder para derrotar Gary!",
  ui_story_5028_50281301_49_dialog_content = "Obrigado pelo comentário. Conseguimos!",
  ui_story_5028_50281301_50_dialog_content = "Você acha que pode me vencer? Você deve estar sonhando.",
  ui_story_5028_50281301_51_dialog_content = "Vamos então, minhas criaturas. Esmague-os!",
  ui_story_5028_50281301_52_dialog_content = "*Rugindo*",
  ui_story_5028_50281301_53_dialog_content = "Ei!",
  ui_story_5028_50281302_1_dialog_content = "Vá, Kyllo, e ensine a esse homem malvado que não devemos ser intimidados!",
  ui_story_5028_50281302_2_dialog_content = "Ei!",
  ui_story_5028_50281302_3_dialog_content = "H-Como?",
  ui_story_5028_50281302_4_dialog_content = "Ei! Lo, lo, lo!",
  ui_story_5028_50281302_5_dialog_content = "Kyllo de Gary grita de dor.",
  ui_story_5028_50281302_6_dialog_content = "Kyllo...",
  ui_story_5028_50281302_7_dialog_content = "Kyllo! Vá para o chicote de Gary!",
  ui_story_5028_50281302_8_dialog_content = "Ei!!!",
  ui_story_5028_50281302_9_dialog_content = "Argh!",
  ui_story_5028_50281302_10_dialog_content = "Agora!",
  ui_story_5028_50281302_11_dialog_content = "Contemple!",
  ui_story_5028_50281302_12_dialog_content = "Queime!",
  ui_story_5028_50281302_13_dialog_content = "Chicote!",
  ui_story_5028_50281302_14_dialog_content = "Os Eclipsites estão todos derrotados!",
  ui_story_5028_50281302_15_dialog_content = "Eu tenho o último inimigo. Então realmente foi a minha vitória.",
  ui_story_5028_50281302_16_dialog_content = "Você conseguiu empinar um pouco lá, minha querida Genevieve.",
  ui_story_5028_50281302_17_dialog_content = "Mas realmente, aquele último companheiro era meu.",
  ui_story_5028_50281302_18_dialog_content = "Você acabou de bater nele com seu chicote no final, eu acho.",
  ui_story_5028_50281302_19_dialog_content = "Tiramos todos eles?",
  ui_story_5028_50281302_20_dialog_content = "Fizemos isso...?",
  ui_story_5028_50281302_21_dialog_content = "Ei!",
  ui_story_5028_50281302_22_dialog_content = "Sim!",
  ui_story_5028_50281302_23_dialog_content = "Desagradável...",
  ui_story_5028_50281302_24_dialog_content = "Todos os Kyllos foram libertados do controle de Gary!",
  ui_story_5028_50281302_25_dialog_content = "PlayerName, use seu poder para transmitir os pensamentos de Fia para aquele outro Kyllo, assim como você fez antes!",
  ui_story_5028_50281302_26_dialog_content = "Beleza!",
  ui_story_5028_50281302_27_option_content = "Aumento de Força!",
  ui_story_5028_50281302_28_dialog_content = "Você é um companheiro Kyllo?",
  ui_story_5028_50281302_29_dialog_content = "Você não precisa mais ter medo daquele homem malvado e desagradável!",
  ui_story_5028_50281302_30_dialog_content = "Nós libertamos você do controle dele. Ele nunca pode forçá-lo a fazer algo que você não quer fazer nunca mais!",
  ui_story_5028_50281302_31_dialog_content = "Você não precisa mais lutar. Venha e junte-se a nós.",
  ui_story_5028_50281302_32_dialog_content = "Sou um extrozoologista e vou protegê-lo.",
  ui_story_5028_50281302_33_dialog_content = "Lo... Lo?",
  ui_story_5028_50281302_34_dialog_content = "Ei!",
  ui_story_5028_50281302_35_dialog_content = "Não se preocupe. Eu não sou como o homem mau lá. Eu vou cuidar bem de você.",
  ui_story_5028_50281302_36_dialog_content = "...",
  ui_story_5028_50281302_37_dialog_content = "Oh céus. A crueldade de Gary é tudo que Kyllo já conheceu. Receio que isso o tenha levado a um ponto de ruptura psicológico!",
  ui_story_5028_50281302_38_dialog_content = "Temos que sair daqui imediatamente. Levará tempo para ensiná-lo outro modo de vida.",
  ui_story_5028_50281302_39_dialog_content = "Eu não vou deixar meus sonhos de justiça, de vingança, falharem por causa de um bando de tolos como você!",
  ui_story_5028_50281302_40_dialog_content = "Renda-se a mim, sua besta!",
  ui_story_5028_50281302_41_dialog_content = "O tempo de descanso acabou!",
  ui_story_5028_50281302_42_dialog_content = "Ei... Ei...!",
  ui_story_5028_50281302_43_dialog_content = "O Kyllo está constantemente gritando de dor, não é?",
  ui_story_5028_50281302_44_dialog_content = "Pare com isso, Gary!",
  ui_story_5028_50281302_45_dialog_content = "Você vai torturá-lo?",
  ui_story_5028_50281302_46_dialog_content = "Torturar?",
  ui_story_5028_50281302_47_dialog_content = "Que boa ideia!",
  ui_story_5028_50281302_48_dialog_content = "De que outra forma ele vai me temer?",
  ui_story_5028_50281302_49_dialog_content = "E se não me teme, como posso usar seu maior poder?",
  ui_story_5028_50281302_50_dialog_content = "Agora use toda a sua força para destruí-los!",
  ui_story_5028_50281302_51_dialog_content = "Ou você conhecerá a verdadeira dor em minhas mãos!",
  ui_story_5028_50281302_52_dialog_content = "Ei, ei! Ei!",
  ui_story_5028_50281302_53_dialog_content = "Ei!",
  ui_story_5028_50281302_54_dialog_content = "Oh não? O que nós fazemos? É clamar por socorro!",
  ui_story_5028_50281302_55_dialog_content = "Devemos derrotá-lo novamente?",
  ui_story_5028_50281302_56_dialog_content = "Ei!",
  ui_story_5028_50281302_57_dialog_content = "Pare com isso, Fia!",
  ui_story_5028_50281302_58_dialog_content = "O Kyllo está tremendamente fraco agora. Não sobreviverá a outro ataque.",
  ui_story_5028_50281302_59_dialog_content = "Bem, então o que você acha que devemos fazer, Mestre?",
  ui_story_5028_50281302_60_dialog_content = "Com um Kyllo tão longe, acho que depende do destino e da sorte.",
  ui_story_5028_50281302_61_dialog_content = "Eu me recuso a acreditar. Aprendi a não confiar em você!",
  ui_story_5028_50281302_62_dialog_content = "Haha! Ore por boa sorte então. Essa é sua última esperança de qualquer maneira.",
  ui_story_5028_50281302_63_dialog_content = "Agora é hora de—",
  ui_story_5028_50281302_64_dialog_content = "Sinceramente, não suporto brigar. É a pior parte disso.",
  ui_story_5028_50281302_65_dialog_content = "De onde veio isso?!",
  ui_story_5028_50281302_66_dialog_content = "Mas qualquer coisa é melhor do que deixar alguém como você ir livre!",
  ui_story_5028_50281302_67_dialog_content = "Rugido!!!",
  ui_story_5028_50281302_68_dialog_content = "Ah! Como você...",
  ui_story_5028_50281302_69_option_content = "Isso foi sorte... Virou Shira!",
  ui_story_5028_50281302_70_option_content = "Shira bate no chão e manda Gary voando com um chute!",
  ui_story_5028_50281302_71_dialog_content = "Nada a ver com sorte.",
  ui_story_5028_50281302_72_dialog_content = "Apenas uma transformação qualitativa de todos os meus esforços até agora.",
  ui_story_5028_50281302_73_dialog_content = "Shira!",
  ui_story_5028_50281302_74_dialog_content = "Foi uma sorte eu ter a previsão de dizer ao Drakolion para ajudar Shira a salvar os outros.",
  ui_story_5028_50281302_75_dialog_content = "Essa foi a chave para parar a trama de Gary!",
  ui_story_5028_50281302_76_dialog_content = "E eu estava pronto para dizer o quão maduro você cresceu...",
  ui_story_5028_50281302_77_dialog_content = "Ei...",
  ui_story_5028_50281302_78_dialog_content = "Uhh?",
  ui_story_5028_50281302_79_dialog_content = "Ei, ei?!",
  ui_story_5028_50281302_80_dialog_content = "Não consigo imaginar as torturas que esta pobre criatura sofreu sob Gary.",
  ui_story_5028_50281302_81_dialog_content = "Por que não damos um tempo?",
  ui_story_5028_50281302_82_dialog_content = "O que vamos fazer com o Sr. Inimigo Público Número Um?",
  ui_story_5028_50281302_83_dialog_content = "*Tosse*... Ugh!",
  ui_story_5028_50281302_84_dialog_content = "(Shira levanta Gary por um de seus tentáculos e o traz.)",
  ui_story_5028_50281302_85_dialog_content = "(Ela parece cheia de raiva assassina.)",
  ui_story_5028_50281302_86_dialog_content = "(Ela é assustadora!)",
  ui_story_5028_50281302_87_dialog_content = "Lo, lo, lo...",
  ui_story_5028_50281302_88_dialog_content = "Eh... Parece que... eu fui... derrotado finalmente...",
  ui_story_5028_50281302_89_dialog_content = "É melhor você me matar.",
  ui_story_5028_50281302_90_dialog_content = "Talvez fosse meu destino morrer nas mãos desses brutos, afinal.",
  ui_story_5028_50281302_91_dialog_content = "Ele é muito perigoso para viver.",
  ui_story_5028_50281302_92_dialog_content = "Acho que, para um bem maior, devemos...",
  ui_story_5028_50281302_93_dialog_content = "Digo que primeiro ouvimos nosso principal arquiteto do sucesso de hoje — vamos ouvir sua opinião, Fia. O que você acha que devemos fazer com ele?",
  ui_story_5028_50281302_94_dialog_content = "...",
  ui_story_5028_50281302_95_dialog_content = "Fia?",
  ui_story_5028_50281302_96_dialog_content = "Obviamente, devemos deixar esse homem mau apodrecer na prisão por seus crimes!",
  ui_story_5028_50281302_97_dialog_content = "Hã?",
  ui_story_5028_50281302_98_dialog_content = "Huh? Apodrecer na prisão?",
  ui_story_5028_50281302_99_dialog_content = "Não pense que vou parar de planejar a vingança depois de sair.",
  ui_story_5028_50281302_100_dialog_content = "E aí eu, a extrozoóloga Fia, vou ter que te parar de novo!",
  ui_story_5028_50281302_101_dialog_content = "Você verá o quão poderosas minhas bestas maravilhosas cresceram sob minha proteção naquele tempo—",
  ui_story_5028_50281302_102_dialog_content = "Esse será o seu maior castigo!",
  ui_story_5028_50281302_103_dialog_content = "Bem feito. Um discurso muito impressionante.",
  ui_story_5028_50281302_104_dialog_content = "Minha nossa! Você se parece com Shira. Mas você é um homem polvo?",
  ui_story_5028_50281302_105_dialog_content = "Minha nossa. Realmente dói ouvir você dizer isso.",
  ui_story_5028_50281302_106_dialog_content = "Kleken, você estar aqui significa que o Shadowlord...?",
  ui_story_5028_50281302_107_dialog_content = "O momento não poderia ter sido mais perfeito, PlayerName. Você tem em suas mãos o bandido que o Shadowlord procura.",
  ui_story_5028_50281302_108_dialog_content = "Dado o incômodo que ele tem sido, seria mais surpreendente para o Senhor das Sombras não se interessar.",
  ui_story_5028_50281302_109_dialog_content = "Muito verdade, senhora.",
  ui_story_5028_50281302_110_dialog_content = "Gary, dez anos atrás sua esposa e filho tropeçaram no território de bestas maravilhosas, onde foram tristemente mortos por um grupo de bestas maravilhosas.",
  ui_story_5028_50281302_111_dialog_content = "E a partir desse dia você se ocupou com a matança e captura de animais maravilhosos de todos os tipos.",
  ui_story_5028_50281302_112_dialog_content = "Se você tivesse se limitado a isso, o Shadowlord não teria se envolvido.",
  ui_story_5028_50281302_113_dialog_content = "Mas seus comportamentos recentes cruzaram uma linha que ameaça até a própria Umbraton.",
  ui_story_5028_50281302_114_dialog_content = "Ameaça Umbraton? Certamente não...",
  ui_story_5028_50281302_115_dialog_content = "De fato, meu caro.",
  ui_story_5028_50281302_116_dialog_content = "Muitas bestas maravilhosas escolhem morar perto de Umbraton e são um componente importante de sua defesa.",
  ui_story_5028_50281302_117_dialog_content = "As feras expulsam qualquer ameaça perigosa de seus ecossistemas, incluindo Eclipsites.",
  ui_story_5028_50281302_118_dialog_content = "A presença de Eclipsite perto de Umbraton impeliu as bestas maravilhosas a construir uma parede intangível separando Aurorianos da ameaça Eclipsite.",
  ui_story_5028_50281302_119_dialog_content = "É claro que o desaparecimento das feras exporia Umbraton a um ataque direto ao Eclipsite.",
  ui_story_5028_50281302_120_dialog_content = "Então é isso...",
  ui_story_5028_50281302_121_dialog_content = "Huh? Senhor das Sombras？",
  ui_story_5028_50281302_122_dialog_content = "Se o Senhor das Sombras é tão grande e poderoso, por que ele não interveio tantos anos atrás para proteger minha esposa e filho?",
  ui_story_5028_50281302_123_dialog_content = "No final do dia, não vivemos todos sob suas chamadas \"leis\"?",
  ui_story_5028_50281302_124_dialog_content = "O Senhor das Sombras impõe suas leis em Umbraton, mas isso para não falar da floresta.",
  ui_story_5028_50281302_125_dialog_content = "Em última análise, o respeito por seus ditames requer sua manifestação.",
  ui_story_5028_50281302_126_dialog_content = "Bah! Só se fosse tão simples.",
  ui_story_5028_50281302_127_dialog_content = "Gary.",
  ui_story_5028_50281302_128_dialog_content = "O que? Você tem mais algumas palavras de sabedoria?",
  ui_story_5028_50281302_129_dialog_content = "Ou você queria tirar sua própria chance de mim por nossa amizade de curta duração?",
  ui_story_5028_50281302_130_dialog_content = "Qualquer que seja. Eu não me importo. Não estou mudando de ideia sobre nada.",
  ui_story_5028_50281302_131_dialog_content = "Ninguém pode me parar. Ninguém!",
  ui_story_5028_50281302_132_dialog_content = "... Não é sua chamada a fazer.",
  ui_story_5028_50281302_133_dialog_content = "Treinar feras maravilhosas para matar umas às outras pode levar à extinção de toda a vida exótica neste planeta...",
  ui_story_5028_50281302_134_dialog_content = "Mesmo que o Senhor das Sombras não tivesse feito nada para impedi-lo, outros, incluindo esta senhora, teriam feito isso em seu lugar.",
  ui_story_5028_50281302_135_dialog_content = "Gary.",
  ui_story_5028_50281302_136_dialog_content = "Você sabe por que eu só tenho uma asa?",
  ui_story_5028_50281302_137_dialog_content = "Não sei. Então?",
  ui_story_5028_50281302_138_dialog_content = "Hã?",
  ui_story_5028_50281302_139_option_content = "Por quê?",
  ui_story_5028_50281302_140_dialog_content = "Percebi isso desde que nos conhecemos, mas você sempre tocava no assunto.",
  ui_story_5028_50281302_141_dialog_content = "Eu estava tão encantado com bestas maravilhosas, mesmo quando criança. Eu adorava chegar perto e pessoal com eles.",
  ui_story_5028_50281302_142_dialog_content = "Mas eu não entendia muito bem como suas mentes funcionavam na época. Então uma vez acabei irritando a besta maravilhosa errada.",
  ui_story_5028_50281302_143_dialog_content = "Ele atacou, arrancando metade da minha asa com sua mandíbula, deixando-me com isso.",
  ui_story_5028_50281302_144_dialog_content = "Veja o que eles podem fazer? E você não estava com raiva de ser tratado assim?",
  ui_story_5028_50281302_145_dialog_content = "Eu estava confuso e com raiva até que um certo amigo me mostrou algo diferente.",
  ui_story_5028_50281302_146_dialog_content = "Nós, Aurorianos, somos tão confusos e indecifráveis para as bestas maravilhosas quanto eles são para nós.",
  ui_story_5028_50281302_147_dialog_content = "Seus instintos lhes dizem para temer e duvidar de nós. A criatura atacou apenas por autodefesa quando cheguei muito perto.",
  ui_story_5028_50281302_148_dialog_content = "E não é exatamente isso que fazemos com eles às vezes também?",
  ui_story_5028_50281302_149_dialog_content = "De sua perspectiva, os aurorianos têm a mesma probabilidade de caçar ou capturá-los, ou invadir suas terras.",
  ui_story_5028_50281302_150_dialog_content = "E se meu amigo não tivesse usado seus poderes telepáticos para me ajudar a me comunicar com as criaturas...",
  ui_story_5028_50281302_151_dialog_content = "Eu poderia nunca ter tido a chance de realmente saber como eles se sentem sobre nós.",
  ui_story_5028_50281302_152_dialog_content = "Essa foi a chave que me permitiu entender e finalmente perdoá-los.",
  ui_story_5028_50281302_153_dialog_content = "Não somos os mesmos.",
  ui_story_5028_50281302_154_dialog_content = "Você decidiu perdoá-los. Isso não diz nada sobre o que eles pensam.",
  ui_story_5028_50281302_155_dialog_content = "Minha família foi assassinada!",
  ui_story_5028_50281302_156_dialog_content = "E, pelo que entendi, você começou a caçá-los na floresta sozinho depois, correto?",
  ui_story_5028_50281302_157_dialog_content = "Certo. Eu matei muitos deles. Nenhum sobreviveu.",
  ui_story_5028_50281302_158_dialog_content = "Então você matou os culpados, completa e completamente vingando-se. Então por que continuar? Por que submeter outros exóticos ao mesmo destino?",
  ui_story_5028_50281302_159_dialog_content = "Muito menos submetê-los a uma campanha de medo direcionada aos aurorianos.",
  ui_story_5028_50281302_160_dialog_content = "Obviamente para mostrar a todos que esses brutos não são como os Aurorianos e merecem morrer!",
  ui_story_5028_50281302_161_dialog_content = "Se as bestas maravilhosas fossem realmente tão horríveis quanto você pensa...",
  ui_story_5028_50281302_162_dialog_content = "E deliberadamente alvejou sua família, destruindo sua felicidade e qualquer chance de uma vida normal...",
  ui_story_5028_50281302_163_dialog_content = "Então, como você é diferente – dada a sua campanha para massacrar todos eles indiscriminadamente?",
  ui_story_5028_50281302_164_dialog_content = "...!",
  ui_story_5028_50281302_165_dialog_content = "Você ainda tem muitos anos de vida, meu velho amigo. Espero que você use o restante para realmente pensar sobre o que está fazendo.",
  ui_story_5028_50281302_166_dialog_content = "Não tenho mais nada a acrescentar, Sr. Polvo Misterioso.",
  ui_story_5028_50281302_167_dialog_content = "Oh? Você terminou?",
  ui_story_5028_50281302_168_dialog_content = "Então, por favor, ouça meu pedido.",
  ui_story_5028_50281302_169_dialog_content = "Tudo bem. Eu apreciaria se todos os presentes pudessem entregá-lo e seus subordinados ao Senhor das Sombras.",
  ui_story_5028_50281302_170_dialog_content = "O Senhor das Sombras se comprometeu a dar a este criminoso a punição devida para proteger a segurança de Umbraton.",
  ui_story_5028_50281302_171_dialog_content = "Em relação à sentença de prisão que milady mencionou, farei o meu melhor para transmitir seus desejos ao Senhor das Sombras.",
  ui_story_5028_50281302_172_dialog_content = "Não tenho objeções. E o resto de vocês?",
  ui_story_5028_50281302_173_dialog_content = "O Shadowlord pode não compartilhar nossa paixão por pesquisas exóticas, mas ele é um especialista quando se trata de punir criminosos.",
  ui_story_5028_50281302_174_dialog_content = "Vai ser difícil montar uma prisão só para ele.",
  ui_story_5028_50281302_175_dialog_content = "Tenho certeza de que o Shadowlord tem muitos lugares para colocar ameaças à sociedade.",
  ui_story_5028_50281302_176_dialog_content = "Concordo.",
  ui_story_5028_50281302_177_dialog_content = "Contanto que ele passe muito tempo na prisão, estou bem com isso!",
  ui_story_5028_50281302_178_option_content = "Você tem o seu desejo, Kleken.",
  ui_story_5028_50281302_179_option_content = "Mesmo assim muito obrigado.",
  ui_story_5028_50281302_180_dialog_content = "Então, pessoal, posso pedir sua ajuda para transportar esses bandidos de volta para Umbraton comigo?",
  ui_story_5028_50281302_181_dialog_content = "Você quer ajudar? OK, claro.",
  ui_story_5028_50281302_182_dialog_content = "Oh não. Mais uma tarefa chata.",
  ui_story_5028_50281302_183_dialog_content = "Não vejo como podemos realmente ajudar? Devemos dar as outras criaturas aqui para um profissional ou algo para ajudá-los.",
  ui_story_5028_50281302_184_dialog_content = "Sim!",
  ui_story_5028_50281302_185_dialog_content = "Eu voltarei para minha missão então. Adeus, todos.",
  ui_story_5028_50281302_186_dialog_content = "Só espero que nunca mais tenhamos que ver seu rosto triste novamente.",
  ui_story_5028_50281302_187_dialog_content = "Bem, não acho que seja a última vez que vimos Gary.",
  ui_story_5028_50281401_1_dialog_content = "O fim de todo o aborrecimento é o suficiente para agradecer.",
  ui_story_5028_50281401_2_dialog_content = "Estou impressionado como Kyllos são poderosos.",
  ui_story_5028_50281401_3_dialog_content = "E aqui eu pensei que sua referência à invencibilidade era apenas um truque para prender Gary.",
  ui_story_5028_50281401_4_dialog_content = "Eu nunca enganaria um antigo ou atual aprendiz meu, seja Gary, Shira ou Fia, meus estimados aprendizes.",
  ui_story_5028_50281401_5_dialog_content = "Ele não é intencionalmente enganador.",
  ui_story_5028_50281401_6_dialog_content = "Você vê, Shira disse isso a si mesma.",
  ui_story_5028_50281401_7_dialog_content = "Seus problemas de credibilidade são mais sobre falta de confiabilidade do que qualquer outra coisa.",
  ui_story_5028_50281401_8_dialog_content = "Shira, dói-me ao ponto das lágrimas ouvir-te dizer isso...",
  ui_story_5028_50281401_9_dialog_content = "Mas não entendo como meu Kyllo pode ter todo esse poder e ainda não usá-lo antes, mesmo em perigo?",
  ui_story_5028_50281401_10_dialog_content = "Não, espere - a coisa mais estranha é...",
  ui_story_5028_50281401_11_dialog_content = "Como podemos explicar a impressionante falta de sucesso do Mestre Vic, considerando todas as poderosas bestas maravilhosas ao seu alcance?",
  ui_story_5028_50281401_12_dialog_content = "Certo. Isso é realmente estranho!",
  ui_story_5028_50281401_13_dialog_content = "...",
  ui_story_5028_50281401_14_dialog_content = "Puxa... Deixe-me.",
  ui_story_5028_50281401_15_dialog_content = "Kyllo é uma espécie muito especial com habilidades únicas.",
  ui_story_5028_50281401_16_dialog_content = "No entanto, essas habilidades são implantadas apenas em conversas com outras criaturas que compartilham um vínculo de confiança.",
  ui_story_5028_50281401_17_dialog_content = "Infelizmente, como o número de Kyllos diminuiu, também diminuiu sua capacidade de se comunicar.",
  ui_story_5028_50281401_18_dialog_content = "E dada a extraordinária variedade de características de Kyllo e diferenças na linguagem corporal, tornou-se quase impossível para os outros obter uma compreensão precisa.",
  ui_story_5028_50281401_19_dialog_content = "É por isso que tão poucos aurorianos podem se comunicar com os Kyllos.",
  ui_story_5028_50281401_20_dialog_content = "Às vezes, até os próprios Kyllos lutam para compreender o significado dos gritos um do outro.",
  ui_story_5028_50281401_21_dialog_content = "Tudo isso aumentou severamente a taxa de mortalidade infantil entre Kyllos na natureza.",
  ui_story_5028_50281401_22_dialog_content = "Na verdade, todos os Kyllos que você observou naquele habitat foram criados pessoalmente até a idade adulta por Vic.",
  ui_story_5028_50281401_23_dialog_content = "O Mestre é tão brilhante?",
  ui_story_5028_50281401_24_dialog_content = "Então, se os Kyllos não podem se comunicar conosco, como o Mestre descobriu tudo isso?",
  ui_story_5028_50281401_25_dialog_content = "Há um método que pode permitir que alguém entenda o que um Kyllo está realmente e verdadeiramente pensando, e isso é...",
  ui_story_5028_50281401_26_option_content = "Eu?",
  ui_story_5028_50281401_27_dialog_content = "Especificamente, a habilidade psíquica dos celestitas.",
  ui_story_5028_50281401_28_option_content = "Caelestitas...?",
  ui_story_5028_50281401_29_dialog_content = "Sim.",
  ui_story_5028_50281401_30_dialog_content = "As habilidades psíquicas dos celestitas são capazes de superar diretamente a barreira da linguagem e perceber os pensamentos de Kyllos.",
  ui_story_5028_50281401_31_dialog_content = "Essa compreensão forma a chave para decodificar a relação entre os gritos e pensamentos de Kyllo e, em seguida, a própria linguagem.",
  ui_story_5028_50281401_32_dialog_content = "Foi quando finalmente descobri seu talento especial, Fia, quando você conseguiu entendê-los tão rapidamente.",
  ui_story_5028_50281401_33_dialog_content = "E é por isso que a primeira tarefa que meu mestre me deu foi capturar um celestita, certo?",
  ui_story_5028_50281401_34_dialog_content = "Correto. \"Comunicação\" é o fator mais importante necessário para desbloquear o verdadeiro potencial de Kyllo.",
  ui_story_5028_50281401_35_dialog_content = "Então, como eu pude entender o que Kyllo estava dizendo também?",
  ui_story_5028_50281401_36_dialog_content = "Por causa de todas as suas viagens juntos, suspeito que Kyllo o considerava um amigo.",
  ui_story_5028_50281401_37_dialog_content = "Mas então como o Kyllo de Gary usou o mesmo poder?",
  ui_story_5028_50281401_38_dialog_content = "Não tenho certeza.",
  ui_story_5028_50281401_39_dialog_content = "Suponho que pode ser um efeito do chicote.",
  ui_story_5028_50281401_40_dialog_content = "Aquele chicote terrível é capaz de subjugar a mente de uma besta maravilhosa com uma impressão terrível.",
  ui_story_5028_50281401_41_dialog_content = "O medo é igual e o extremo oposto do amor. O terror extremo de Kyllo desbloqueou uma terrível metamorfose.",
  ui_story_5028_50281401_42_dialog_content = "Hum. Isso não é exatamente o que eu chamaria de \"comunicação\"!",
  ui_story_5028_50281401_43_dialog_content = "Deve ser por isso que ele não conseguiu me derrotar, um extrozoólogo, e conseguir qualquer tipo de conexão real com seu Kyllo!",
  ui_story_5028_50281401_44_dialog_content = "Você acha que Vic estava ciente de tudo isso o tempo todo?",
  ui_story_5028_50281401_45_dialog_content = "Não necessariamente.",
  ui_story_5028_50281401_46_dialog_content = "Ele teve um amigo celestita uma vez.",
  ui_story_5028_50281401_47_dialog_content = "Esse amigo o ajudou a se comunicar com sucesso com Kyllo e a entender mais sobre essas criaturas magníficas.",
  ui_story_5028_50281401_48_dialog_content = "Até dezessete anos atrás.",
  ui_story_5028_50281401_49_dialog_content = "Espere, Vic sempre se descreveu como um \"eterno 18 anos\"?",
  ui_story_5028_50281401_50_dialog_content = "Exatamente quantos anos ele tem então?",
  ui_story_5028_50281401_51_dialog_content = "Tosse, tudo bem então. Não vamos mergulhar no passado o dia todo, vamos?",
  ui_story_5028_50281401_52_dialog_content = "Acho que temos algumas coisas para fazer aqui.",
  ui_story_5028_50281401_53_dialog_content = "Ei! Ei!",
  ui_story_5028_50281401_54_dialog_content = "O que é isso? Quer que eu olhe?",
  ui_story_5028_50281401_55_dialog_content = "Lo... Lo...",
  ui_story_5028_50281401_56_dialog_content = "A sua... A sua situação deteriorou-se rapidamente.",
  ui_story_5028_50281401_57_dialog_content = "Oh céus. Deve ser resultado de viver sob um regime de puro terror e sofrimento por tanto tempo.",
  ui_story_5028_50281401_58_dialog_content = "Foi gravemente ferido na batalha agora mesmo. Temo que sua vida esteja se esvaindo.",
  ui_story_5028_50281401_59_dialog_content = "Alguém aqui é capaz de curá-lo com Luminatics?",
  ui_story_5028_50281401_60_dialog_content = "...",
  ui_story_5028_50281401_61_dialog_content = "Rápido! É melhor encontrarmos alguém que possa nos ajudar em Umbraton! Deve haver tempo!",
  ui_story_5028_50281401_62_dialog_content = "Drakolion, ajude-nos!",
  ui_story_5028_50281401_63_dialog_content = "Sem tempo, sem tempo!",
  ui_story_5028_50281401_64_dialog_content = "Ei!",
  ui_story_5028_50281401_65_dialog_content = "Huh? K-Kyllo?!",
  ui_story_5028_50281401_66_dialog_content = "Ei! Ei! Ei!",
  ui_story_5028_50281401_67_dialog_content = "São todos os Kyllos que acabei de lançar...",
  ui_story_5028_50281401_68_dialog_content = "Eles voltaram?",
  ui_story_5028_50281401_69_dialog_content = "Ei! Ei, ei!",
  ui_story_5028_50281401_70_dialog_content = "Quer dizer, se eu puder me comunicar com eles, eles vão nos ajudar?",
  ui_story_5028_50281401_71_dialog_content = "OK eu vou tentar!",
  ui_story_5028_50281401_72_dialog_content = "Ouça-me, oh Kyllos, ajude-nos a salvá-lo!",
  ui_story_5028_50281401_73_dialog_content = "Ajude-nos...",
  ui_story_5028_50281401_74_dialog_content = "Ajude...",
  ui_story_5028_50281401_75_dialog_content = "Ei!",
  ui_story_5028_50281401_76_dialog_content = "Lo, lo, lo!",
  ui_story_5028_50281401_77_dialog_content = "É a mesma luminescência que cercou o Kyllo de Fia na batalha!",
  ui_story_5028_50281401_78_dialog_content = "É melhor você sentar e assistir.",
  ui_story_5028_50281401_79_dialog_content = "Você pode estar em uma experiência única na vida.",
  ui_story_5028_50281401_80_dialog_content = "O Caelestite ajuda Fia a se comunicar com os Kyllos para desbloquear seu poder extraordinário...",
  ui_story_5028_50281401_81_dialog_content = "Lo, lo, lo—",
  ui_story_5028_50281401_82_dialog_content = "A luz do Kyllos envolve o Kyllo ferido...",
  ui_story_5028_50281401_83_dialog_content = "Suas feridas — está cicatrizando!",
  ui_story_5028_50281401_83X_dialog_content = "É assim que Kyllo é poderoso!",
  ui_story_5028_50281401_84_dialog_content = "Ser capaz de imitar as habilidades de outras bestas maravilhosas e Aurorianos...",
  ui_story_5028_50281401_85_dialog_content = "\"Extraordinário\" não é exagero.",
  ui_story_5028_50281401_86_dialog_content = "Parece que eu não estava muito errado quando disse que \"o mundo seria sua ostra\".",
  ui_story_5028_50281401_87_dialog_content = "Entendo...",
  ui_story_5028_50281401_88_option_content = "Incrível.",
  ui_story_5028_50281401_89_dialog_content = "Você não é tão ruim mesmo, PlayerName.",
  ui_story_5028_50281401_90_dialog_content = "Hã?",
  ui_story_5028_50281401_91_option_content = "estou com um pouco de inveja...",
  ui_story_5028_50281401_92_dialog_content = "Eu faria um trabalho muito melhor protegendo meus amigos se tivesse esse tipo de poder...",
  ui_story_5028_50281401_93_dialog_content = "Você tem muito poder como é – o poder da comunicação perfeita entre indivíduos divergentes.",
  ui_story_5028_50281401_94_dialog_content = "Pode não ser muito em combate, mas não subestime o poder de ajudar as pessoas a se entenderem.",
  ui_story_5028_50281401_95_dialog_content = "O poder de dissipar equívocos, desvendar velhos ódios e impedir que as brigas comecem.",
  ui_story_5028_50281401_96_dialog_content = "Entendo...",
  ui_story_5028_50281401_97_dialog_content = "Sim!",
  ui_story_5028_50281401_98_dialog_content = "Olha, esse Kyllo parece ter recuperado sua força.",
  ui_story_5028_50281401_99_dialog_content = "Lo... Lo?",
  ui_story_5028_50281401_100_dialog_content = "Você está curado!",
  ui_story_5028_50281401_101_dialog_content = "Todos trabalhando juntos te curaram!",
  ui_story_5028_50281401_102_dialog_content = "Ei, ei! Ei!",
  ui_story_5028_50281401_103_dialog_content = "Ah, e também graças ao seu extrozoologista residente!",
  ui_story_5028_50281401_104_dialog_content = "Lo, lo, lo!",
  ui_story_5028_50281401_105_dialog_content = "Uau! Haha, isso faz cócegas!",
  ui_story_5028_50281401_106_dialog_content = "De qualquer forma, acho que já passou da hora de sairmos e levarmos essas criaturas para um habitat muito mais adequado.",
  ui_story_5028_50281401_107_dialog_content = "Huh? Kyllo vai voltar?",
  ui_story_5028_50281401_108_dialog_content = "Ei!",
  ui_story_5028_50281401_109_dialog_content = "Você está... Você vai me deixar, Kyllo?",
  ui_story_5028_50281401_110_dialog_content = "Você não acha que poderia ficar?",
  ui_story_5028_50281401_111_dialog_content = "Ei...",
  ui_story_5028_50281401_112_dialog_content = "Lo-woo!",
  ui_story_5028_50281401_113_dialog_content = "Y-Você não acha? B-Mas...",
  ui_story_5028_50281401_114_dialog_content = "Ainda uma criança, no final do dia.",
  ui_story_5028_50281401_115_dialog_content = "Um pesquisador puro deve não apenas entender, mas também respeitar os hábitos e desejos instintivos das criaturas que observam.",
  ui_story_5028_50281401_116_dialog_content = "Você não pode impor sua vontade às bestas maravilhosas.",
  ui_story_5028_50281401_117_dialog_content = "Eu não sou uma criança!",
  ui_story_5028_50281401_118_dialog_content = "Ei!",
  ui_story_5028_50281401_119_dialog_content = "Aqui...",
  ui_story_5028_50281401_120_dialog_content = "O poder da coruja Lutumi. Você conseguiu... uau.",
  ui_story_5028_50281401_121_dialog_content = "Ei! Ei!",
  ui_story_5028_50281401_122_dialog_content = "Caramba. Você está partindo tão cedo?",
  ui_story_5028_50281401_123_dialog_content = "Fia não vai ficar feliz quando acordar depois de se despedir de tantos companheiros.",
  ui_story_5028_50281401_124_dialog_content = "Certifique-se de confortá-la. Essas coisas podem ser difíceis e irritantes.",
  ui_story_5028_50281401_125_dialog_content = "Não tenho muita experiência com crianças. Posso importunar meu estimado aprendiz para lidar com isso?",
  ui_story_5028_50281401_126_dialog_content = "Hum...",
  ui_story_5028_50281401_127_dialog_content = "Certifique-se de cuidar bem uns dos outros!",
  ui_story_5028_50281401_128_dialog_content = "E fique longe de pessoas que parecem más notícias.",
  ui_story_5028_50281401_129_dialog_content = "Ei!",
  ui_story_5028_50281401_130_dialog_content = "Bem, esse é o fim da história.",
  ui_story_5028_50281401_131_dialog_content = "Os Kyllo e seus irmãos moram nessa mesma floresta até hoje.",
  ui_story_5028_50281401_132_dialog_content = "A garota chamada Fia realmente cresceu e se tornou uma renomada extrozoóloga.",
  ui_story_5028_50281401_133_dialog_content = "Um final feliz pra todo mundo.",
  ui_story_5028_50281401_134_dialog_content = "Então o que aconteceu?",
  ui_story_5028_50281401_135_dialog_content = "Em qualquer caso, Vice, deixe-me descansar um pouco primeiro, sim?",
  ui_story_5028_50281401_136_dialog_content = "Estou lendo \"As Aventuras do Extrozoólogo\" há 3 horas.",
  ui_story_5028_50281401_137_dialog_content = "Minha garganta está ficando rouca.",
  ui_story_5028_50281401_138_dialog_content = "Oh, desculpe. É melhor descansar então.",
  ui_story_5028_50281401_139_dialog_content = "Mas estou realmente entrando nisso! Não podemos terminar aqui.",
  ui_story_5028_50281401_140_dialog_content = "Eu realmente quero saber o que aconteceu em seguida.",
  ui_story_5028_50281401_141_dialog_content = "Ou você pode simplesmente perguntar à senhora que escreveu o livro, ela deve...",
  ui_story_5028_50281401_142_dialog_content = "PlayerName!",
  ui_story_5028_50281401_143_dialog_content = "Olha, lá está ela!",
  ui_story_5028_50281401_144_dialog_content = "Eu quero ir à procura de bestas maravilhosas amanhã à beira-mar!",
  ui_story_5028_50281401_145_dialog_content = "E como você é um exótico, celestita, não aceitarei um não como resposta!",
  ui_story_5028_50281401_146_dialog_content = "Tudo bem, tudo bem. Já lhe disse algumas vezes, que não sou uma fera maravilhosa...",
  ui_story_5028_50281401_147_dialog_content = "Você nega? Que pena. Um pouco tarde para isso agora.",
  ui_story_5028_50281401_148_dialog_content = "E, como seu \"mestre extrozoólogo\", não posso simplesmente deixar você fugindo!",
  ui_story_5028_50281401_149_dialog_content = "Você realmente quer pegar uma carona em Soroz, não é!",
  ui_story_5028_50281401_150_dialog_content = "E esse Drakolion parece que está chegando também!",
  ui_story_5028_50281401_151_dialog_content = "Você tem que pensar em uma maneira de devolvê-lo onde precisa ir!",
  ui_story_5028_50281401_152_dialog_content = "Confie em mim, a Soroz não vai atender a nenhum pedido de parceria!",
  ui_story_5028_50281401_153_dialog_content = "Eu não disse isso? Drakolion voltará após a temporada de acasalamento.",
  ui_story_5028_50281401_154_dialog_content = "O respeito pelos animais maravilhosos, seus hábitos e esperanças, é fundamental para qualquer extrozoólogo que se preze.",
  ui_story_5028_50281401_155_dialog_content = "Eu não vou forçá-lo de volta, isso é certo!",
  ui_story_5028_50281401_156_dialog_content = "Bem dito - desta vez.",
  ui_story_5028_50281401_157_dialog_content = "Deus sabe quanto tempo você choraria se Kyllo não voltasse!",
  ui_story_5028_50281401_158_dialog_content = "Licença?",
  ui_story_5028_50281401_159_dialog_content = "Eu não me lembro disso!",
  ui_story_5028_50281401_160_dialog_content = "Vamos! Admite!",
  ui_story_5028_50281401_161_dialog_content = "Ei!",
  ui_story_5028_50281401_162_dialog_content = "Kyllo, morda-o!",
  ui_story_5028_50281401_163_dialog_content = "Lo—Oowoo!",
  ui_story_5028_50281401_164_dialog_content = "Grrr!",
  ui_story_5028_50281401_165_dialog_content = "Minha perna!",
  ui_story_5028_50281401_166_dialog_content = "Pfft!",
  ui_story_5028_50281401_167_dialog_content = "Você não pode ser muito direto com as crianças, PlayerName.",
  ui_story_5028_50281401_168_dialog_content = "Vice, venha me ajudar!",
  ui_story_5028_50281401_169_dialog_content = "Ajude-me a tirar Kyllo da minha perna!",
  ui_story_5028_50281401_170_dialog_content = "Tudo bem, tudo bem. Liberar PlayerName, OK?",
  ui_story_5028_50281401_171_dialog_content = "Ei!",
  ui_story_5028_50281401_172_dialog_content = "Huh! Os extrozoólogos têm todo o poder, não têm?",
  ui_story_5028_50281401_173_dialog_content = "Minha perna... As marcas de mordida de Kyllo estão nela!",
  ui_story_5028_50281401_174_dialog_content = "Aguentar. O Kyllo foi embora. Eu me lembro disso claramente. Como é que ainda está rondando Fia?",
  ui_story_5028_50281401_175_dialog_content = "Um especialista na minha área tem um carisma tremendo do qual você sabe pouco. Meu Kyllo finalmente voltou.",
  ui_story_5028_50281401_176_dialog_content = "Lo, lo, lo-lo!",
  ui_story_5028_50281401_177_dialog_content = "Oh? Kyllo está tentando nos dizer alguma coisa?",
  ui_story_5028_50281401_178_dialog_content = "Oh? Não entendi muito bem isso, Kyllo. O que você estava dizendo? Você poderia se repetir?",
  ui_story_5028_50281401_179_dialog_content = "Lo, lo, lo...",
  ui_story_5028_50281401_180_dialog_content = "\"Porque eu estava preocupado com o bem-estar de Fia?\"",
  ui_story_5028_50281401_181_dialog_content = "\"Eu pensei em todos os dias que Fia estaria chorando na minha ausência...\"",
  ui_story_5028_50281401_182_dialog_content = "\"Eu estava tão preocupado com a saúde dela que tive que voltar...\"",
  ui_story_5028_50281401_183_dialog_content = "É assim mesmo?!",
  ui_story_5028_50281401_184_dialog_content = "Ei! Ei! Ei!",
  ui_story_5028_50281401_185_dialog_content = "Ahhh! Kyllo!",
  ui_story_5028_50281401_186_dialog_content = "Para!",
  ui_story_5028_50281401_187_dialog_content = "... E com isso devemos fechar as cortinas deste conto.",
  ui_story_5028_50281401_188_dialog_content = "... Tendo em mente que não pode haver fim para as muitas aventuras de um verdadeiro extrozoólogo."
}
return config
